def _resolve_secret_key():
    """Resolve a stable secret key.

    Priority:
      1. SECRET_KEY environment variable (recommended for production).
      2. A persisted key file inside the instance folder. This guarantees
         that every gunicorn/uWSGI worker AND every restart share the SAME
         key, so sessions and CSRF tokens stay valid. (A per-process random
         key silently breaks logins under multi-worker servers.)
    A loud warning is logged the first time a key has to be generated so the
    operator knows to set SECRET_KEY explicitly in production.
    """
    env_key = os.environ.get("SECRET_KEY")
    if env_key:
        return env_key

    base_dir = os.path.dirname(os.path.abspath(__file__))
    instance_dir = os.path.join(base_dir, "instance")
    os.makedirs(instance_dir, exist_ok=True)
    key_path = os.path.join(instance_dir, "secret_key")

    if os.path.exists(key_path):
        with open(key_path, "r", encoding="utf-8") as fh:
            stored = fh.read().strip()
        if stored:
            return stored

    generated = secrets.token_hex(32)
    try:
        with open(key_path, "w", encoding="utf-8") as fh:
            fh.write(generated)
        os.chmod(key_path, 0o600)
    except OSError:
        pass  # read-only FS — fall back to the in-memory key
    logging.getLogger(__name__).warning(
        "SECRET_KEY not set — generated and persisted one in instance/secret_key. "
        "Set the SECRET_KEY environment variable for production deployments."
    )
    return generated


app.secret_key = _resolve_secret_key()
