def _anon_chat_name(db, raw):
    name = sanitise(str(raw or ""), 60).strip() or "Anónimo"
    flat = re.sub(r"[^a-z0-9]", "", name.lower()
                  .translate(str.maketrans("áéíóúüñ", "aeiouun")))
    taken = db.execute("SELECT 1 FROM users WHERE lower(name)=lower(?) OR lower(username)=lower(?)",
                       (name, name)).fetchone()
    if taken or any(r in flat for r in _RESERVED_CHAT):
        name = name[:44] + " (sin verificar)"
    return name


def sanitise_dict(d: dict, fields: list, max_len: int = 2000) -> dict:
    return {k: sanitise(d.get(k, ""), max_len) for k in fields}

# ── Role-based access control ─────────────────────────────────
def _rol_actual():
    """Rol vigente de quien pide, leído de la base de datos (no de la sesión),
    para que retirar un permiso tenga efecto inmediato. 'anon' si no hay cuenta."""
    if not session.get("user_id"):
        return "anon"
    r = get_db().execute("SELECT role FROM users WHERE id=?", (session["user_id"],)).fetchone()
    return r[0] if r else "anon"

def require_role(*roles):
    """Decorator: require user to be logged in with one of the given roles."""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            user_role = "anon"
            if session.get("user_id"):
                r = get_db().execute("SELECT role FROM users WHERE id=?",
                                     (session["user_id"],)).fetchone()
                user_role = r[0] if r else "anon"
                session["role"] = user_role
            if user_role not in roles:
                return jsonify({"status": "error", "message": "Acceso no autorizado"}), 403
            return f(*args, **kwargs)
        return wrapper
    return decorator

# ── Security headers ──────────────────────────────────────────
@app.after_request
def add_security_headers(response):
    response.headers["X-Content-Type-Options"]  = "nosniff"
    response.headers["X-Frame-Options"]          = "SAMEORIGIN"
    response.headers["X-XSS-Protection"]         = "1; mode=block"
    response.headers["Referrer-Policy"]          = "strict-origin-when-cross-origin"
    if IS_PRODUCTION:
        response.headers["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
    # Content Security Policy
    csp = (
        "default-src 'self'; "
        # blob: y mediastream: son los orígenes de una pista de audio
        # recibida por WebRTC. Sin declararlos, la voz del otro extremo
        # llega y el navegador se niega a reproducirla.
        "media-src 'self' blob: mediastream:; "
        "script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://unpkg.com https://fonts.googleapis.com https://public.tableau.com; "
        "style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://fonts.googleapis.com https://fonts.gstatic.com; "
        "img-src 'self' data: blob: https://images.unsplash.com https://via.placeholder.com "
        "https://*.tile.openstreetmap.org https://*.basemaps.cartocdn.com "
        "https://tiles.openfreemap.org https://public.tableau.com "
        # Relatos en el mapa: mapa topográfico (ríos y relieve).
        "https://*.tile.opentopomap.org "
        # Miniaturas de los videos de YouTube enlazados en una contribución.
        "https://i.ytimg.com; "
        "font-src 'self' https://fonts.gstatic.com; "
        # El mapa vectorial descarga por fetch su hoja de estilo, sus teselas,
        # sus tipografías y su hoja de iconos. Sin este permiso el navegador las
        # bloquea en silencio y el mapa queda en blanco: no falla, simplemente
        # no aparece, que es la forma más difícil de diagnosticar.
        "connect-src 'self' https://*.tile.openstreetmap.org "
        "https://*.basemaps.cartocdn.com https://tiles.openfreemap.org https://*.tile.opentopomap.org "
        # El service worker guarda las bibliotecas y las fuentes para usarlas
        # sin conexión; sin estos orígenes su instalación fallaba en silencio.
        "https://cdnjs.cloudflare.com https://unpkg.com https://fonts.googleapis.com "
        "https://fonts.gstatic.com https://i.ytimg.com; "
        # MapLibre descomprime y tesela en hilos aparte, creados desde una URL
        # blob:. Con worker-src heredando default-src 'self' esos hilos no
        # arrancan y la librería se carga entera para no dibujar nada.
        "worker-src 'self' blob:; "
        "child-src 'self' blob:; "
        # Reproductores de YouTube (dominio sin cookies) y Vimeo. Sólo se
        # cargan cuando la persona pulsa «reproducir» en el recuadro del video.
        "frame-src 'self' https://public.tableau.com https://*.tableau.com "
        "https://www.youtube-nocookie.com https://www.youtube.com "
        "https://player.vimeo.com; "
        "frame-ancestors 'self';"
    )
    response.headers["Content-Security-Policy"] = csp
    return response

# ── Error handlers ────────────────────────────────────────────
@app.errorhandler(404)
def not_found(e):
    if request.path.startswith("/api/"):
        return jsonify({"status": "error", "message": "Endpoint no encontrado"}), 404
    return jsonify({"status": "error", "message": "Página no encontrada"}), 404

@app.errorhandler(413)
def too_large(e):
    return jsonify({"status": "error", "message": "Archivo demasiado grande (máximo 16 MB; "
                    "los videos se suben por partes hasta 400 MB)"}), 413

@app.errorhandler(429)
def too_many(e):
    return jsonify({"status": "error", "message": "Demasiadas solicitudes"}), 429

@app.errorhandler(500)
def server_error(e):
    logger.error(f"Internal server error: {e}")
    return jsonify({"status": "error", "message": "Error interno del servidor"}), 500

