# ── LUGARES DE UNA CONTRIBUCIÓN ──────────────────────────────
# Una contribución puede venir de uno de los 7 territorios NARP, de
# cualquiera de los 33 departamentos o de cualquier ciudad marcada en el
# mapa. Todas se guardan con un territorio (el territorio NARP o el
# departamento, para que filtros y resúmenes sigan funcionando) y con las
# coordenadas del lugar, para que aparezcan en el mapa donde ocurrieron.
_NARP_CITY = {"cali": "cali", "cartagena": "cartagena", "buenaventura": "buenaventura",
              "tumaco": "tumaco", "sanandres": "sanandres", "quibdo": "choco"}
_DEPT_BY_SLUG = {d["slug"]: d for d in DEPARTMENTS}


def _dept_slug_for_city(c):
    if _slugify(c["name"]).startswith("bogota"):
        return "bogota"
    cd = _slugify(c["dept"])
    for d in DEPARTMENTS:
        dn = _slugify(d["name"].split(" (")[0])
        if d["slug"] == "bogota":
            continue
        if dn == cd or dn.startswith(cd) or cd.startswith(dn):
            return d["slug"]
    return ""


def _dept_center(slug):
    """Coordenadas de la capital del departamento (o de Bogotá)."""
    if slug in ("bogota", "cundinamarca"):
        c = next(c for c in CITIES if c["slug"].startswith("bogota"))
        return c["lat"], c["lon"]
    for c in CITIES:                       # las capitales van primero en CITIES
        if _dept_slug_for_city(c) == slug:
            return c["lat"], c["lon"]
    return None, None


def resolve_place(value):
    """'choco' | 'antioquia' | 'dep:antioquia' | 'city:medellin' →
    (territory_slug, lat, lon, place_name), o None si no es un lugar válido."""
    v = (value or "").strip()
    if v in TERRITORIES:
        t = TERRITORIES[v]
        return v, t["lat"], t["lon"], ""
    if v.startswith("dep:"):
        v = v[4:]
    if v in _DEPT_BY_SLUG:
        lat, lon = _dept_center(v)
        return v, lat, lon, ""
    if v.startswith("city:"):
        c = next((c for c in CITIES if c["slug"] == v[5:]), None)
        if not c:
            return None
        ter = _NARP_CITY.get(c["slug"]) or _dept_slug_for_city(c)
        return ter, c["lat"], c["lon"], c["name"]
    return None


