def otras_cifras_oficiales():
    load_official_indicators()
    # Una cifra que ya ocupa la celda principal como complemento no se repite aquí.
    out = [c for c in OTRAS_CIFRAS_OFICIALES
           if not (TERRITORIES.get(c["territory"], {}).get(c["field"] + "_complemento")
                   and TERRITORIES.get(c["territory"], {}).get(c["field"]) == c["value"])]
    # Último mes aprobado de la desocupación por ciudad (R5), si no ocupa ya la celda.
    if dane_auto is not None and os.path.exists(DB_PATH):
        try:
            con = dane_auto.conectar(DB_PATH)
            try:
                for ter in TERRITORIES:
                    v = dane_auto.ventana(con, ter)
                    u = v[-1] if v else None      # solo el mes más reciente, nunca uno anterior
                    if u and u.get("value") is not None and TERRITORIES[ter].get("unemployment_origen") != "aprobado_mensual":
                        out.append({"territory": ter, "field": "unemployment", "value": u["value"],
                                    "year": u["period_label"] or u["period"], "ambito": u["ambito"],
                                    "source": u["source_label"], "url": u["source_url"]})
            finally:
                con.close()
        except Exception as e:
            logger.warning(f"otras cifras (R5): {e}")
    ruta = os.path.join(DATA_FOLDER, "otras_cifras_oficiales.csv")
    if os.path.exists(ruta):
        try:
            with open(ruta, "r", encoding="utf-8-sig") as f:
                for r in csv.DictReader(f):
                    v = _celda_oficial(r.get("value"))
                    if v is not None and r.get("territory") and r.get("field"):
                        out.append({"territory": r["territory"], "field": r["field"], "value": v,
                                    "year": r.get("year", ""), "ambito": r.get("ambito", ""),
                                    "source": r.get("source", ""), "url": r.get("url", "")})
        except Exception as e:
            logger.warning(f"otras_cifras_oficiales.csv: {e}")
    return out


def fuente_oficial(territorio, campo, por_defecto="DANE — GEIH"):
    """Rótulo «fuente año» de una celda oficial, para guardarlo junto al valor."""
    load_official_indicators()
    meta = _OFFICIAL_FICHA.get((territorio, campo))
    if not meta:
        return por_defecto
    return f"{meta.get('fuente','').split(' (')[0]} · {meta.get('ambito','')}".strip(" ·")

