def _nd_text_of(contribution: dict) -> str:
    return " ".join(str(contribution.get(k,"") or "") for k in ("title","body","tags","category")).lower()

def nd_find_candidates(contribution: dict, limit: int = 3):
    """Rule 3 (tema): keyword-overlap search over the documented indicator
    catalog. Returns candidates ranked by keyword hits — never invents a
    relationship, only surfaces ones with an explicit textual match."""
    text = _nd_text_of(contribution)
    candidates = []
    for ind in INDICATOR_CATALOG:
        hits = [kw for kw in ind["keywords"] if kw in text]
        if hits:
            candidates.append({"indicator": ind, "hits": hits,
                                "quality_hits":[q for q in ind.get("quality_keywords",[]) if q in text]})
    candidates.sort(key=lambda c: len(c["hits"]), reverse=True)
    return candidates[:limit]

def nd_evaluate(contribution: dict, community_value=None):
    """Rules 1–7 (territorio, período, tema, población, variable, unidad,
    fuente) before Rule 8 (comparación). Returns a fully-documented
    comparison payload — status is only ever 'consistent'/'divergent' when a
    real numeric community estimate was supplied by the contributor."""
    territory = (contribution.get("territory") or "").strip()
    official_by_ter = load_official_indicators()

    # Rule 1 — territorio: sin línea base DANE en la plataforma, no se compara.
    if territory not in official_by_ter:
        return {"status":"no_comparable","confidence":0.0,
                "reason":"Este territorio todavía no tiene una línea base DANE cargada en la plataforma.",
                "indicator":None,"candidates":[]}

    candidates = nd_find_candidates(contribution)
    # Rule 3 — tema: sin coincidencia temática, no hay con qué comparar.
    if not candidates:
        return {"status":"no_comparable","confidence":0.0,
                "reason":"No se identificó un indicador DANE relacionado con el tema de esta narrativa.",
                "indicator":None,"candidates":[]}

    best = candidates[0]
    ind = best["indicator"]
    official_value = official_by_ter.get(territory,{}).get(ind["field"])
    confidence = round(min(1.0, 0.35 + 0.18*len(best["hits"])), 2)
    reason = f"Mismo territorio y tema (palabras clave: {', '.join(best['hits'][:4])})."

    payload = {
        "indicator": {
            "id": ind["id"], "name": ind["name"], "field": ind["field"],
            "unit": ind["unit"], "period": ind["period"], "direction": ind["direction"],
            "universe": ind["universe"], "definition": ind["definition"],
            "source_label": ind["source_label"], "source_url": ind["source_url"],
            "official_value": official_value,
        },
        "candidates": [{"id":c["indicator"]["id"],"name":c["indicator"]["name"],"hits":c["hits"]} for c in candidates],
        "confidence": confidence, "reason": reason, "territory": territory,
    }

    # The narrative names a quality/experience dimension the indicator's own
    # definition says it does not measure (doc §6, ejemplo de Buenaventura) —
    # this is exactly the case the design calls "Complementaria" / "No capturada".
    quality_mismatch = bool(best["quality_hits"])
    not_captured_note = (
        f"El indicador «{ind['name']}» mide {ind['universe'].lower()} bajo la definición: "
        f"“{ind['definition']}”. La narrativa menciona aspectos (p. ej. {', '.join(best['quality_hits'][:3]) or 'experiencia vivida, calidad o trato'}) "
        f"que esa definición no captura."
    ) if quality_mismatch else (
        f"El indicador «{ind['name']}» es una medición agregada; no puede confirmar ni descartar "
        f"la experiencia individual descrita en la narrativa — solo aporta contexto territorial."
    )

    if community_value is None or community_value == "":
        # Rule 8 boundary: no numeric estimate supplied → no se calcula
        # ninguna diferencia. Se documenta como conocimiento no capturado.
        payload.update({"status":"not_captured","community_value":None,"difference":None,
                         "not_captured_note": not_captured_note})
        return payload

    try:
        cv = float(community_value)
    except (TypeError, ValueError):
        payload.update({"status":"not_captured","community_value":None,"difference":None,
                         "not_captured_note": not_captured_note})
        return payload

    if official_value is None:
        payload.update({"status":"not_captured","community_value":cv,"difference":None,
                         "not_captured_note":"No hay valor oficial DANE cargado para este indicador en este territorio."})
        return payload

    diff = round(cv - official_value, 2)
    payload["community_value"] = cv
    payload["difference"] = diff

    if quality_mismatch:
        # Aun con número, si la narrativa habla de calidad/trato y el
        # indicador solo mide tenencia/cobertura, no se declara "consistente"
        # ni "divergente" — se marca complementaria (doc §6, riesgo §19).
        payload["status"] = "complementary"
        payload["not_captured_note"] = not_captured_note
        return payload

    if abs(diff) <= 5:
        payload["status"] = "consistent"
    elif abs(diff) > 15:
        payload["status"] = "divergent"
    else:
        payload["status"] = "complementary"
        payload["not_captured_note"] = not_captured_note
    return payload



# ── I2: DATA PIPELINE HOOK ───────────────────────────────────

def try_run_pipeline():
    pipeline = os.path.join(BASE_DIR, "load_geih_data.py")
    if os.path.exists(pipeline):
        try:
            import subprocess
            # Use the SAME interpreter that is running the app. "python" may be
            # missing or point to the wrong version under WSGI (PythonAnywhere).
            r = subprocess.run([sys.executable or "python", pipeline],
                               capture_output=True, text=True, timeout=120)
            if r.returncode == 0:
                global _OFFICIAL_INDICATORS_CACHE
                _OFFICIAL_INDICATORS_CACHE = None  # force reload
                logger.info("Pipeline GEIH ejecutado correctamente")
                return True
            logger.warning(f"Pipeline falló: {r.stderr[:200]}")
        except Exception as e:
            logger.error(f"Error en pipeline: {e}")
    return False


# ── SIEMBRA DE LA CAPA DE EDUCACIÓN DESDE EL PIPELINE ────────
# Aquí vivía una tabla con tres indicadores y sus cifras oficiales escritas a
# mano: 7,4 años de escolaridad, 82 % de asistencia y 8,1 % de deserción,
# atribuidos a «DANE-GEIH 2020-2024» sin que ninguna corrida los hubiera
# producido. Se retiran. Las cifras oficiales se leen de las salidas de
# etl_educacion_geih.py, que declara para cada una su universo, su método y su
# manifiesto, igual que el Anexo F del documento. Tres consecuencias:
#
#   1. Ninguna cifra oficial se escribe en este archivo. Si el pipeline no ha
#      corrido, la capa queda vacía y se registra por qué, en lugar de mostrar
#      un número sin fuente verificable.
#   2. El territorio de la GEIH es el departamento. La encuesta no es
#      representativa a escala municipal fuera de las 23 ciudades del diseño
#      muestral y Buenaventura no está entre ellas, de modo que estas
#      estimaciones se siembran como «valle_del_cauca». La cifra municipal
#      viene del censo y la produce etl_educacion_cnpv.py.
#   3. El contraste comunitario se empareja por nombre exacto de indicador. Si
#      el archivo comunitario no trae el rótulo que produce el ETL, la fila se
#      siembra igual, sin columna comunitaria, y el desajuste queda en el
#      registro con los dos lados a la vista en lugar de desaparecer.

_GEIH_INDICADORES     = "educacion_indicadores_geih.csv"
# Salidas de los otros dos ETL de educación. Mismo esquema de columnas
# (territorio, indicador, valor, fuente, universo, medicion, metodo). Antes sólo
# se cargaban en local mediante scripts aparte; ahora el servidor también las lee
# de data/ al arrancar, sin procesar microdatos.
_FUENTES_EDUCACION = [
    # (archivo, territorio por defecto, fuente por defecto)
    (_GEIH_INDICADORES, "valle_del_cauca", "DANE — GEIH"),
    ("educacion_indicadores.csv", "buenaventura",
     "DANE — Censo Nacional de Población y Vivienda 2018"),
    ("educacion_indicadores_educ.csv", "buenaventura",
     "DANE–MEN — Educación Formal (EDUC) 2023"),
]
_GEIH_SERIE           = "educacion_geih_serie_anual.csv"
_GEIH_MANIFIESTO      = "geih_manifiesto.json"
_VALORES_COMUNITARIOS = "valores_comunitarios.csv"
_CAPA_EDUCACION       = "Educación"
_DOMINIO_SERIE        = "NARP — Valle del Cauca"


def _ruta_datos(nombre):
    return os.path.join(DATA_FOLDER, nombre)


def _leer_csv_datos(nombre):
    ruta = _ruta_datos(nombre)
    if not os.path.exists(ruta):
        return []
    try:
        with open(ruta, encoding="utf-8-sig", newline="") as f:
            return list(csv.DictReader(f))
    except Exception as e:
        logger.warning(f"No se pudo leer {nombre}: {e}")
        return []


def _a_float(v):
    try:
        return float(str(v).strip().replace(",", "."))
    except (TypeError, ValueError):
        return None


def _columnas_de_procedencia(cur):
    """Añade a community_indicators las columnas que el pipeline ya declara.

    Universo, método y manifiesto existen en la salida del ETL y en el Anexo F.
    Sin ellas la aplicación mostraría un número sin las tres cosas que lo hacen
    citable, que es justamente lo que el apartado 6.3 le exige a una cifra.
    """
    existentes = {f[1] for f in cur.execute("PRAGMA table_info(community_indicators)")}
    for col in ("universo", "medicion", "metodo", "manifiesto"):
        if col not in existentes:
            cur.execute(
                f"ALTER TABLE community_indicators ADD COLUMN {col} TEXT DEFAULT ''")


def _mapa_comunitario():
    """{indicador: (valor, fuente, explicación)} desde el archivo comunitario.

    Se aceptan varios nombres de columna porque ese archivo lo mantiene la
    comunidad y no el pipeline: imponerle un esquema rígido sería trasladarle el
    costo de nuestra convención.
    """
    mapa = {}
    for fila in _leer_csv_datos(_VALORES_COMUNITARIOS):
        clave = (fila.get("indicador") or fila.get("indicator") or "").strip()
        valor = _a_float(fila.get("valor_comunitario") or fila.get("valor"))
        if not clave or valor is None:
            continue
        mapa[clave] = (
            valor,
            (fila.get("fuente_comunitaria") or fila.get("fuente") or "").strip(),
            (fila.get("explicacion") or fila.get("evidencia") or "").strip(),
        )
    return mapa


def sembrar_serie_geih(cur):
    """Siembra la serie anual real, un punto por año observado.

    Cinco años medidos sustituyen al par «2018 estimado + un punto». Cada punto
    va con is_estimate=1 porque los años de escolaridad se derivan del nivel y
    del último grado aprobado y no se preguntan directamente; distinguir una
    cifra derivada de una medida es parte de lo que esta plataforma reclama.
    """
    filas = _leer_csv_datos(_GEIH_SERIE)
    if not filas:
        return 0
    indicador = "Años de escolaridad promedio, población NARP de 25 años y más"
    puestos = 0
    for fila in filas:
        if (fila.get("dominio") or "").strip() != _DOMINIO_SERIE:
            continue
        anio = _a_float(fila.get("anio"))
        valor = _a_float(fila.get("escolaridad_promedio_25mas"))
        if anio is None or valor is None:
            continue
        muestra = fila.get("n_escolaridad") or "?"
        cur.execute("""INSERT OR IGNORE INTO official_timeseries
            (territory,indicator,layer,year,value,source_type,source_label,is_estimate)
            VALUES (?,?,?,?,?,?,?,?)""",
            ("valle_del_cauca", indicador, _CAPA_EDUCACION, int(anio), valor,
             "geih",
             f"DANE — GEIH {int(anio)}, microdatos anonimizados · n={muestra}", 1))
        puestos += cur.rowcount or 0
    return puestos


def sembrar_educacion_geih():
    """Siembra la capa de educación desde las salidas del pipeline.

    Idempotente: omite los indicadores que ya existen por (territorio, nombre).
    Si el pipeline no ha corrido, no inventa nada y lo dice.
    """
    indicadores = []
    for archivo, ter_def, fuente_def in _FUENTES_EDUCACION:
        filas = _leer_csv_datos(archivo)
        if not filas:
            logger.info("Capa de educación: %s no está en data/ (se omite).", archivo)
        for f in filas:
            indicadores.append((f, ter_def, fuente_def))
    if not indicadores:
        logger.warning(
            "Capa de educación no sembrada: no hay CSV de educación en data/. "
            "Ejecuta los ETL en local y sube sus salidas; la aplicación no "
            "fabrica cifras oficiales.")
        return 0

    comunitarios = _mapa_comunitario()
    manifiesto = _GEIH_MANIFIESTO if os.path.exists(_ruta_datos(_GEIH_MANIFIESTO)) else ""
    sin_contraste, insertados = [], 0
    try:
        con = sqlite3.connect(DB_PATH, timeout=15)
        cur = con.cursor()
        if not cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='community_indicators'"
        ).fetchone():
            con.close()
            return 0
        _columnas_de_procedencia(cur)

        for fila, ter_def, fuente_def in indicadores:
            territorio = (fila.get("territorio") or ter_def).strip()
            nombre = (fila.get("indicador") or "").strip()
            valor = _a_float(fila.get("valor"))
            if not nombre or valor is None:
                continue
            if cur.execute(
                "SELECT id FROM community_indicators WHERE territory=? AND indicator=?",
                (territorio, nombre)
            ).fetchone():
                continue

            com_valor, com_fuente, com_texto = comunitarios.get(nombre, (None, "", ""))
            if com_valor is None:
                sin_contraste.append(nombre)
                diferencia, direccion = None, ""
            else:
                diferencia = round(com_valor - valor, 2)
                direccion = "undercount" if diferencia > 0 else "overcount"

            cur.execute("""
                INSERT INTO community_indicators
                    (territory, indicator, layer, official_value, official_source,
                     community_value, community_source, difference, direction,
                     evidence_body, validated, universo, medicion, metodo, manifiesto)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                territorio, nombre, _CAPA_EDUCACION, valor,
                (fila.get("fuente") or fuente_def).strip(),
                com_valor, com_fuente, diferencia, direccion, com_texto, 0,
                (fila.get("universo") or "").strip(),
                (fila.get("medicion") or "estimada").strip(),
                (fila.get("metodo") or "").strip(),
                manifiesto))
            insertados += 1

        puntos = sembrar_serie_geih(cur)
        con.commit()
        con.close()

        if insertados:
            logger.info(
                f"Capa de educación sembrada desde el pipeline: {insertados} "
                f"indicador(es), {puntos} punto(s) de serie.")
        if sin_contraste:
            # El desajuste de rótulos es lo que deja el módulo «Comunidad vs
            # DANE» con una sola columna. Se nombra aquí, con los dos lados a la
            # vista, para que corregirlo no dependa de la memoria de nadie.
            logger.warning(
                "Sin contraste comunitario (%d de %d). Rótulos del ETL sin pareja "
                "en %s: %s | Rótulos del archivo comunitario: %s",
                len(sin_contraste), insertados, _VALORES_COMUNITARIOS,
                " · ".join(sin_contraste[:5]),
                " · ".join(list(comunitarios)[:5]) or "(ninguno)")
        return insertados
    except Exception as e:
        logger.warning(f"No se pudo sembrar la capa de educación: {e}")
        return 0



# ── CAPA: RESULTADOS CUANTITATIVOS DE LA TESIS ───────────────
# Separada a propósito del selector «DANE (oficial) / Comunidad / Ambos». Aquel
# compara un mismo indicador entre dos fuentes; esta reproduce resultados ya
# cerrados del Capítulo 5, que proceden de operaciones estadísticas y diagnósticos
# distintos y no deben promediarse ni presentarse como una sola serie: el CNPV
# 2018 cuenta personas, la EDUC 2023 cuenta sedes y matrícula, la GEIH estima
# sobre una muestra de hogares, y los diagnósticos territoriales (Fundación
# Empresarios por la Educación, LEE-PUJ) se citan con su fuente (clave «fuente»). Cada bloque declara su operación, su año, su
# universo y su unidad de observación, y la vista los mantiene aparte.
#
# Las tasas no son partes de un total, así que aquí no hay gráficos circulares:
# barras para comparar categorías, líneas para lo que ocurre a lo largo del
# tiempo o de la edad.

