def _esc_svg(t):
    return (str(t).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def _svg_marco(ancho, alto, titulo, cuerpo):
    return (f'<svg viewBox="0 0 {ancho} {alto}" width="100%" '
            f'xmlns="http://www.w3.org/2000/svg" role="img" '
            f'aria-label="{_esc_svg(titulo)}"><title>{_esc_svg(titulo)}</title>'
            f'{cuerpo}</svg>')


def _svg_barras(bloque):
    """Barras horizontales ordenadas. Para tasas por categoría."""
    datos = bloque["datos"]
    fila, izq, ancho = 34, 210, 760
    alto = 30 + fila * len(datos)
    tope = max(v for _, v in datos) or 1
    p = [f'<text x="6" y="16" font-size="13" fill="#6b7f8c">'
         f'{_esc_svg(bloque["eje"])}</text>']
    for i, (etq, val) in enumerate(datos):
        y = 30 + i * fila
        largo = (ancho - izq - 60) * val / tope
        p.append(f'<text x="{izq - 10}" y="{y + 15}" text-anchor="end" '
                 f'font-size="14" fill="#333">{_esc_svg(etq)}</text>')
        p.append(f'<rect x="{izq}" y="{y}" width="{largo:.1f}" height="20" '
                 f'rx="2" fill="{_PALETA[0]}"/>')
        p.append(f'<text x="{izq + largo + 8:.1f}" y="{y + 15}" font-size="13" '
                 f'fill="#333">{val:g}{_esc_svg(bloque.get("sufijo", " %"))}</text>')
    return _svg_marco(ancho, alto, bloque["titulo"], "".join(p))


def _svg_linea(bloque):
    """Una sola línea sobre un eje categórico (edad o año)."""
    datos = bloque["datos"]
    ancho, alto, izq, arr, aba = 760, 320, 60, 24, 50
    tope = max(v for _, v in datos) or 1
    paso = (ancho - izq - 30) / max(len(datos) - 1, 1)
    pts, p = [], [f'<text x="6" y="14" font-size="13" fill="#6b7f8c">'
                  f'{_esc_svg(bloque["eje"])}</text>']
    for k in range(5):
        y = arr + (alto - arr - aba) * k / 4
        p.append(f'<line x1="{izq}" y1="{y:.1f}" x2="{ancho - 20}" y2="{y:.1f}" '
                 f'stroke="#e8e4dc"/>')
        p.append(f'<text x="{izq - 8}" y="{y + 4:.1f}" text-anchor="end" '
                 f'font-size="12" fill="#6b7f8c">{tope * (4 - g) / 4:.0f}</text>')
    for i, (etq, val) in enumerate(datos):
        x = izq + paso * i
        y = arr + (alto - arr - aba) * (1 - val / tope)
        pts.append(f"{x:.1f},{y:.1f}")
        p.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4" fill="{_PALETA[0]}"/>')
        p.append(f'<text x="{x:.1f}" y="{y - 10:.1f}" text-anchor="middle" '
                 f'font-size="12" fill="#333">{val:g}</text>')
        p.append(f'<text x="{x:.1f}" y="{alto - 22}" text-anchor="middle" '
                 f'font-size="13" fill="#333">{_esc_svg(etq)}</text>')
    p.insert(1, f'<polyline points="{" ".join(pts)}" fill="none" '
                f'stroke="{_PALETA[0]}" stroke-width="2.5"/>')
    return _svg_marco(ancho, alto, bloque["titulo"], "".join(p))


def _leyenda(series, x, y):
    p = []
    for i, nombre in enumerate(series):
        cx = x + i * 190
        p.append(f'<rect x="{cx}" y="{y - 9}" width="11" height="11" rx="2" '
                 f'fill="{_PALETA[i % len(_PALETA)]}"/>')
        p.append(f'<text x="{cx + 16}" y="{y}" font-size="12" fill="#333">'
                 f'{_esc_svg(nombre)}</text>')
    return "".join(p)


def _svg_agrupadas(bloque):
    """Barras agrupadas horizontales: una categoría, varias series."""
    series, datos = bloque["series"], bloque["datos"]
    izq, ancho, altura = 210, 760, 15
    grupo = altura * len(series) + 16
    alto = 44 + grupo * len(datos)
    tope = max(max(v) for _, v in datos) or 1
    p = [_leyenda(series, 6, 14)]
    for i, (etq, valores) in enumerate(datos):
        y0 = 40 + grupo * i
        p.append(f'<text x="{izq - 10}" y="{y0 + grupo / 2}" text-anchor="end" '
                 f'font-size="13" fill="#333">{_esc_svg(etq)}</text>')
        for k, val in enumerate(valores):
            y = y0 + k * altura
            largo = (ancho - izq - 60) * val / tope
            p.append(f'<rect x="{izq}" y="{y}" width="{largo:.1f}" '
                     f'height="{altura - 2}" fill="{_PALETA[k % len(_PALETA)]}"/>')
            p.append(f'<text x="{izq + largo + 6:.1f}" y="{y + altura - 4}" '
                     f'font-size="11" fill="#555">{val:g}</text>')
    return _svg_marco(ancho, alto, bloque["titulo"], "".join(p))


def _svg_linea_multiple(bloque):
    """Varias líneas sobre el mismo eje temporal."""
    series, datos = bloque["series"], bloque["datos"]
    ancho, alto, izq, arr, aba = 760, 340, 60, 30, 56
    planos = [v for _, vs in datos for v in vs]
    lo, hi = min(planos), max(planos)
    lo, hi = lo - (hi - lo) * 0.25 - 0.1, hi + (hi - lo) * 0.25 + 0.1
    paso = (ancho - izq - 30) / max(len(datos) - 1, 1)
    p = [_leyenda(series, 6, 14),
         f'<text x="6" y="{alto - 6}" font-size="12" fill="#6b7f8c">'
         f'{_esc_svg(bloque["eje"])}</text>']
    for k in range(5):
        y = arr + (alto - arr - aba) * k / 4
        p.append(f'<line x1="{izq}" y1="{y:.1f}" x2="{ancho - 20}" y2="{y:.1f}" '
                 f'stroke="#e8e4dc"/>')
        p.append(f'<text x="{izq - 8}" y="{y + 4:.1f}" text-anchor="end" '
                 f'font-size="12" fill="#6b7f8c">'
                 f'{hi - (hi - lo) * g / 4:.1f}</text>')
    for k in range(len(series)):
        pts = []
        for i, (_, valores) in enumerate(datos):
            x = izq + paso * i
            y = arr + (alto - arr - aba) * (1 - (valores[k] - lo) / (hi - lo))
            pts.append(f"{x:.1f},{y:.1f}")
            p.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="3.5" '
                     f'fill="{_PALETA[k % len(_PALETA)]}"/>')
        p.append(f'<polyline points="{" ".join(pts)}" fill="none" '
                 f'stroke="{_PALETA[k % len(_PALETA)]}" stroke-width="2.2"/>')
    for i, (etq, _) in enumerate(datos):
        p.append(f'<text x="{izq + paso * i:.1f}" y="{alto - 30}" '
                 f'text-anchor="middle" font-size="13" fill="#333">'
                 f'{_esc_svg(etq)}</text>')
    return _svg_marco(ancho, alto, bloque["titulo"], "".join(p))


def _svg_multiple(bloque):
    """Un gráfico pequeño por indicador: cinco unidades, cinco ejes."""
    piezas = []
    for etq, valores in bloque["datos"]:
        sub = {"titulo": f'{bloque["titulo"]} — {etq}', "eje": bloque["eje"],
               "datos": list(zip(bloque["series"], valores))}
        piezas.append(f'<figure class="mini"><figcaption>{_esc_svg(etq)}'
                      f'</figcaption>{_svg_barras(sub)}</figure>')
    return "".join(piezas)


_DIBUJANTES = {"barras": _svg_barras, "linea": _svg_linea,
               "agrupadas": _svg_agrupadas, "linea_multiple": _svg_linea_multiple,
               "multiple": _svg_multiple}


def dibujar_bloque(bloque):
    return _DIBUJANTES[bloque["tipo"]](bloque)


def escribir_respaldo_tesis():
    """Deja onlife_tesis_quantitative.json como respaldo legible de la capa.

    El archivo permite auditar los valores sin leer el código y sin consultar la
    base: es la versión para personas del mismo contenido que sirve el endpoint.
    """
    try:
        ruta = os.path.join(DATA_FOLDER, "onlife_tesis_quantitative.json")
        with open(ruta, "w", encoding="utf-8") as f:
            json.dump({"generado": datetime.now().isoformat(timespec="seconds"),
                       "nota": "Resultados cerrados del Capítulo 5. Varias "
                               "operaciones estadísticas y diagnósticos "
                               "distintos; no deben promediarse entre sí.",
                       "bloques": RESULTADOS_TESIS},
                      f, ensure_ascii=False, indent=2)
        return ruta
    except Exception as e:
        logger.warning(f"No se pudo escribir el respaldo de la capa de tesis: {e}")
        return ""


@app.route("/api/thesis-quantitative")
def api_thesis_quantitative():
    """Resultados cuantitativos cerrados de la tesis, con su procedencia."""
    bid = request.args.get("bloque", "")
    if bid:
        uno = next((b for b in RESULTADOS_TESIS if b["id"] == bid), None)
        if not uno:
            return jsonify({"status": "error", "message": "bloque desconocido"}), 404
        return jsonify(uno)
    return jsonify({"status": "ok", "total": len(RESULTADOS_TESIS),
                    "bloques": RESULTADOS_TESIS})


@app.route("/datos/tesis")
def vista_tesis_cuantitativa():
    """Página retirada (P3): el enlace antiguo vuelve al inicio."""
    return redirect("/", code=301)


def sembrar_series_oficiales():
    """Siembra data/official_timeseries.csv: series anuales publicadas por el DANE
    (p. ej., la tasa de desocupación por ciudad, año calendario). Solo años
    observados; reemplaza la fila si el archivo cambia. Columnas:
    territory, indicator, layer, year, value, source_label."""
    filas = _leer_csv_datos("official_timeseries.csv")
    if not filas:
        return 0
    n = 0
    try:
        con = sqlite3.connect(DB_PATH)
        for f in filas:
            ter = (f.get("territory") or "").strip()
            ind = (f.get("indicator") or "").strip()
            anio = _a_float(f.get("year")); val = _a_float(f.get("value"))
            if not ter or not ind or anio is None or val is None:
                continue
            con.execute("""INSERT OR REPLACE INTO official_timeseries
                (territory,indicator,layer,year,value,source_type,source_label,is_estimate)
                VALUES (?,?,?,?,?,?,?,0)""",
                (ter, ind, (f.get("layer") or "Empleo").strip(), int(anio), val, "geih",
                 (f.get("source_label") or "DANE").strip()))
            n += 1
        con.commit(); con.close()
        if n:
            logger.info(f"Series oficiales sembradas desde CSV: {n} punto(s).")
    except Exception as e:
        logger.warning(f"No se pudieron sembrar las series oficiales: {e}")
    return n


def run_supplement_startup():
    """Wire in the Buenaventura/education supplement automatically.

    Runs the GEIH pipeline ONCE (only if its CSV output is missing, so we do
    not spawn a subprocess on every worker reload) and seeds the education
    indicators. Everything is wrapped so a failure here can never stop the app
    from serving.
    """
    try:
        csv_path = os.path.join(DATA_FOLDER, "official_indicators.csv")
        if not os.path.exists(csv_path) and not IS_PRODUCTION:
            # El pipeline se ejecuta SOLO en desarrollo. En el servidor de
            # producción está prohibido, y la prohibición no es una precaución
            # sino la consecuencia de un incidente: el proceso lee microdatos
            # de la GEIH con pandas, y un DataFrame ocupa varias veces lo que
            # ocupa el archivo en disco. Lanzado desde el servidor web, superó
            # el techo de memoria de la cuenta y el alojamiento terminó el
            # proceso trabajador, con el sitio caído. Los CSV derivados se
            # calculan en la máquina de trabajo y se suben ya hechos.
            #
            # Va además en un hilo aparte, para que el primer arranque en
            # desarrollo no deje la aplicación sin responder mientras dura.
            def _en_segundo_plano():
                if try_run_pipeline():
                    sembrar_educacion_geih()
            threading.Thread(target=_en_segundo_plano, daemon=True,
                             name="pipeline-geih").start()
        elif not os.path.exists(csv_path):
            logger.warning(
                "Falta %s y no se ejecuta el pipeline en producción por el "
                "límite de memoria de la cuenta. Genera los CSV en local y "
                "súbelos a data/.", os.path.basename(csv_path))
            # La capa de educación NO depende de ese archivo: tiene sus propios
            # CSV (educacion_indicadores_geih.csv, serie anual, comunitarios).
            # Antes se omitía aquí y el servidor mostraba menos brechas que
            # el equipo local aunque esos archivos ya estuvieran en data/.
            sembrar_educacion_geih()
        else:
            sembrar_educacion_geih()    # lee las salidas del pipeline
        sembrar_series_oficiales()      # data/official_timeseries.csv, si existe
        escribir_respaldo_tesis()       # onlife_tesis_quantitative.json
    except Exception as e:
        logger.warning(f"Supplement startup omitido: {e}")


# ── E5: PASSWORD HASHING ─────────────────────────────────────

def hash_password(password):
    try:
        from werkzeug.security import generate_password_hash
        return generate_password_hash(password)
    except ImportError:
        salt = secrets.token_hex(16)
        return f"{salt}:{hashlib.sha256((salt+password).encode()).hexdigest()}"

def check_password(stored, password):
    try:
        from werkzeug.security import check_password_hash
        return check_password_hash(stored, password)
    except (ImportError, ValueError):
        if ":" not in stored:
            return stored == hashlib.sha256(password.encode()).hexdigest()
        salt, h = stored.split(":", 1)
        return h == hashlib.sha256((salt+password).encode()).hexdigest()

# ── HELPERS ──────────────────────────────────────────────────

IMAGE_EXTS = {".jpg",".jpeg",".png",".webp",".gif"}
VIDEO_EXTS = {".mp4",".webm",".mov",".avi"}
# Duración máxima publicable de un video. El archivo se acepta completo —
# rechazar una grabación de campo por larga sería perderla— y se recorta
# después: quien graba en el territorio no siempre puede repetir la toma.
VIDEO_MAX_SEGUNDOS = 120
# Una sola versión para toda la aplicación (cabecera, exportaciones, mesh).
APP_VERSION = "5.0"
# Los videos se suben por partes (ver /api/upload/video/*): PythonAnywhere
# corta cualquier petición de más de 100 MiB, y un video de dos minutos grabado
# con un teléfono pesa entre 100 y 300 MB. Cada parte cabe holgadamente bajo
# MAX_CONTENT_LENGTH y, si la red se corta, sólo se repite la parte perdida.
VIDEO_MAX_MB        = 400
VIDEO_PARTE_MB      = 8
# Lo que se guarda: 720p (el lado mayor a 1280 px), H.264 y AAC. Un video de
# dos minutos queda en unos 20–30 MB, se reproduce en cualquier navegador
# (incluidos los .mov HEVC del iPhone, que Chrome no abre) y pierde por el
# camino los metadatos del teléfono.
VIDEO_LADO_MAX      = 1280
VIDEO_COMPRIMIR_TIMEOUT = 200   # segundos; si se supera, se recorta sin recodificar
AUDIO_EXTS = {".mp3",".wav",".ogg",".m4a",".aac"}
# Documents people may share in the Red Comunitaria / attach to contributions.
# These are NOT script-executable in the browser the way svg/html are, and we
# always serve them as downloads (Content-Disposition: attachment), so they are
# safe to accept. svg/html remain excluded as stored-XSS vectors.
DOC_EXTS   = {".pdf",".doc",".docx",".xls",".xlsx",".ppt",".pptx",
             ".txt",".csv",".odt",".ods",".odp",".rtf"}

# Only these may ever be written to disk. Anything else (svg, html, php,
# js, exe, ...) is rejected — an uploaded SVG/HTML served from our own
# origin is a stored-XSS vector, so they are deliberately excluded.
ALLOWED_UPLOAD_EXTS = IMAGE_EXTS | VIDEO_EXTS | AUDIO_EXTS | DOC_EXTS

# Leading "magic bytes" for the image formats we accept, so a script
# renamed to .png can't pass the extension check.
_IMAGE_SIGNATURES = (
    b"\xff\xd8\xff",                 # jpg/jpeg
    b"\x89PNG\r\n\x1a\n",            # png
    b"GIF87a", b"GIF89a",           # gif
    b"RIFF",                         # webp (RIFF....WEBP)
)

def _looks_like_image(head: bytes) -> bool:
    return any(head.startswith(sig) for sig in _IMAGE_SIGNATURES)

def validate_upload(storage):
    """Return (ok, media_type, error). Enforces extension allowlist and,
    for images, verifies the file actually begins with image magic bytes."""
    fn = storage.filename or ""
    ext = os.path.splitext(fn)[1].lower()
    if ext not in ALLOWED_UPLOAD_EXTS:
        return False, None, f"Tipo de archivo no permitido: {ext or 'desconocido'}"
    mt = detect_media(fn)
    if ext in IMAGE_EXTS:
        head = storage.stream.read(16)
        storage.stream.seek(0)
        if not _looks_like_image(head):
            return False, None, "El archivo no es una imagen válida."
    return True, mt, None

EVIDENCIA_MAX = 5   # archivos de evidencia por corrección o comparación

def _evidencias(lista):
    """Limpia la lista de archivos de evidencia que manda el navegador.

    Sólo acepta archivos ya subidos a /gallery/ por /api/upload y que existan
    en disco, con un tipo permitido; el nombre visible se limpia. Devuelve la
    lista lista para guardar como JSON."""
    out = []
    if not isinstance(lista, list):
        return out
    for it in lista[:EVIDENCIA_MAX]:
        if not isinstance(it, dict):
            continue
        url = str(it.get("url") or "")
        m = re.fullmatch(r"/gallery/([A-Za-z0-9_.-]+)", url)
        if not m:
            continue
        fn = m.group(1)
        ext = os.path.splitext(fn)[1].lower()
        if ext not in ALLOWED_UPLOAD_EXTS or not os.path.isfile(os.path.join(UPLOAD_FOLDER, fn)):
            continue
        nombre = sanitise(str(it.get("name") or fn), 120) or fn
        out.append({"url": url, "name": nombre, "ext": ext.lstrip(".")})
    return out


def _con_evidencias(filas):
    """Convierte la columna evidence_files (texto JSON) en lista para el navegador."""
    for f in filas:
        try:
            f["evidence_files"] = json.loads(f.get("evidence_files") or "[]")
        except Exception:
            f["evidence_files"] = []
    return filas


IMAGE_WIDTHS = (480, 960, 1600)

def process_image_upload(src_path, stem):
    """Strip metadata and write responsive derivatives.

    Returns (canonical_url_name, [widths_written]) or (None, []) if the
    image could not be processed, in which case the caller keeps the
    original file untouched.
    """
    try:
        from PIL import Image, ImageOps
    except Exception:
        logger.info("Pillow no disponible — la imagen se guarda sin optimizar.")
        return None, []
    try:
        im = Image.open(src_path)
        # Honour the EXIF orientation flag BEFORE discarding metadata,
        # otherwise portrait photos come out sideways.
        im = ImageOps.exif_transpose(im)
        if im.mode not in ("RGB", "L"):
            im = im.convert("RGB")
        # Re-create from pixel data only: no EXIF, no GPS, no device id.
        clean = Image.new(im.mode, im.size)
        clean.putdata(list(im.getdata()))

        written = []
        for w in IMAGE_WIDTHS:
            if clean.width < w and w != IMAGE_WIDTHS[0]:
                continue                      # never upscale
            d = clean.copy()
            d.thumbnail((w, w * 3), Image.LANCZOS)
            d.save(os.path.join(UPLOAD_FOLDER, f"{stem}-{w}.webp"), "WEBP", quality=82, method=4)
            written.append(w)
        if not written:
            return None, []
        # JPEG fallback at the largest size — used by the printable
        # evidence packet and by anything that downloads the image.
        big = max(written)
        j = clean.copy(); j.thumbnail((big, big * 3), Image.LANCZOS)
        j.save(os.path.join(UPLOAD_FOLDER, f"{stem}-{big}.jpg"), "JPEG", quality=86, optimize=True)
        logger.info("Imagen procesada: %s — metadatos eliminados, anchos %s", stem, written)
        return f"{stem}-{big}.webp", written
    except Exception as e:
        logger.warning("No se pudo procesar la imagen %s: %s", stem, e)
        return None, []

def detect_media(fn):
    e = os.path.splitext(fn)[1].lower()
    if e in IMAGE_EXTS: return "foto"
    if e in VIDEO_EXTS: return "video"
    if e in AUDIO_EXTS: return "audio"
    return "doc"

def secure_name(fn):
    b, e = os.path.splitext(fn)
    c = "".join(x for x in b if x.isalnum() or x in "-_").strip()
    if not c: c = "upload_"+datetime.now().strftime("%Y%m%d%H%M%S")
    return c+e.lower()

def rows(cur): return [dict(r) for r in cur.fetchall()]
def row(cur):  r = cur.fetchone(); return dict(r) if r else None

def paginate(q, params, req, order="created_at DESC"):
    page     = max(req.args.get("page", 1, type=int) or 1, 1)
    per_page = req.args.get("per_page", 20, type=int)
    per_page = min(per_page, 100)
    q += " ORDER BY " + order + " LIMIT ? OFFSET ?"
    params.extend([per_page, (page-1)*per_page])
    return q, params

def notify(db, recipient, ntype, actor, message, panel="", contribution_id=None):
    """Create a notification row. recipient is a username (for logged-in users)
    or a persistent_ voter id — matches whatever identity system already
    produced the like/comment/follow. Silently no-ops on bad input; a failed
    notification should never break the action that triggered it."""
    if not recipient:
        return
    try:
        db.execute(
            "INSERT INTO notifications (recipient,type,actor,message,panel,contribution_id) "
            "VALUES (?,?,?,?,?,?)",
            (recipient, ntype, actor or "Alguien", message, panel, contribution_id))
    except Exception as e:
        logger.warning("notify() failed: %s", e)

def auto_tracker(db, cid, territory, title):
    # INSERT OR IGNORE relies on the unique index idx_tracker_contrib so a case
    # can never be tracked twice, even under concurrent approvals.
    if not db.execute("SELECT id FROM tracker WHERE contribution_id=?",(cid,)).fetchone():
        db.execute("INSERT OR IGNORE INTO tracker (contribution_id,territory,title) VALUES (?,?,?)",(cid,territory,title))

def db_metrics(db):
    m = {
        "total":       db.execute("SELECT COUNT(*) FROM contributions").fetchone()[0],
        "approved":    db.execute("SELECT COUNT(*) FROM contributions WHERE approved=1").fetchone()[0],
        "pending":     db.execute("SELECT COUNT(*) FROM contributions WHERE approved=0").fetchone()[0],
        "rejected":    db.execute("SELECT COUNT(*) FROM contributions WHERE approved=-1").fetchone()[0],
        "territories": db.execute("SELECT COUNT(DISTINCT territory) FROM contributions WHERE approved=1").fetchone()[0],
        "categories":  db.execute("SELECT COUNT(DISTINCT category) FROM contributions WHERE approved=1").fetchone()[0],
        # «En proceso»: casos de Seguimiento enviados a una institución y aún
        # sin resolver. (La clave conserva el nombre antiguo «interviews» porque
        # varias vistas la leen; antes valía siempre 0.)
        "interviews":  db.execute("SELECT COUNT(*) FROM tracker WHERE status='en_proceso'").fetchone()[0],
        "indicators":  db.execute("SELECT COUNT(*) FROM ci_publicados").fetchone()[0],
        "undercounts": db.execute("SELECT COUNT(*) FROM ci_publicados WHERE direction='undercount'").fetchone()[0],
        "users":       db.execute("SELECT COUNT(*) FROM users").fetchone()[0],
        "actions":     db.execute("SELECT COUNT(*) FROM institutional_actions").fetchone()[0],
        "resolved":    db.execute("SELECT COUNT(*) FROM tracker WHERE status='resuelto'").fetchone()[0],
        # Guía PWA §4.3 — actividad reciente para la línea de prueba social del hero.
        "week_new":    db.execute("SELECT COUNT(*) FROM contributions WHERE approved=1 "
                                  "AND created_at >= datetime('now','-7 days')").fetchone()[0],
        "week_territory": (db.execute(
            "SELECT territory FROM contributions WHERE approved=1 "
            "AND created_at >= datetime('now','-7 days') AND territory<>'' "
            "GROUP BY territory ORDER BY COUNT(*) DESC LIMIT 1").fetchone() or [""])[0],
    }
    # Nombre legible del territorio (en la base se guarda el slug).
    t = m["week_territory"]
    m["week_territory"] = TERRITORIES.get(t, {}).get("name", t) if t else ""
    return m

