# ── B/O1: SERVICE WORKER (excludes sensitive endpoints) ──────

_BUILD_ID = None
def _build_id():
    """Short hash of the served HTML — changes only when the page changes.

    Used as the service-worker cache name so that every deploy that alters the
    UI automatically invalidates old caches and pushes fresh content to users.
    """
    global _BUILD_ID
    if _BUILD_ID is None:
        try:
            _BUILD_ID = hashlib.sha256(HTML.encode("utf-8")).hexdigest()[:12]
        except Exception:
            _BUILD_ID = datetime.now().strftime("%Y%m%d%H%M%S")
    return _BUILD_ID

@app.route("/sw.js")
def service_worker():
    sw = r"""
const CACHE='onlife-__BUILD__';
// Teselas del mapa: caché propia que sobrevive a los despliegues. Guarda solo
// lo que la persona ya miró (no descarga zonas enteras: las políticas de uso
// de los servidores de mapas lo prohíben) y se recorta al pasar de 6000.
const TILES='onlife-teselas';
const TILE_RE=/tile\.opentopomap\.org|tiles\.openfreemap\.org|basemaps\.cartocdn\.com|tile\.openstreetmap\.org/;
let _tilePuts=0;
const SHELL=['/',__ASSETS__
  'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css',
  'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/leaflet.heat/0.2.0/leaflet-heat.js',
  'https://cdnjs.cloudflare.com/ajax/libs/maplibre-gl/4.7.1/maplibre-gl.min.css',
  'https://cdnjs.cloudflare.com/ajax/libs/maplibre-gl/4.7.1/maplibre-gl.min.js',
  'https://unpkg.com/@maplibre/maplibre-gl-leaflet@0.1.4/leaflet-maplibre-gl.js'];

// O1: Never cache sensitive endpoints
const NO_CACHE=['/api/auth/','/api/upload','/api/moderation/vote',
                '/api/moderation/approve','/api/moderation/reject',
                '/api/me','/static/','/sw.js','/api/admin/'];

self.addEventListener('install',e=>{
  // Cada recurso por separado: si una biblioteca externa falla, el resto se
  // guarda igual y el modo sin conexión no queda desactivado por completo.
  e.waitUntil(caches.open(CACHE).then(c=>Promise.allSettled(SHELL.map(u=>c.add(u)))).then(()=>self.skipWaiting()));
});
self.addEventListener('activate',e=>{
  // Delete every OLD cache (any name != current build), then take control.
  e.waitUntil(caches.keys().then(ks=>Promise.all(
    ks.filter(k=>k!==CACHE && k!==TILES).map(k=>caches.delete(k))
  )).then(()=>self.clients.claim()));
});
self.addEventListener('fetch',e=>{
  const u=e.request.url;
  if(e.request.method!=='GET'){return;}
  if(NO_CACHE.some(nc=>u.includes(nc))){return;} // never cache
  if(TILE_RE.test(u)){
    // Primero la caché: una tesela ya vista no vuelve a gastar datos.
    e.respondWith(caches.open(TILES).then(c=>c.match(e.request).then(hit=>hit || fetch(e.request).then(r=>{
      if(r && (r.ok || r.type==='opaque')){ c.put(e.request, r.clone());
        if(++_tilePuts%100===0) c.keys().then(ks=>{ if(ks.length>6000) ks.slice(0,ks.length-6000).forEach(k=>c.delete(k)); }); }
      return r; }).catch(()=>Response.error()))));
    return;
  }
  // NETWORK-FIRST for page navigations / HTML so deployed updates show
  // immediately when online; fall back to cache only when offline.
  if(e.request.mode==='navigate'){
    e.respondWith(
      fetch(e.request).then(r=>{const cl=r.clone();caches.open(CACHE).then(c=>c.put(e.request,cl));return r;})
        .catch(()=>caches.match(e.request).then(c=>c||caches.match('/')))
    );
    return;
  }
  if(u.includes('/api/')){
    e.respondWith(fetch(e.request).then(r=>{const cl=r.clone();caches.open(CACHE).then(c=>c.put(e.request,cl));return r;}).catch(()=>caches.match(e.request)));
    return;
  }
  // CACHE-FIRST for static assets (leaflet, fonts) — these are versioned URLs.
  e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request).then(r=>{if(r&&r.status===200){const cl=r.clone();caches.open(CACHE).then(c=>c.put(e.request,cl));}return r;}).catch(()=>Response.error())));
});
self.addEventListener('sync',e=>{if(e.tag==='sync-queue')e.waitUntil(syncQueue());});
async function syncQueue(){
  const db=await openIDB();const all=await idbAll(db,'queue');
  for(const item of all){try{const r=await fetch('/api/contribute',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item.data)});if(r.ok)await idbDel(db,'queue',item.id);}catch(e){}}
}
function openIDB(){return new Promise((res,rej)=>{const r=indexedDB.open('onlife_q',1);r.onupgradeneeded=e=>e.target.result.createObjectStore('queue',{keyPath:'id',autoIncrement:true});r.onsuccess=e=>res(e.target.result);r.onerror=rej;});}
function idbAll(db,st){return new Promise((res,rej)=>{const r=db.transaction(st,'readonly').objectStore(st).getAll();r.onsuccess=()=>res(r.result);r.onerror=rej;});}
function idbDel(db,st,id){return new Promise((res,rej)=>{const t=db.transaction(st,'readwrite');t.objectStore(st).delete(id);t.oncomplete=res;t.onerror=rej;});}
"""
    # Cache name is derived from the served HTML, so it changes automatically
    # on every deploy that alters the page. A changed sw.js makes the browser
    # install a fresh service worker, whose 'activate' purges the old caches —
    # so new features appear without users having to clear anything.
    sw = sw.replace("__BUILD__", _build_id())
    sw = sw.replace("__ASSETS__", "".join(f"'{v['ruta']}'," for v in _ASSETS.values()))
    return Response(sw, mimetype="application/javascript",
                    headers={"Service-Worker-Allowed": "/",
                             "Cache-Control": "no-store, no-cache, must-revalidate",
                             "Pragma": "no-cache"})

