@app.route("/api/me")
def api_me():
    if "user_id" in session:
        u = row(get_db().execute(
            "SELECT id,username,name,role,email,bio,profile_pic,cover_pic,territory,"
            "birth_date,occupation,organization,experience,phone,show_contact,email_verified,created_at "
            "FROM users WHERE id=?", (session["user_id"],)))
        if u:
            e = _edad(u.get("birth_date"))
            u["adult"] = None if e is None else e >= EDAD_MINIMA
            return jsonify({"status":"success","user":u})
    return jsonify({"status":"error","user":None})

# ── EDAD Y CORREO ────────────────────────────────────────────
# En Colombia la mayoría de edad es a los 18 años, y la Ley 1581 de 2012
# (art. 7) y el Decreto 1377 de 2013 (art. 12) restringen el tratamiento de
# datos de niños, niñas y adolescentes a lo autorizado por su representante.
# La plataforma no gestiona esas autorizaciones: sólo admite cuentas de
# personas mayores de 18. La fecha de nacimiento nunca se publica; los demás
# sólo ven «mayor de edad» implícito en que la cuenta existe.
EDAD_MINIMA = 18
_EMAIL_RE = re.compile(r"^[^@\s]{1,64}@[^@\s]{1,190}\.[A-Za-z]{2,24}$")

def _edad(fecha):
    try:
        n = datetime.strptime(str(fecha)[:10], "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None
    hoy = datetime.now().date()
    if n > hoy or n.year < 1900:
        return None
    return hoy.year - n.year - ((hoy.month, hoy.day) < (n.month, n.day))

def _send_mail(to_addr, subject, body, tag="mail"):
    """Envía un correo si hay SMTP configurado; si no, deja el contenido en el
    registro del servidor para que el equipo lo reenvíe a mano."""
    host = os.environ.get("SMTP_HOST")
    if not host or not to_addr:
        logger.info(f"[{tag}] (sin SMTP) para {to_addr or '?'}: {body}")
        return False
    try:
        import smtplib
        from email.message import EmailMessage
        msg = EmailMessage()
        msg["Subject"] = subject
        msg["From"] = os.environ.get("SMTP_FROM", "no-reply@onlifeafro.org")
        msg["To"] = to_addr
        msg.set_content(body)
        with smtplib.SMTP(host, int(os.environ.get("SMTP_PORT", "587")), timeout=15) as s_:
            s_.starttls()
            user, pw = os.environ.get("SMTP_USER"), os.environ.get("SMTP_PASS")
            if user and pw:
                s_.login(user, pw)
            s_.send_message(msg)
        return True
    except Exception as e:
        logger.error(f"[{tag}] fallo al enviar a {to_addr}: {e}")
        return False

def _enviar_verificacion(db, uid, email):
    token = secrets.token_urlsafe(32)
    vence = (datetime.now() + timedelta(hours=48)).strftime("%Y-%m-%d %H:%M:%S")
    db.execute("INSERT INTO email_verifications (user_id,email,token_hash,expires_at) VALUES (?,?,?,?)",
               (uid, email, hashlib.sha256(token.encode()).hexdigest(), vence))
    db.commit()
    base = os.environ.get("APP_BASE_URL") or request.host_url.rstrip("/")
    return _send_mail(email, "OnLife Afro | confirma tu correo",
        "Hola. Para verificar tu cuenta en OnLife Afro abre este enlace:\n"
        f"{base}/verificar-correo?token={token}\n\nVence en 48 horas. "
        "Si no creaste esta cuenta, ignora este mensaje.", tag="verificar-correo")

@app.route("/api/auth/register", methods=["POST"])
@rate_limit(5, 300)
@csrf_required
def api_register():
    d = request.json or {}
    u    = re.sub(r'[^a-zA-Z0-9_.-]', '', d.get("username","").strip())[:50]
    p    = d.get("password","").strip()
    n    = sanitise(d.get("name",""), 100)
    # Las cuentas institucionales pueden cambiar el estado de los casos y
    # validar datos, así que no se otorgan solas: se piden y un admin aprueba.
    wants_institutional = d.get("role") == "institutional"
    role = "community"
    email = (d.get("email") or "").strip().lower()[:200]
    nac   = (d.get("birth_date") or "").strip()[:10]
    if not all([u,p,n]): return jsonify({"status":"error","message":"Faltan campos"}),400
    if len(p) < 8: return jsonify({"status":"error","message":"Contraseña mínima 8 caracteres"}),400
    edad = _edad(nac)
    if edad is None:
        return jsonify({"status":"error","message":"Escribe tu fecha de nacimiento."}),400
    if edad < EDAD_MINIMA:
        # No se guarda nada de quien no puede registrarse.
        return jsonify({"status":"error","message":"Para crear una cuenta debes ser mayor de 18 años. "
                        "Puedes explorar la plataforma sin cuenta."}),400
    if not _EMAIL_RE.match(email):
        return jsonify({"status":"error","message":"Escribe un correo válido: lo usaremos para verificar tu cuenta."}),400
    if not d.get("consent"):
        return jsonify({"status":"error","message":"Debes aceptar la política de tratamiento de datos."}),400
    db = get_db()
    if db.execute("SELECT id FROM users WHERE username=?",(u,)).fetchone():
        return jsonify({"status":"error","message":"Usuario ya existe"}),400
    if db.execute("SELECT id FROM users WHERE lower(email)=?",(email,)).fetchone():
        return jsonify({"status":"error","message":"Ya existe una cuenta con ese correo."}),400
    db.execute("INSERT INTO users (username,password,name,role,requested_role,email,birth_date,data_consent_at) "
               "VALUES (?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",
               (u,hash_password(p),n,role,"institutional" if wants_institutional else "",email,nac))
    db.commit()
    new = row(get_db().execute("SELECT * FROM users WHERE username=?",(u,)))
    try:
        _enviar_verificacion(db, new["id"], email)
    except Exception as e:
        logger.warning(f"verificación no enviada: {e}")
    # Log the new account in immediately so they can follow / contribute without
    # a second step. (Previously registration left the user logged out.)
    session["user_id"]  = new["id"]
    session["username"] = new["username"]
    session["role"]     = new["role"]
    session.permanent   = True   # la cookie sobrevive al cierre del navegador (24 h)
    logger.info(f"Nuevo usuario: {u} ({role})")
    return jsonify({"status":"success", "institutional_pending": wants_institutional,
                    "csrf_token": generate_csrf(),
                    "user":{"id":new["id"],"username":new["username"],
                            "name":new["name"],"role":new["role"]}})

@app.route("/api/auth/login", methods=["POST"])
@rate_limit(10, 300)
@csrf_required
def api_login():
    d = request.json or {}
    u,p = d.get("username","").strip(),d.get("password","").strip()
    user = row(get_db().execute("SELECT * FROM users WHERE username=?",(u,)))
    if not user or not check_password(user["password"],p):
        logger.warning(f"Login fallido: {u}")
        return jsonify({"status":"error","message":"Credenciales inválidas"}),401
    session["user_id"]  = user["id"]
    session["username"] = user["username"]
    session["role"]     = user["role"]
    session.permanent   = True   # la cookie sobrevive al cierre del navegador (24 h)
    logger.info(f"Login: {u} ({user['role']})")
    return jsonify({"status":"success","csrf_token":generate_csrf(),"user":{"id":user["id"],"username":u,"name":user["name"],"role":user["role"]}})

@app.route("/api/auth/logout", methods=["POST"])
@csrf_required
def api_logout():
    session.clear()
    # Token nuevo para esta misma pestaña: sin él, después de cerrar sesión
    # todas las acciones (contestar una llamada, votar, comentar) fallaban con
    # «CSRF validation failed» hasta recargar la página.
    return jsonify({"status":"success","csrf_token":generate_csrf()})

# ── PASSWORD RESET ───────────────────────────────────────────
# Token-based reset. If SMTP_* env vars are set, the link is emailed;
# otherwise the token is written to the log so an admin can relay it.
# The endpoint never reveals whether an account exists (anti-enumeration).

def _send_reset_email(to_addr, token):
    host = os.environ.get("SMTP_HOST")
    if not host or not to_addr:
        logger.info(f"[password-reset] token for {to_addr or 'unknown'}: {token} "
                    f"(no SMTP configured — relay manually)")
        return False
    try:
        import smtplib
        from email.message import EmailMessage
        msg = EmailMessage()
        msg["Subject"] = "OnLife Afro | restablecer contraseña"
        msg["From"] = os.environ.get("SMTP_FROM", "no-reply@onlifeafro.org")
        msg["To"] = to_addr
        base = os.environ.get("APP_BASE_URL", "http://127.0.0.1:5000")
        msg.set_content(f"Usa este enlace para restablecer tu contraseña:\n"
                        f"{base}/?reset_token={token}\n\nVence en 1 hora.")
        port = int(os.environ.get("SMTP_PORT", "587"))
        with smtplib.SMTP(host, port, timeout=15) as s:
            s.starttls()
            user, pw = os.environ.get("SMTP_USER"), os.environ.get("SMTP_PASS")
            if user and pw:
                s.login(user, pw)
            s.send_message(msg)
        return True
    except Exception as e:
        logger.error(f"[password-reset] email send failed: {e}")
        return False

@app.route("/api/auth/request-reset", methods=["POST"])
@rate_limit(5, 300)
@csrf_required
def api_request_reset():
    d = request.json or {}
    ident = (d.get("username") or d.get("email") or "").strip()
    db = get_db()
    user = row(db.execute(
        "SELECT id,email FROM users WHERE username=? OR email=?", (ident, ident)))
    if user:
        token = secrets.token_urlsafe(32)
        expires = (datetime.now() + timedelta(hours=1)).strftime("%Y-%m-%d %H:%M:%S")
        db.execute("INSERT INTO password_resets (user_id,token_hash,expires_at) VALUES (?,?,?)",
                   (user["id"], hashlib.sha256(token.encode()).hexdigest(), expires))
        db.commit()
        _send_reset_email(user.get("email"), token)
    # Always the same response, whether or not the account exists.
    return jsonify({"status": "success",
                    "message": "Si la cuenta existe, se enviaron instrucciones."})

@app.route("/api/auth/reset", methods=["POST"])
@rate_limit(5, 300)
@csrf_required
def api_reset_password():
    d = request.json or {}
    token = (d.get("token") or "").strip()
    new_pw = (d.get("password") or "").strip()
    if len(new_pw) < 6:
        return jsonify({"status":"error","message":"La contraseña debe tener al menos 6 caracteres."}), 400
    db = get_db()
    th = hashlib.sha256(token.encode()).hexdigest()
    rec = row(db.execute(
        "SELECT id,user_id,expires_at,used FROM password_resets WHERE token_hash=?", (th,)))
    if not rec or rec["used"] or rec["expires_at"] < datetime.now().strftime("%Y-%m-%d %H:%M:%S"):
        return jsonify({"status":"error","message":"Token inválido o vencido."}), 400
    db.execute("UPDATE users SET password=? WHERE id=?", (hash_password(new_pw), rec["user_id"]))
    db.execute("UPDATE password_resets SET used=1 WHERE id=?", (rec["id"],))
    db.commit()
    logger.info(f"Password reset via token: user#{rec['user_id']}")
    return jsonify({"status":"success","message":"Contraseña restablecida."})

# ── MESSAGES ─────────────────────────────────────────────────

@app.route("/api/messages", methods=["GET","POST"])
@csrf_required
def api_messages():
    db = get_db()
    if request.method=="POST":
        d = request.json or {}
        # Sin sesión, el nombre es sólo una etiqueta: nunca lleva insignia de
        # rol, nunca toma la foto de otra persona y no puede usar el nombre de
        # una institución ni de una cuenta registrada.
        sender = _anon_chat_name(db, d.get("sender",""))
        pic    = str(d.get("sender_pic",""))
        pic    = pic if re.match(r"^/gallery/[A-Za-z0-9_./-]+$", pic) else ""
        role   = ""
        sender_uid = ""
        att    = safe_media_url(str(d.get("attachment","")))
        att_t  = sanitise(str(d.get("attachment_type","")), 20)
        att_n  = sanitise(str(d.get("attachment_name","")), 160)
        text   = (d.get("text","") or "").strip()
        # A message must carry either text or an attachment.
        if not text and not att:
            return jsonify({"status":"error","message":"Mensaje vacío"}),400
        if "username" in session:
            u = row(db.execute("SELECT username,name,profile_pic,role FROM users WHERE username=?",(session["username"],)))
            if u:
                sender = u.get("name") or u.get("username") or sender
                pic    = pic or (u.get("profile_pic") or "")
                role   = u.get("role") or ""
                sender_uid = u["username"]
        # Fecha y hora completas (UTC): la columna guardaba solo la hora, y sin
        # fecha el chat no podía separar «Hoy», «Ayer» ni mostrar la hora local.
        db.execute("INSERT INTO messages (room,sender,text,sender_pic,sender_role,attachment,attachment_type,attachment_name,sender_uid,ts) "
                   "VALUES (?,?,?,?,?,?,?,?,?,datetime('now'))",
                   (d.get("room","general"), sender, text, pic, role, att, att_t, att_n, sender_uid))
        db.commit(); return jsonify({"status":"success"})
    room = request.args.get("room","general")
    limit = request.args.get("limit",60,type=int)
    # LEFT JOIN users so we can fill in an avatar/role even for older messages
    # that were stored before the author snapshot existed.
    msgs = rows(db.execute("""
        SELECT m.id, m.room, m.sender, m.text, m.ts,
               COALESCE(NULLIF(m.sender_pic,''),  u.profile_pic, '') AS sender_pic,
               COALESCE(NULLIF(m.sender_role,''), '')                AS sender_role,
               m.attachment, m.attachment_type, m.attachment_name
        FROM messages m
        LEFT JOIN users u ON (m.sender_uid<>'' AND u.username=m.sender_uid)
        WHERE m.room=? ORDER BY m.id DESC LIMIT ?""",(room,limit)))[::-1]
    return jsonify(msgs)

# ── CONTRIBUTIONS (E2: pagination, F5: layer filter) ─────────

_PORTALES = {"historia", "audio", "foto", "video", "denuncia", "dato", "texto"}
# Aportes anteriores a la marca de portal (type='texto'): cuentan como relato
# escrito salvo que su categoría delate otro portal (datos o denuncias).
_CATEGORIAS_NO_RELATO = ("Datos DANE", "Denuncia Comunitaria")

# Un relato escrito: sin foto, audio, video ni video enlazado, y entrado por el
# portal «Historia» (o, si es anterior a la marca de portal, sin categoría de
# datos). Lleva dos marcadores: _CATEGORIAS_NO_RELATO.
_SQL_RELATO = ("(COALESCE(media_url,'')='' AND COALESCE(video_embed,'')='' "
               "AND NOT (media_gallery IS NOT NULL AND media_gallery!='' AND media_gallery!='[]') "
               "AND (type='historia' OR (type='texto' AND COALESCE(category,'') NOT IN (?,?))))")


@app.route("/api/relatos/categorias")
def api_relatos_categorias():
    """Cuántos relatos escritos publicados hay por categoría: alimenta los
    filtros de «Relatos escritos» en Inicio, que sólo muestran las que tienen
    relatos (un filtro vacío es una promesa rota)."""
    out = rows(get_db().execute(
        "SELECT category, COUNT(*) AS n FROM contributions WHERE approved=1 AND "
        + _SQL_RELATO + " GROUP BY category ORDER BY n DESC", _CATEGORIAS_NO_RELATO))
    return jsonify(out)


@app.route("/api/documental/capitulos")
def api_documental_capitulos():
    """Capítulos del Modo Documental: categorías con aportes publicados y
    cuántos tiene cada una. Sólo se ofrecen capítulos con contenido."""
    return jsonify(rows(get_db().execute(
        "SELECT category, COUNT(*) AS n FROM contributions WHERE approved=1 "
        "AND COALESCE(category,'')<>'' GROUP BY category ORDER BY n DESC")))


@app.route("/api/contribute", methods=["POST"])
@rate_limit(20, 60)
@csrf_required
def api_contribute():
    d = request.json or {}
    ter   = sanitise(d.get("territory", ""), 50)
    title = sanitise(d.get("title", ""), 200)
    # Room for 500 words plus pasted links; the real limit is the word count.
    body  = sanitise(d.get("body", ""), 8000)
    if not ter or not title or not body:
        return jsonify({"status":"error","message":"Faltan campos obligatorios"}),400
    where = resolve_place(ter)
    if not where:
        return jsonify({"status":"error","message":"Lugar no válido"}),400
    ter, place_lat, place_lon, place_name = where
    n_words = count_words(body)
    if n_words > MAX_BODY_WORDS:
        return jsonify({"status":"error",
                        "message":f"El texto tiene {n_words} palabras; el máximo es {MAX_BODY_WORDS}."}),400
    video_embed = extract_video_embeds(body)
    author_pic = safe_media_url(str(d.get("author_pic", "")))
    if not author_pic.startswith("/gallery/"):
        author_pic = ""
    db = get_db()
    _langs = {"es","pal","cre","emb","wou","other"}
    lang = d.get("language","es")
    if lang not in _langs: lang = "es"
    # Multi-photo: media_urls is a list of image URLs. Keep media_url as the
    # primary attachment (first photo, or a non-image doc/audio) for backward
    # compatibility, and store the full set as JSON in media_gallery.
    gallery = d.get("media_urls") or []
    if isinstance(gallery, str):
        gallery = [gallery]
    # Cada URL se valida; las que no pasan se descartan en silencio en vez
    # de guardarse y romper el atributo donde se pintan.
    gallery = [safe_media_url(str(u)) for u in gallery][:60]  # generous cap
    gallery = [u for u in gallery if u]
    primary = safe_media_url(d.get("media_url","")) or (gallery[0] if gallery else "")
    # Durable ownership: the session username when logged in, otherwise the
    # persistent_ id the browser already uses for votes and likes. This is
    # what later lets the author — logged in or not — delete their own post.
    author_uid = _owner_uid(d)
    # Portal de origen. Sólo valores conocidos: «historia» es el portal de
    # texto y lo que alimenta «Relatos escritos» en Inicio.
    portal = str(d.get("type") or "texto").strip().lower()
    if portal not in _PORTALES:
        portal = "texto"
    d["type"] = portal
    cur = db.execute("""INSERT INTO contributions
        (territory,category,type,title,body,author,author_role,media_url,media_type,lat,lon,language,media_gallery,author_uid,video_embed,author_pic,place)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",(
        ter, d.get("category","Historia y Memoria"), d.get("type","texto"),
        title, body, sanitise(d.get("author",""),80) or "Comunidad", sanitise(d.get("author_role",""),80),
        primary, d.get("media_type",""),
        d.get("lat") or place_lat, d.get("lon") or place_lon, lang,
        json.dumps(gallery) if gallery else "", author_uid,
        json.dumps(video_embed) if video_embed else "", author_pic, place_name))
    db.commit()
    logger.info(f"Nueva contribución #{cur.lastrowid}: {title} ({ter}) · {len(gallery)} foto(s)")
    return jsonify({"status":"success","id":cur.lastrowid})

@app.route("/api/contributions")
def api_contributions():
    db = get_db()
    ter    = request.args.get("territory","")
    cat    = request.args.get("category","")
    layer  = request.args.get("layer","")
    status = request.args.get("status","published")
    q = ("SELECT c.*, "
         # Foto de quien publicó: la guardada con la historia o, si no hay,
         # la de su cuenta. Subconsultas y no JOIN, para no volver ambiguas
         # las columnas territory/created_at que comparten ambas tablas.
         # La foto actual de la cuenta va primero: si la persona la cambia,
         # sus relatos la muestran; la guardada con la historia es el respaldo
         # de quien publicó sin cuenta.
         "COALESCE((SELECT NULLIF(u.profile_pic,'') FROM users u "
         "  WHERE c.author_uid<>'' AND u.username=c.author_uid), NULLIF(c.author_pic,''), '') AS author_photo, "
         "(SELECT u.role FROM users u WHERE c.author_uid<>'' AND u.username=c.author_uid) AS author_account_role, "
         "(SELECT u.id FROM users u WHERE c.author_uid<>'' AND u.username=c.author_uid) AS author_user_id, "
         "(SELECT COUNT(*) FROM likes    WHERE contribution_id=c.id) AS like_count, "
         "(SELECT COUNT(*) FROM comments WHERE contribution_id=c.id AND COALESCE(hidden,0)=0) AS comment_count "
         "FROM contributions c WHERE 1=1")
    params = []
    # Solo el personal ve lo que aún no está publicado. Cualquier otra persona
    # ve lo publicado y, como mucho, sus propios envíos pendientes o
    # rechazados (identificados por su sesión o su id persistente).
    personal = _rol_actual() in ("admin", "institutional")
    yo = _owner_uid({"voter": request.args.get("viewer", "")})
    if request.args.get("mine") == "1":
        if not yo:
            return jsonify([])
        q += " AND author_uid<>'' AND author_uid=?"; params.append(yo)
    if status == "published":
        q += " AND approved=1"
    elif status in ("pending", "rejected"):
        q += " AND approved=" + ("0" if status == "pending" else "-1")
        if not personal:
            q += " AND author_uid<>'' AND author_uid=?"; params.append(yo or "\x00")
    else:   # «all»
        if not personal:
            q += " AND (approved=1 OR (author_uid<>'' AND author_uid=?))"; params.append(yo or "\x00")
    if ter: q+=" AND territory=?"; params.append(ter)
    if cat: q+=" AND category=?";  params.append(cat)
    # F5: layer filter
    if layer:
        cats = LAYER_CATEGORY_MAP.get(layer,[])
        if cats:
            q+=" AND category IN ("+",".join("?"*len(cats))+")"
            params.extend(cats)
    # Explorador de historias: Todas (media) · Fotos · Videos · Música y voces.
    # Una contribución con galería cuenta como foto aunque su media_type sea otro.
    mtype = request.args.get("media_type", "")
    _galeria = "(media_gallery IS NOT NULL AND media_gallery!='' AND media_gallery!='[]')"
    if mtype == "foto":
        q += " AND (media_type='foto' OR " + _galeria + ")"
    elif mtype == "video":
        q += " AND ((media_type='video' AND media_url!='') OR COALESCE(video_embed,'')!='')"
    elif mtype == "audio":
        q += " AND media_type='audio' AND media_url!=''"
    elif mtype == "texto":
        # Relatos escritos: sin media y entrados por el portal «Historia».
        q += " AND " + _SQL_RELATO
        params.extend(_CATEGORIAS_NO_RELATO)
    elif mtype == "media":
        q += (" AND ((media_type IN ('video','audio') AND media_url!='') "
              "OR COALESCE(video_embed,'')!='' "
              "OR media_type='foto' OR " + _galeria + ")")
    order = ("view_count DESC, created_at DESC"
             if request.args.get("sort") == "views" else "created_at DESC")
    q, params = paginate(q, params, request, order)
    out = rows(db.execute(q,params))
    # Same can_delete hint as the moderation queue, so the author's own
    # 🗑️ button appears on their story wherever it is listed.
    viewer = _owner_uid({"voter": request.args.get("viewer","")})
    for c in out:
        c["can_delete"] = _may_delete_contribution(db, c, viewer)
        # Solo la persona autora ve el menú «⋯ → Borrar» en las publicaciones.
        c["is_mine"] = bool(viewer and (c.get("author_uid") or "") == viewer)
        c.pop("author_uid", None)
    return jsonify(out)

def _owner_uid(d=None):
    """The durable identity of whoever is acting right now.

    Logged-in visitors are their username. Anonymous visitors are the
    persistent_ id their browser has been using for moderation votes and
    likes all along. Returns "" when neither is available, and "" never
    matches anything — an unknown caller owns nothing.
    """
    if session.get("username"):
        return session["username"].strip()
    d = d or {}
    uid = str(d.get("author_uid") or d.get("voter") or "").strip()
    # Only accept the persistent_ shape, and only at a length that is not
    # trivially guessable, so nobody can claim ownership of someone else's
    # post by posting a short made-up id.
    if uid.startswith("persistent_") and len(uid) >= 20:
        return uid
    return ""

def _may_delete_contribution(db, c, actor_uid=""):
    """Who is allowed to remove a contribution.

    1. Admins — always.
    2. The author, identified by the durable author_uid captured when the
       contribution was created. This is the path that makes deletion work
       for anonymous contributors, who are the majority on this platform.
    Contributions created before author_uid existed can only be removed by
    an admin. They used to be matched by the author's typed name, which let
    anyone who registered as "Comunidad" delete every unsigned story.
    """
    if session.get("role") == "admin":
        return True
    owner = (c.get("author_uid") or "").strip()
    if owner and actor_uid and owner == actor_uid:
        return True
    return False

@app.route("/api/contributions/<int:cid>", methods=["DELETE"])
@rate_limit(20, 60)
@csrf_required
def api_delete_contribution(cid):
    """Delete a contribution.

    Open to the person who posted it — logged in or anonymous — and to
    admins. Anonymous ownership rests on the durable author_uid stored at
    creation time; the browser proves it by sending the same persistent_
    id it uses for votes and likes. Authorisation is decided here on the
    server; the button in the UI is only a hint.
    """
    d = request.json or {}
    db = get_db()
    c = row(db.execute("SELECT id,author,author_uid FROM contributions WHERE id=?", (cid,)))
    if not c:
        return jsonify({"status":"error","message":"Contribución no encontrada"}), 404
    is_admin = session.get("role") == "admin"
    if not _may_delete_contribution(db, c, _owner_uid(d)):
        return jsonify({"status":"error",
                        "message":"Solo quien publicó esta contribución puede borrarla."}), 403
    db.execute("DELETE FROM moderation_votes WHERE contribution_id=?", (cid,))
    db.execute("DELETE FROM likes WHERE contribution_id=?", (cid,))
    db.execute("DELETE FROM reactions WHERE contribution_id=?", (cid,))
    db.execute("DELETE FROM comments WHERE contribution_id=?", (cid,))
    db.execute("DELETE FROM contributions WHERE id=?", (cid,))
    db.commit()
    logger.info("Contribution #%s deleted by %s (admin=%s)", cid, session.get("username","anon"), is_admin)
    return jsonify({"status":"success"})

# ── FEED SOCIAL: LIKES ──────────────────────────────────────────
def _resolve_voter(d):
    """Same durable-identity pattern as moderation votes (A2): prefer the
    Flask session username, else require a client-generated persistent_ id."""
    if session.get("username"):
        return session["username"]
    voter = (d.get("voter") or "").strip()
    if not voter.startswith("persistent_") or len(voter) < 20:
        return None
    return voter

@app.route("/api/like/<int:cid>", methods=["POST"])
@rate_limit(60, 60)
@csrf_required
def api_toggle_like(cid):
    d = request.json or {}
    voter = _resolve_voter(d)
    if not voter:
        return jsonify({"status":"error","message":"ID de votante inválido"}), 400
    db = get_db()
    if not row(db.execute("SELECT id FROM contributions WHERE id=?", (cid,))):
        return jsonify({"status":"error","message":"Contribución no encontrada"}), 404
    existing = row(db.execute("SELECT id FROM likes WHERE contribution_id=? AND voter=?", (cid, voter)))
    if existing:
        db.execute("DELETE FROM likes WHERE id=?", (existing["id"],))
        liked = False
    else:
        db.execute("INSERT INTO likes (contribution_id,voter) VALUES (?,?)", (cid, voter))
        liked = True
        c = row(db.execute("SELECT title,author_uid FROM contributions WHERE id=?", (cid,)))
        owner = (c or {}).get("author_uid") or ""
        if owner and owner != voter:
            actor_name = session.get("username") or "Alguien de la comunidad"
            notify(db, owner, "like", actor_name,
                   f'A {actor_name} le gustó tu historia "{c["title"]}"', "entrevistas", cid)
    db.commit()
    count = db.execute("SELECT COUNT(*) FROM likes WHERE contribution_id=?", (cid,)).fetchone()[0]
    return jsonify({"status":"success","liked":liked,"count":count})

@app.route("/api/likes/<int:cid>")
def api_like_status(cid):
    voter = request.args.get("voter","").strip()
    db = get_db()
    count = db.execute("SELECT COUNT(*) FROM likes WHERE contribution_id=?", (cid,)).fetchone()[0]
    liked = False
    if session.get("username"):
        liked = bool(row(db.execute("SELECT id FROM likes WHERE contribution_id=? AND voter=?", (cid, session["username"]))))
    elif voter:
        liked = bool(row(db.execute("SELECT id FROM likes WHERE contribution_id=? AND voter=?", (cid, voter))))
    return jsonify({"count":count,"liked":liked})

# ── FEED SOCIAL: COMMENTS ───────────────────────────────────────
@app.route("/api/comments/<int:cid>")
def api_get_comments(cid):
    db = get_db()
    page     = request.args.get("page", 1, type=int)
    per_page = min(request.args.get("per_page", 50, type=int), 100)
    q = ("SELECT id,contribution_id,author,body,created_at FROM comments "
         "WHERE contribution_id=? AND COALESCE(hidden,0)=0 ORDER BY created_at ASC LIMIT ? OFFSET ?")
    items = rows(db.execute(q, (cid, per_page, (page-1)*per_page)))
    return jsonify(items)

@app.route("/api/comment/<int:cid>", methods=["POST"])
@rate_limit(20, 60)
@csrf_required
def api_add_comment(cid):
    db = get_db()
    if not row(db.execute("SELECT id FROM contributions WHERE id=?", (cid,))):
        return jsonify({"status":"error","message":"Contribución no encontrada"}), 404
    d = request.json or {}
    body = sanitise((d.get("body") or "").strip(), 500)
    if not body:
        return jsonify({"status":"error","message":"El comentario no puede estar vacío"}), 400
    author = sanitise((d.get("author") or session.get("username") or "Comunidad").strip(), 100)
    cur = db.execute("INSERT INTO comments (contribution_id,author,body,author_uid) VALUES (?,?,?,?)",
                     (cid, author, body, _owner_uid(d)))
    c = row(db.execute("SELECT title,author_uid FROM contributions WHERE id=?", (cid,)))
    owner = (c or {}).get("author_uid") or ""
    if owner and owner != _owner_uid(d):
        notify(db, owner, "comment", author,
               f'{author} comentó en tu historia "{c["title"]}"', "entrevistas", cid)
    db.commit()
    return jsonify({"status":"success","id":cur.lastrowid,"author":author,"body":body})

@app.route("/api/comment/<int:comment_id>", methods=["DELETE"])
@csrf_required
def api_delete_comment(comment_id):
    db = get_db()
    c = row(db.execute("SELECT id,author,author_uid,contribution_id FROM comments WHERE id=?", (comment_id,)))
    if not c:
        return jsonify({"status":"error","message":"Comentario no encontrado"}), 404
    is_admin = _rol_actual() == "admin"
    # La autoría se comprueba con el id durable guardado al comentar, no con el
    # nombre visible (que cualquiera puede escribir o registrar como usuario).
    me = _owner_uid(request.get_json(silent=True) or {})
    is_author = bool(c.get("author_uid")) and c.get("author_uid") == me
    if not (is_admin or is_author):
        return jsonify({"status":"error","message":"No tienes permiso para borrar este comentario"}), 403
    db.execute("DELETE FROM comments WHERE id=?", (comment_id,))
    db.commit()
    return jsonify({"status":"success"})

# ── INTERACCIÓN SOCIAL v3 §10: reacciones · reportes · detalle ──
REACTIONS = {"love": "❤️", "happy": "😊", "sad": "😢", "wow": "😮", "clap": "👏", "strength": "✊🏾"}
REPORT_HIDE_COMMENT = 3        # reportes distintos que ocultan un comentario
REPORT_REQUEUE_CONTENT = 5     # reportes distintos que devuelven un contenido a moderación

def _reaction_summary(db, cids, reactor=None):
    out = {int(c): {"counts": {}, "total": 0, "mine": None, "comments": 0} for c in cids}
    if not out:
        return out
    marks = ",".join("?" * len(out))
    ids = list(out.keys())
    for r in db.execute(f"SELECT contribution_id,emoji,COUNT(*) n FROM reactions "
                        f"WHERE contribution_id IN ({marks}) GROUP BY contribution_id,emoji", ids):
        o = out[r[0]]; o["counts"][r[1]] = r[2]; o["total"] += r[2]
    for r in db.execute(f"SELECT contribution_id,COUNT(*) FROM comments WHERE contribution_id IN ({marks}) "
                        f"AND COALESCE(hidden,0)=0 GROUP BY contribution_id", ids):
        out[r[0]]["comments"] = r[1]
    if reactor:
        for r in db.execute(f"SELECT contribution_id,emoji FROM reactions WHERE reactor=? "
                            f"AND contribution_id IN ({marks})", [reactor] + ids):
            out[r[0]]["mine"] = r[1]
    return out

@app.route("/api/reactions")
def api_reactions():
    try:
        ids = [int(x) for x in (request.args.get("ids", "") or "").split(",") if x.strip()][:60]
    except ValueError:
        return jsonify({"status": "error", "message": "ids inválidos"}), 400
    who = session.get("username") or None
    v = (request.args.get("voter", "") or "").strip()
    if not who and v.startswith("persistent_") and len(v) >= 20:
        who = v
    return jsonify(_reaction_summary(get_db(), ids, who))

@app.route("/api/react/<int:cid>", methods=["POST"])
@rate_limit(60, 60)
@csrf_required
def api_react(cid):
    d = request.json or {}
    emoji = (d.get("emoji") or "").strip()
    if emoji not in REACTIONS:
        return jsonify({"status": "error", "message": "Reacción no válida"}), 400
    reactor = _resolve_voter(d)
    if not reactor:
        return jsonify({"status": "error", "message": "ID de votante inválido"}), 400
    db = get_db()
    # Sólo el contenido publicado admite reacciones (regla de publicación).
    c = row(db.execute("SELECT id,title,author,author_uid FROM contributions WHERE id=? AND approved=1", (cid,)))
    if not c:
        return jsonify({"status": "error", "message": "Contenido no disponible"}), 404
    prev = row(db.execute("SELECT id,emoji FROM reactions WHERE contribution_id=? AND reactor=?", (cid, reactor)))
    if prev and prev["emoji"] == emoji:
        db.execute("DELETE FROM reactions WHERE id=?", (prev["id"],))      # tocar la misma la retira
        mine = None
    elif prev:
        db.execute("UPDATE reactions SET emoji=?,created_at=CURRENT_TIMESTAMP WHERE id=?", (emoji, prev["id"]))
        mine = emoji
    else:
        db.execute("INSERT INTO reactions (contribution_id,reactor,emoji) VALUES (?,?,?)", (cid, reactor, emoji))
        mine = emoji
        owner = c.get("author_uid") or ""
        if owner and owner != reactor:
                actor = session.get("username") or "Alguien de la comunidad"
                notify(db, owner, "like", actor,
                       f'{actor} reaccionó {REACTIONS[emoji]} a tu historia "{c["title"]}"', "entrevistas", cid)
    # ❤️ se refleja en «likes» para que recomendaciones y contadores sigan coherentes.
    if mine == "love":
        db.execute("INSERT OR IGNORE INTO likes (contribution_id,voter) VALUES (?,?)", (cid, reactor))
    else:
        db.execute("DELETE FROM likes WHERE contribution_id=? AND voter=?", (cid, reactor))
    db.commit()
    return jsonify({"status": "success", **_reaction_summary(db, [cid], reactor)[cid]})

@app.route("/api/report", methods=["POST"])
@rate_limit(20, 60)
@csrf_required
def api_report():
    d = request.json or {}
    ttype = d.get("type")
    try:
        tid = int(d.get("id") or 0)
    except (TypeError, ValueError):
        tid = 0
    if ttype not in ("comment", "contribution") or tid <= 0:
        return jsonify({"status": "error", "message": "Reporte no válido"}), 400
    reporter = _resolve_voter(d)
    if not reporter:
        return jsonify({"status": "error", "message": "ID de votante inválido"}), 400
    db = get_db()
    table = "comments" if ttype == "comment" else "contributions"
    if not row(db.execute(f"SELECT id FROM {table} WHERE id=?", (tid,))):
        return jsonify({"status": "error", "message": "No encontrado"}), 404
    db.execute("INSERT OR IGNORE INTO content_reports (target_type,target_id,reporter,reason) VALUES (?,?,?,?)",
               (ttype, tid, reporter, sanitise((d.get("reason") or "").strip(), 300)))
    n = db.execute("SELECT COUNT(*) FROM content_reports WHERE target_type=? AND target_id=?",
                   (ttype, tid)).fetchone()[0]
    hidden = False
    if ttype == "comment" and n >= REPORT_HIDE_COMMENT:
        db.execute("UPDATE comments SET hidden=1 WHERE id=?", (tid,)); hidden = True
    if ttype == "contribution":
        for a in rows(db.execute("SELECT username FROM users WHERE role='admin'")):
            notify(db, a["username"], "report", "Comunidad",
                   f"Contenido #{tid} reportado ({n} reporte{'s' if n != 1 else ''})", "moderacion", tid)
        if n >= REPORT_REQUEUE_CONTENT:
            # Vuelve a la cola de moderación existente; no se borra nada.
            db.execute("UPDATE contributions SET approved=0,status='pending' WHERE id=?", (tid,)); hidden = True
    db.commit()
    return jsonify({"status": "success", "reports": n, "hidden": hidden})

@app.route("/api/contributions/<int:cid>")
def api_contribution_detail(cid):
    """Detalle público de un contenido publicado (enlaces compartidos ?story=ID)."""
    db = get_db()
    c = row(db.execute(
        "SELECT id,title,body,territory,category,author,media_url,media_type,media_gallery,video_embed,view_count,created_at "
        "FROM contributions WHERE id=? AND approved=1", (cid,)))
    if not c:
        return jsonify({"status": "error", "message": "Contenido no disponible"}), 404
    return jsonify(c)

def _current_identity():
    """Resolve who's asking: logged-in username, else the client's persistent_
    voter id passed as ?voter=. Returns None if neither is available."""
    if session.get("username"):
        return session["username"]
    v = request.args.get("voter","").strip()
    return v if v.startswith("persistent_") and len(v) >= 20 else None

@app.route("/api/notifications")
def api_notifications():
    """Novedades v7: «seen» (la campana se abrió) es distinto de «is_read» (se
    tocó la notificación). La campana cuenta las no vistas; la lista resalta
    las no leídas hasta que se abren, como en las apps profesionales."""
    who = _current_identity()
    if not who:
        return jsonify({"status":"error","message":"Inicia sesión para ver tus notificaciones"}), 401
    db = get_db()
    items = rows(db.execute(
        "SELECT n.*, (SELECT NULLIF(u.profile_pic,'') FROM users u WHERE u.name=n.actor OR u.username=n.actor LIMIT 1) AS actor_pic "
        "FROM notifications n WHERE n.recipient=? ORDER BY n.created_at DESC, n.id DESC LIMIT 60", (who,)))
    unread = db.execute(
        "SELECT COUNT(*) FROM notifications WHERE recipient=? AND is_read=0", (who,)).fetchone()[0]
    unseen = db.execute(
        "SELECT COUNT(*) FROM notifications WHERE recipient=? AND COALESCE(seen,0)=0 AND is_read=0", (who,)).fetchone()[0]
    return jsonify({"items": items, "unread": unread, "unseen": unseen})

@app.route("/api/notifications/seen", methods=["POST"])
@csrf_required
def api_notifications_seen():
    who = _current_identity()
    if not who:
        return jsonify({"status":"error","message":"No autenticado"}), 401
    db = get_db()
    db.execute("UPDATE notifications SET seen=1 WHERE recipient=?", (who,))
    db.commit()
    return jsonify({"status":"success"})

@app.route("/api/notifications/read", methods=["POST"])
@csrf_required
def api_notifications_read():
    """Sin cuerpo: todas leídas. Con {"id": n}: solo esa. Con {"ids": [...]}:
    las que la persona tuvo a la vista al abrir la campana (de quien la pide)."""
    who = _current_identity()
    if not who:
        return jsonify({"status":"error","message":"No autenticado"}), 401
    db = get_db()
    body = request.get_json(silent=True) or {}
    nid = body.get("id")
    ids = body.get("ids")
    if isinstance(ids, list):
        try:
            ids = [int(x) for x in ids][:200]
        except (TypeError, ValueError):
            return jsonify({"status":"error"}), 400
        if ids:
            db.execute(f"UPDATE notifications SET is_read=1, seen=1 WHERE recipient=? AND id IN ({','.join('?'*len(ids))})",
                       (who, *ids))
    elif nid:
        try:
            db.execute("UPDATE notifications SET is_read=1, seen=1 WHERE recipient=? AND id=?", (who, int(nid)))
        except (TypeError, ValueError):
            return jsonify({"status":"error"}), 400
    else:
        db.execute("UPDATE notifications SET is_read=1, seen=1 WHERE recipient=?", (who,))
    db.commit()
    return jsonify({"status":"success"})

