# ── SALA DE VOZ: SEÑALIZACIÓN ────────────────────────────────
# Una llamada WebRTC necesita que los dos extremos se intercambien, antes de
# hablar, una descripción de lo que saben hacer y una lista de direcciones por
# las que se les puede alcanzar. Ese intercambio es todo lo que hace el
# servidor. Una vez establecido el canal, el audio va de un navegador al otro
# sin volver a pasar por aquí, lo que mantiene la conversación fuera del
# alcance de la plataforma y de cualquier intermediario.
#
# La entrega es por sondeo y no por conexión persistente: un despliegue WSGI
# corriente no sostiene WebSockets, y una llamada tarda un segundo más en
# establecerse pero funciona en el alojamiento que el proyecto puede pagar.

CALL_TTL      = 12.0     # segundos sin latido tras los que un par se da por ido
CALL_MAX_PARES = 6       # malla completa: cada par habla con todos los demás


def _sala_privada_ok(db, room, para_entrar=False):
    """Las salas «dm-…» son de una llamada directa: sólo entran las dos cuentas
    de la invitación, y sólo mientras la invitación sigue viva. Las salas de
    canal (general, territorios, grupos) siguen abiertas como antes."""
    if not room.startswith("dm-"):
        return True
    me = session.get("user_id")
    if not me:
        return False
    inv = row(db.execute(
        "SELECT caller_id, callee_id, estado FROM call_invites WHERE room=?", (room,)))
    if not inv or me not in (inv["caller_id"], inv["callee_id"]):
        return False
    vivos = ("sonando", "aceptada")
    if inv["estado"] not in vivos:
        # Salir y recibir el último «adiós» sigue permitido; entrar, no.
        return not para_entrar
    # Quien recibe entra sólo después de aceptar; quien llama, desde el timbre.
    if para_entrar and me == inv["callee_id"] and inv["estado"] != "aceptada":
        return False
    return True


def _limpiar_llamadas(db, room):
    """Retira presencias caducadas y señales viejas de la sala."""
    limite = time.time() - CALL_TTL
    idos = [r["peer"] for r in rows(db.execute(
        "SELECT peer FROM call_peers WHERE room=? AND visto<?", (room, limite)))]
    if idos:
        db.execute("DELETE FROM call_peers WHERE room=? AND visto<?", (room, limite))
        db.executemany("DELETE FROM call_signals WHERE room=? AND (emisor=? OR destino=?)",
                       [(room, p, p) for p in idos])
    db.execute("DELETE FROM call_signals WHERE creado < ?", (time.time() - 120,))
    return idos


@app.route("/api/call/join", methods=["POST"])
@rate_limit(60, 60)
@csrf_required
def api_call_join():
    d = request.json or {}
    room = (d.get("room") or "general").strip()[:64]
    peer = (d.get("peer") or "").strip()[:64]
    nombre = (d.get("nombre") or "Invitado").strip()[:60]
    if not peer:
        return jsonify({"status": "error", "message": "peer requerido"}), 400
    db = get_db()
    if not _sala_privada_ok(db, room, para_entrar=True):
        return jsonify({"status": "error", "message": "Esta llamada no es tuya o ya terminó"}), 403
    _limpiar_llamadas(db, room)
    otros = rows(db.execute(
        "SELECT peer,nombre FROM call_peers WHERE room=? AND peer<>?", (room, peer)))
    # En una llamada directa caben dos: quien llama y quien contesta.
    maximo = 2 if room.startswith("dm-") else CALL_MAX_PARES
    if len(otros) >= maximo:
        # La malla crece con el cuadrado de los participantes: con siete, cada
        # teléfono sostendría seis conexiones de subida a la vez. El límite no
        # es arbitrario, es la frontera donde una llamada en el territorio deja
        # de oírse.
        return jsonify({"status": "full", "max": maximo}), 409
    db.execute("INSERT OR REPLACE INTO call_peers (room,peer,nombre,visto) VALUES (?,?,?,?)",
               (room, peer, nombre, time.time()))
    db.commit()
    return jsonify({"status": "success", "peers": otros, "ttl": CALL_TTL})


@app.route("/api/call/signal", methods=["POST"])
@rate_limit(600, 60)
@csrf_required
def api_call_signal():
    d = request.json or {}
    room = (d.get("room") or "general").strip()[:64]
    for campo in ("peer", "destino", "tipo"):
        if not (d.get(campo) or "").strip():
            return jsonify({"status": "error", "message": f"{campo} requerido"}), 400
    if d["tipo"] not in ("offer", "answer", "ice", "bye"):
        return jsonify({"status": "error", "message": "tipo no admitido"}), 400
    carga = json.dumps(d.get("carga"))
    if len(carga) > 64_000:
        return jsonify({"status": "error", "message": "carga excesiva"}), 413
    db = get_db()
    if not _sala_privada_ok(db, room):
        return jsonify({"status": "error", "message": "sala no permitida"}), 403
    db.execute("INSERT INTO call_signals (room,emisor,destino,tipo,carga,creado) "
               "VALUES (?,?,?,?,?,?)",
               (room, d["peer"][:64], d["destino"][:64], d["tipo"], carga, time.time()))
    db.commit()
    return jsonify({"status": "success"})


@app.route("/api/call/poll")
@rate_limit(600, 60)
def api_call_poll():
    room = (request.args.get("room") or "general").strip()[:64]
    peer = (request.args.get("peer") or "").strip()[:64]
    if not peer:
        return jsonify({"status": "error"}), 400
    db = get_db()
    if not _sala_privada_ok(db, room):
        return jsonify({"status": "error", "message": "sala no permitida"}), 403
    db.execute("UPDATE call_peers SET visto=? WHERE room=? AND peer=?",
               (time.time(), room, peer))
    idos = _limpiar_llamadas(db, room)
    pendientes = rows(db.execute(
        "SELECT id,emisor,tipo,carga FROM call_signals WHERE room=? AND destino=? "
        "ORDER BY id", (room, peer)))
    if pendientes:
        # Entregado es borrado: la señalización no deja rastro de la conversación.
        db.executemany("DELETE FROM call_signals WHERE id=?",
                       [(m["id"],) for m in pendientes])
    otros = rows(db.execute(
        "SELECT peer,nombre FROM call_peers WHERE room=? AND peer<>?", (room, peer)))
    db.commit()
    for m in pendientes:
        try: m["carga"] = json.loads(m["carga"])
        except Exception: m["carga"] = None
    return jsonify({"status": "success", "senales": pendientes,
                    "peers": otros, "idos": idos})


@app.route("/api/call/leave", methods=["POST"])
@rate_limit(60, 60)
@csrf_required
def api_call_leave():
    d = request.json or {}
    room = (d.get("room") or "general").strip()[:64]
    peer = (d.get("peer") or "").strip()[:64]
    db = get_db()
