@app.route("/api/trending")
def api_trending():
    """Trending uploaded media for the dashboard Fotos / Videos sections.
    Ranked by view_count (then recency). Only approved contributions."""
    db = get_db()
    limit = min(int(request.args.get("limit", 12) or 12), 40)
    photos = rows(db.execute(
        "SELECT id,title,territory,author,media_url,media_type,media_gallery,view_count,created_at "
        "FROM contributions WHERE approved=1 AND "
        "(media_type='foto' OR (media_gallery IS NOT NULL AND media_gallery!='' AND media_gallery!='[]')) "
        "ORDER BY view_count DESC, created_at DESC LIMIT ?", (limit,)))
    videos = rows(db.execute(
        "SELECT id,title,territory,author,media_url,media_type,video_embed,view_count,created_at "
        "FROM contributions WHERE approved=1 AND "
        "(media_type='video' OR COALESCE(video_embed,'')!='') "
        "ORDER BY view_count DESC, created_at DESC LIMIT ?", (limit,)))
    # La voz grabada es el material más propio de este archivo y hasta ahora
    # solo aparecía en una pestaña interior. En la portada va junto a lo demás:
    # una entrevista de campo no vale menos que una fotografía.
    audios = rows(db.execute(
        "SELECT id,title,territory,author,media_url,media_type,view_count,created_at "
        "FROM contributions WHERE approved=1 AND media_type='audio' "
        "ORDER BY view_count DESC, created_at DESC LIMIT ?", (limit,)))
    return jsonify({"photos": photos, "videos": videos, "audios": audios})

@app.route("/api/contributions/geo")
def api_geo():
    db = get_db()
    ter   = request.args.get("territory","")
    layer = request.args.get("layer","")
    q = "SELECT id,territory,category,title,author,lat,lon,created_at,media_url,media_type,media_gallery FROM contributions WHERE approved=1 AND lat IS NOT NULL"
    params = []
    if ter:   q+=" AND territory=?"; params.append(ter)
    if layer:
        cats = LAYER_CATEGORY_MAP.get(layer,[])
        if cats:
            q+=" AND category IN ("+",".join("?"*len(cats))+")"; params.extend(cats)
    return jsonify(rows(db.execute(q,params)))

# ── RELATOS EN EL MAPA (2.1) ─────────────────────────────────
# Lugares con nombre que reúnen relatos, narradores con su consentimiento y
# una bienvenida por territorio. Las denuncias no entran: su ubicación puede
# poner en riesgo a quien denuncia y ya tienen su propio circuito.
_SQL_NO_DENUNCIA = ("LOWER(COALESCE(c.category,'')) NOT LIKE '%denuncia%' "
                    "AND LOWER(COALESCE(c.type,'')) <> 'denuncia'")
_TIPOS_LUGAR = ("río", "estero", "playa", "bosque", "manglar", "vereda", "barrio", "consejo comunitario",
                "lugar sagrado", "cementerio", "muelle", "plaza", "escuela", "casa de memoria", "otro")

def _nombre_territorio(slug):
    if slug in TERRITORIES:
        return TERRITORIES[slug]["name"]
    d = _DEPT_BY_SLUG.get(slug)
    return (d.get("name") or slug).replace(" (departamento)", "") if d else slug

def _centro_territorio(slug):
    if slug in TERRITORIES:
        return TERRITORIES[slug]["lat"], TERRITORIES[slug]["lon"]
    if slug in _DEPT_BY_SLUG:
        return _dept_center(slug)
    return None

def _narradores(raw):
    try:
        L = json.loads(raw) if raw else []
    except (TypeError, ValueError):
        return []
    out = []
    for n in L if isinstance(L, list) else []:
        nombre = sanitise(str((n or {}).get("nombre", "")), 80).strip()
        if nombre:
            foto = safe_media_url(str((n or {}).get("foto", "")))
            out.append({"nombre": nombre, "foto": foto if foto.startswith(("/gallery/", "/uploads/")) else ""})
    return out[:6]

_BIENVENIDA_DEFECTO = ("Este mapa reúne relatos de la comunidad en los lugares donde ocurren. Elige un "
                       "lugar en el mapa o en la lista para escuchar, ver o leer lo que la gente cuenta "
                       "de él. Cada relato se publica después de la moderación y con el permiso de quien "
                       "lo narra.")

@app.route("/api/relatos/territorios")
def api_relatos_territorios():
    """Territorios y departamentos que tienen relatos publicados en el mapa."""
    db = get_db()
    cuenta = {r["territory"]: r["n"] for r in rows(db.execute(
        "SELECT c.territory, COUNT(*) AS n FROM contributions c WHERE c.approved=1 "
        "AND (c.lat IS NOT NULL OR c.place_id IS NOT NULL) AND " + _SQL_NO_DENUNCIA + " GROUP BY c.territory"))}
    out = [{"slug": s, "name": t["name"], "icon": t.get("icon", ""), "narp": True, "n": cuenta.get(s, 0)}
           for s, t in TERRITORIES.items()]
    out += [{"slug": s, "name": _nombre_territorio(s), "icon": "", "narp": False, "n": n}
            for s, n in sorted(cuenta.items()) if s not in TERRITORIES and s in _DEPT_BY_SLUG]
    return jsonify({"status": "ok", "territorios": out})

@app.route("/api/relatos")
def api_relatos():
    """Relatos publicados de un territorio, agrupados por lugar."""
    ter = (request.args.get("territory") or "").strip()
    centro = _centro_territorio(ter)
    if not centro:
        return jsonify({"status": "error", "message": "Territorio no válido"}), 400
    db = get_db()
    lugares = {l["id"]: dict(l, relatos=[], auto=False) for l in rows(db.execute(
        "SELECT * FROM lugares WHERE territory=? ORDER BY nombre", (ter,)))}
    filas = rows(db.execute(
        "SELECT c.id, c.title, c.body, c.author, c.author_role, c.category, c.type, c.media_url, c.media_type, "
        "c.media_gallery, c.video_embed, c.language, c.lat, c.lon, c.place, c.place_id, c.narradores, c.created_at, "
        "COALESCE((SELECT NULLIF(u.profile_pic,'') FROM users u WHERE c.author_uid<>'' AND u.username=c.author_uid), "
        "NULLIF(c.author_pic,''), '') AS author_photo "
        "FROM contributions c WHERE c.approved=1 AND c.territory=? AND " + _SQL_NO_DENUNCIA +
        " AND (c.lat IS NOT NULL OR c.place_id IS NOT NULL) ORDER BY c.created_at DESC", (ter,)))
    auto = {}
    for c in filas:
        try:
            galeria = json.loads(c["media_gallery"]) if c["media_gallery"] else []
        except (TypeError, ValueError):
            galeria = []
        rel = {"id": c["id"], "title": c["title"], "excerpt": re.sub(r"https?://\S+", "", c["body"] or "").strip()[:260],
               "body": c["body"] or "", "author": c["author"] or "Comunidad", "author_role": c["author_role"] or "",
               "author_photo": c["author_photo"] or "", "category": c["category"] or "", "language": c["language"] or "es",
               "media_url": c["media_url"] or "", "media_type": c["media_type"] or "",
               "foto": next((g for g in galeria if g), "") or (c["media_url"] if (c["media_type"] or "") in ("foto", "imagen", "image") else ""),
               "video_embed": c["video_embed"] or "", "narradores": _narradores(c["narradores"]),
               "created_at": (c["created_at"] or "")[:10], "place_id": c["place_id"]}
        if c["place_id"] in lugares:
            lugares[c["place_id"]]["relatos"].append(rel)
            continue
        lat, lon = c["lat"], c["lon"]
        if lat is None or lon is None:
            lat, lon = centro
        clave = (round(float(lat), 3), round(float(lon), 3))
        g = auto.get(clave)
        if not g:
            general = abs(clave[0] - round(centro[0], 3)) < 0.002 and abs(clave[1] - round(centro[1], 3)) < 0.002
            g = auto[clave] = {"id": f"auto-{clave[0]}_{clave[1]}", "territory": ter,
                               "nombre": (c["place"] or _nombre_territorio(ter)) + (" · ubicación general" if general else ""),
                               "tipo": "", "lat": clave[0], "lon": clave[1], "foto": "", "descripcion": "",
                               "auto": True, "general": general, "relatos": []}
        g["relatos"].append(rel)
    out = [l for l in lugares.values() if l["relatos"]] + list(auto.values())
    for l in out:
        if not l.get("foto"):
            l["foto"] = next((r["foto"] for r in l["relatos"] if r["foto"]), "")
    b = row(db.execute("SELECT texto, idioma, actualizado_en FROM bienvenidas WHERE territory=?", (ter,)))
    vacios = [dict(l, relatos=[], auto=False) for l in lugares.values() if not l["relatos"]]
    return jsonify({"status": "ok",
                    "territorio": {"slug": ter, "name": _nombre_territorio(ter), "lat": centro[0], "lon": centro[1],
                                   "icon": TERRITORIES.get(ter, {}).get("icon", "")},
                    "bienvenida": b or {"texto": _BIENVENIDA_DEFECTO, "idioma": "es", "defecto": True},
                    "lugares": out, "lugares_vacios": vacios, "tipos_lugar": list(_TIPOS_LUGAR)})

def _usuario_nombre():
    r = get_db().execute("SELECT username FROM users WHERE id=?", (session.get("user_id"),)).fetchone()
    return r[0] if r else ""

@app.route("/api/relatos/lugares", methods=["POST"])
@csrf_required
@require_role("admin")
def api_relatos_lugar_guardar():
    d = request.get_json(silent=True) or {}
    ter = (d.get("territory") or "").strip()
    nombre = sanitise(str(d.get("nombre", "")), 80).strip()
    if not _centro_territorio(ter) or not nombre:
        return jsonify({"status": "error", "message": "Indica el territorio y el nombre del lugar."}), 400
    try:
        lat, lon = float(d.get("lat")), float(d.get("lon"))
    except (TypeError, ValueError):
        return jsonify({"status": "error", "message": "Toca el mapa para ubicar el lugar."}), 400
    if not (-5 <= lat <= 14 and -82 <= lon <= -66):
        return jsonify({"status": "error", "message": "La ubicación está fuera de Colombia."}), 400
    tipo = sanitise(str(d.get("tipo", "")), 40).strip().lower()
    foto = safe_media_url(str(d.get("foto", "")))
    foto = foto if foto.startswith(("/gallery/", "/uploads/")) else ""
    desc = sanitise(str(d.get("descripcion", "")), 600)
    db = get_db()
    lid = d.get("id")
    if lid:
        cur = db.execute("UPDATE lugares SET nombre=?, tipo=?, lat=?, lon=?, foto=?, descripcion=?, "
                         "actualizado_en=CURRENT_TIMESTAMP WHERE id=? AND territory=?",
                         (nombre, tipo, lat, lon, foto, desc, int(lid), ter))
        if not cur.rowcount:
            return jsonify({"status": "error", "message": "No existe ese lugar."}), 404
    else:
        lid = db.execute("INSERT INTO lugares (territory, nombre, tipo, lat, lon, foto, descripcion, creado_por) "
                         "VALUES (?,?,?,?,?,?,?,?)", (ter, nombre, tipo, lat, lon, foto, desc, _usuario_nombre())).lastrowid
    db.commit()
    return jsonify({"status": "ok", "id": int(lid), "message": "Lugar guardado."})

