@app.route("/api/official-timeseries")
def api_official_timeseries():
    """Serie histórica de un par (territorio, indicador): solo los años observados +
    real GEIH-year point(s) on file, plus the community's 2026 correction appended
    as the final point. Only returns points that actually exist — no fabricated years."""
    ter = request.args.get("territory","")
    ind = request.args.get("indicator","")
    if not ter or not ind:
        return jsonify({"status":"error","message":"territory e indicator son requeridos"}), 400
    db = get_db()
    points = rows(db.execute(
        "SELECT year,value,source_type,source_label,is_estimate FROM official_timeseries "
        "WHERE territory=? AND indicator=? ORDER BY year ASC", (ter, ind)))
    community = row(db.execute(
        "SELECT community_value,community_source,created_at FROM ci_publicados "
        "WHERE territory=? AND indicator=? ORDER BY created_at DESC LIMIT 1", (ter, ind)))
    if community and community.get("community_value") is not None:
        yr_match = re.search(r"20\d{2}", community.get("created_at") or "")
        points.append({
            "year": int(yr_match.group()) if yr_match else 2026,
            "value": community["community_value"],
            "source_type": "community",
            "source_label": community.get("community_source") or "Comunidad",
            "is_estimate": 0,
        })
    return jsonify(points)

