# ── MODERATION (A2: durable voter ID) ────────────────────────

@app.route("/api/moderation/pending")
def api_mod_pending():
    """Pending queue, with a per-row can_delete hint.

    The viewer's durable id arrives as ?viewer= so anonymous authors can be
    shown their own delete button. author_uid is stripped from every row on
    the way out — the client is told WHETHER it may delete, never WHO owns
    a post, and the DELETE endpoint re-checks independently.
    """
    db = get_db()
    viewer = _owner_uid({"voter": request.args.get("viewer","")})
    items = rows(db.execute("SELECT * FROM contributions WHERE approved=0 ORDER BY created_at"))
    for c in items:
        vs = rows(db.execute("SELECT vote,COUNT(*) n FROM moderation_votes WHERE contribution_id=? GROUP BY vote",(c["id"],)))
        c["approve_count"] = next((v["n"] for v in vs if v["vote"]=="approve"),0)
        c["veto_count"]    = next((v["n"] for v in vs if v["vote"]=="veto"),0)
        c["can_delete"]    = _may_delete_contribution(db, c, viewer)
        me = session.get("username")
        c["es_mia"] = bool(me) and c.get("author_uid") == me
        mv = db.execute("SELECT vote FROM moderation_votes WHERE contribution_id=? AND voter=?",(c["id"],me)).fetchone() if me else None
        c["mi_voto"] = mv[0] if mv else ""
        c.pop("author_uid", None)
    return jsonify({"items": items,
                    "approve_threshold": MOD_APPROVE_THRESHOLD,
                    "veto_threshold": MOD_VETO_THRESHOLD})

@app.route("/api/moderation/vote", methods=["POST"])
@rate_limit(15, 60)
@csrf_required
def api_mod_vote():
    d = request.json or {}
    cid    = d.get("contribution_id")
    reason = d.get("reason","")
    vote   = d.get("vote","")
    # Votar exige una cuenta: un identificador anónimo se renueva con solo
    # borrar los datos del navegador, y tres identificadores inventados
    # bastarían para publicar. Con cuenta, cada persona cuenta una vez.
    if "user_id" not in session:
        return jsonify({"status":"error","login":True,
                        "message":"Inicia sesión o crea una cuenta para votar: así cada persona cuenta una sola vez."}),401
    voter = session["username"]
    if not cid or vote not in ("approve","veto"):
        return jsonify({"status":"error","message":"Datos inválidos"}),400
    db = get_db()
    own = db.execute("SELECT author_uid FROM contributions WHERE id=? AND approved=0",(cid,)).fetchone()
    if not own:
        return jsonify({"status":"error","message":"La contribución ya no está pendiente."}),404
    if own[0] and own[0] == voter:
        return jsonify({"status":"error","message":"No puedes votar tu propia contribución."}),403
    if db.execute("SELECT id FROM moderation_votes WHERE contribution_id=? AND voter=?",(cid,voter)).fetchone():
        return jsonify({"status":"error","message":"Ya votaste sobre esta contribución"}),400
    db.execute("INSERT INTO moderation_votes (contribution_id,voter,vote,reason) VALUES (?,?,?,?)",(cid,voter,vote,reason))
    a = db.execute("SELECT COUNT(*) FROM moderation_votes WHERE contribution_id=? AND vote='approve'",(cid,)).fetchone()[0]
    v = db.execute("SELECT COUNT(*) FROM moderation_votes WHERE contribution_id=? AND vote='veto'",(cid,)).fetchone()[0]
    new_status = None
    if a >= MOD_APPROVE_THRESHOLD:
        # PUBLISH — unconditionally. The veto count is deliberately NOT part
        # of this branch: three approvals publish the story whether it also
        # collected 0 vetoes or 20. The vetoes are still stored and still
        # shown, so the disagreement stays visible in the record.
        db.execute("UPDATE contributions SET approved=1,status='published',approve_count=?,veto_count=? WHERE id=?",(a,v,cid))
        c = row(db.execute("SELECT * FROM contributions WHERE id=?",(cid,)))
        auto_tracker(db,cid,c["territory"],c["title"])
        new_status = "published"
    elif v >= MOD_VETO_THRESHOLD:
        # Reject only when the contribution has NOT reached the approval bar
        # and the objection is decisive. Anything short of that leaves the
        # story in the queue, still able to earn its third approval.
        db.execute("UPDATE contributions SET approved=-1,status='rejected',approve_count=?,veto_count=?,moderator_note=? WHERE id=?",
                   (a,v,reason or "Vetada por la comunidad.",cid))
        new_status = "rejected"
    else:
        db.execute("UPDATE contributions SET approve_count=?,veto_count=? WHERE id=?",(a,v,cid))
    db.commit()
    logger.info(f"Voto: contrib#{cid} voter={voter} vote={vote} a={a} v={v}")
    return jsonify({"status":"success","approve_count":a,"veto_count":v,"new_status":new_status,
                    "approve_threshold":MOD_APPROVE_THRESHOLD,"veto_threshold":MOD_VETO_THRESHOLD,
                    "remaining":max(0,MOD_APPROVE_THRESHOLD-a)})

