# ── VOZ ↔ DATO: AUTOMATIC CONTRIBUTION + DANE TREND ───────────
@app.route("/api/narrative-data/voice-dane-series")
def api_voice_dane_series():
    """Builds an auditable annual comparison for the Voice ↔ Data panel.

    Community series = count of approved contributions by year, optionally
    filtered by territory and category. DANE series = only real rows already
    stored in official_timeseries. No synthetic years or values are created.
    The two series intentionally keep different units because contribution
    volume and an official indicator are different phenomena.
    """
    ter = (request.args.get("territory") or "").strip()
    cat = (request.args.get("category") or "").strip()
    ind = (request.args.get("indicator") or "").strip()
    db = get_db()

    # Community voice: annual volume of approved contributions.
    where = ["approved=1"]
    params = []
    if ter:
        where.append("territory=?"); params.append(ter)
    if cat:
        where.append("category=?"); params.append(cat)
    q = """SELECT substr(created_at,1,4) AS year, COUNT(*) AS contributions
           FROM contributions WHERE """ + " AND ".join(where) + " GROUP BY year ORDER BY year"
    community = rows(db.execute(q, params))

    # DANE: use only actual official time-series rows. If indicator is not
    # supplied, prefer the catalog's education indicator because it is the
    # thesis focus, then fall back to the first catalog indicator.
    if not ind:
        ind = "education"
    dane = []
    if ter:
        dane = rows(db.execute(
            "SELECT year,value,source_type,source_label,is_estimate FROM official_timeseries "
            "WHERE territory=? AND indicator=? ORDER BY year", (ter, ind)))
    else:
        # For all territories, aggregate only when the same indicator/year has
        # real observations. This is an unweighted territorial mean, explicitly
        # labelled as such in the payload.
        dane = rows(db.execute(
            "SELECT year, AVG(value) AS value, COUNT(*) AS territories, "
            "'aggregate' AS source_type, 'DANE — promedio simple de territorios con dato' AS source_label, "
            "MAX(is_estimate) AS is_estimate "
            "FROM official_timeseries WHERE indicator=? GROUP BY year ORDER BY year", (ind,)))

    # Remove estimated points: this comparison must never make a fabricated or
    # proxy baseline look like measured DANE data.
    dane = [r for r in dane if not r.get("is_estimate")]

    return jsonify({
        "status":"success",
        "filters":{"territory":ter,"category":cat,"indicator":ind},
        "community":community,
        "dane":dane,
        "indicator_catalog":[
            {"id":x["field"],"name":x["name"],"unit":x["unit"],"period":x["period"],"source_label":x["source_label"]}
            for x in INDICATOR_CATALOG
        ],
        "note":"Las contribuciones son volumen anual de voces publicadas; el DANE es el valor del indicador seleccionado. No son la misma variable y no deben interpretarse como una correlación causal."
    })

