@app.route("/api/tracker")
def api_tracker():
    db = get_db()
    # COALESCE(contribution_id, -id) keeps every manual (null-contribution) row
    # while collapsing any duplicate auto-tracked cases to a single entry.
    items = rows(db.execute(
        "SELECT * FROM tracker WHERE id IN "
        "(SELECT MIN(id) FROM tracker GROUP BY COALESCE(contribution_id, -id)) "
        "ORDER BY updated_at DESC"))
    for t in items:
        t["actions"] = rows(db.execute("SELECT * FROM institutional_actions WHERE tracker_id=?",(t["id"],)))
        z = row(db.execute("SELECT zona_celda, zona_tipo FROM contributions WHERE id=?", (t.get("contribution_id"),))) if t.get("contribution_id") else None
        t["zona_celda"] = (z or {}).get("zona_celda") or ""
        t["zona_tipo"] = (z or {}).get("zona_tipo") or ""
    return jsonify(items)

@app.route("/api/tracker/<int:tid>", methods=["PATCH"])
@require_role("admin","institutional")
@csrf_required
def api_tracker_update(tid):
    d = request.json or {}
    db = get_db()
    caso = row(db.execute("SELECT * FROM tracker WHERE id=?", (tid,)))
    if not caso:
        return jsonify({"status": "error", "message": "Caso no encontrado"}), 404
    hoy = datetime.now().strftime("%Y-%m-%d")

    def _fecha(campo):
        """None = no se envió; '' = borrar; 'AAAA-MM-DD' validada."""
        if campo not in d:
            return None
        v = str(d.get(campo) or "").strip()[:10]
        if not v:
            return ""
        try:
            datetime.strptime(v, "%Y-%m-%d")
        except ValueError:
            raise ValueError("Fecha no válida (use AAAA-MM-DD)")
        if v > hoy:
            raise ValueError("La fecha no puede ser futura")
        return v

    try:
        notificado = _fecha("notified_at")
        resuelto = _fecha("resolved_at")
    except ValueError as e:
        return jsonify({"status": "error", "message": str(e)}), 400

    estado = d.get("status") or caso["status"]
    # Fechas automáticas cuando nadie las escribe: al enviar el caso a la
    # institución se anota el día de hoy como notificación, y al resolverlo,
    # como resolución. Si se reabre, la fecha de resolución se borra.
    if notificado is None and not caso.get("notified_at") and estado in ("en_proceso", "resuelto"):
        notificado = hoy
    if estado == "resuelto":
        if resuelto is None and not caso.get("resolved_at"):
            resuelto = hoy
    else:
        resuelto = ""
    ini = notificado if notificado not in (None, "") else (caso.get("notified_at") or "")
    fin = resuelto if resuelto is not None else (caso.get("resolved_at") or "")
    if ini and fin and fin < ini:
        return jsonify({"status": "error",
                        "message": "La fecha de resolución no puede ser anterior a la de notificación"}), 400

    db.execute("""UPDATE tracker SET
        status=COALESCE(?,status), notes=COALESCE(?,notes),
        assigned_to=COALESCE(?,assigned_to), institution=COALESCE(?,institution),
        notified_at=COALESCE(?,notified_at), resolved_at=COALESCE(?,resolved_at),
        updated_at=strftime('%Y-%m-%d %H:%M','now') WHERE id=?""",
        (d.get("status"),d.get("notes"),d.get("assigned_to"),d.get("institution"),
         notificado, resuelto, tid))
    db.commit()
    logger.info("Tracker #%s actualizado por %s", tid, session.get("username"))
    return jsonify({"status":"success"})

@app.route("/api/actions", methods=["GET","POST"])
@csrf_required
def api_actions():
    db = get_db()
    if request.method=="POST":
        # Sólo el equipo verificado registra acciones institucionales: son lo
        # que el tablero de Evidencia usa para calificar a cada institución.
        r = db.execute("SELECT role FROM users WHERE id=?", (session.get("user_id"),)).fetchone() \
            if session.get("user_id") else None
        if not r or r[0] not in ("admin","institutional"):
            return jsonify({"status":"error","message":"Acceso no autorizado"}), 403
        d = request.json or {}
        cur = db.execute("INSERT INTO institutional_actions (tracker_id,institution,type,description,status,public_url) VALUES (?,?,?,?,?,?)",
            (d.get("tracker_id"),d.get("institution","CAEDI"),d.get("type","plan"),
             d.get("description",""),d.get("status","planificado"),d.get("public_url","")))
        db.commit(); return jsonify({"status":"success","id":cur.lastrowid})
    return jsonify(rows(db.execute("SELECT * FROM institutional_actions ORDER BY date DESC")))

