# ── FILE UPLOAD ───────────────────────────────────────────────

def duracion_de(ruta):
    """Duración en segundos según ffprobe, o None si no se puede determinar."""
    try:
        r = subprocess.run(
            ["ffprobe", "-v", "error", "-show_entries", "format=duration",
             "-of", "default=noprint_wrappers=1:nokey=1", ruta],
            capture_output=True, text=True, timeout=30)
        return float(r.stdout.strip()) if r.returncode == 0 and r.stdout.strip() else None
    except Exception:
        return None


def limpiar_metadatos(ruta):
    """Quita de un video o audio los metadatos que el teléfono le añade:
    ubicación GPS, modelo del equipo, fecha, nombre del autor. En una denuncia
    la ubicación exacta puede exponer a quien la graba.

    Se copian los flujos sin recodificar (rápido, sin pérdida). Devuelve True si
    el archivo quedó limpio; False si no hay ffmpeg o falló, y en ese caso se
    registra para que el equipo lo sepa.
    """
    base, ext = os.path.splitext(ruta)
    tmp = base + ".limpio" + ext
    cmd = ["ffmpeg", "-y", "-i", ruta, "-map", "0", "-map_metadata", "-1",
           "-map_chapters", "-1", "-c", "copy", "-fflags", "+bitexact"]
    if ext.lower() in (".mp4", ".mov", ".m4a"):
        cmd += ["-movflags", "+faststart"]
    try:
        r = subprocess.run(cmd + [tmp], capture_output=True, text=True, timeout=300)
        if r.returncode == 0 and os.path.exists(tmp) and os.path.getsize(tmp) > 0:
            os.replace(tmp, ruta)
            return True
        logger.warning("No se pudieron quitar los metadatos de %s: %s",
                       os.path.basename(ruta), (r.stderr or "")[-200:])
    except FileNotFoundError:
        logger.warning("ffmpeg no está instalado: %s conserva sus metadatos "
                       "(posible ubicación GPS).", os.path.basename(ruta))
    except Exception as e:
        logger.warning("Limpieza de metadatos falló para %s: %s", os.path.basename(ruta), e)
    finally:
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except OSError: pass
    return False


def recortar_video(ruta, tope=VIDEO_MAX_SEGUNDOS):
    """Deja el video en sus primeros `tope` segundos. Devuelve (recortado, duración).

    Primero se intenta copiar los flujos sin recodificar: es casi instantáneo y
    no pierde calidad, pero corta en el fotograma clave anterior, de modo que el
    resultado puede quedar algo por debajo del minuto. Si esa vía falla —hay
    contenedores que no admiten el corte por copia— se recodifica, que tarda más
    pero siempre funciona.

    Si ffmpeg no está instalado, el archivo se conserva intacto y se devuelve
    la duración real: el reproductor de la página se encarga entonces de
    detener la reproducción en el minuto. La contribución no se pierde nunca por
    esto.
    """
    dur = duracion_de(ruta)
    if dur is None or dur <= tope + 0.5:
        return False, dur
    base, ext = os.path.splitext(ruta)
    tmp = base + ".recorte" + ext
    intentos = [
        ["ffmpeg", "-y", "-i", ruta, "-t", str(tope), "-c", "copy",
         "-movflags", "+faststart", tmp],
        ["ffmpeg", "-y", "-i", ruta, "-t", str(tope), "-c:v", "libx264",
         "-preset", "veryfast", "-crf", "26", "-c:a", "aac",
         "-movflags", "+faststart", tmp],
    ]
    for cmd in intentos:
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
            if r.returncode == 0 and os.path.exists(tmp) and os.path.getsize(tmp) > 0:
                os.replace(tmp, ruta)
                logger.info(f"Video recortado a {tope}s: {os.path.basename(ruta)} "
                            f"(original {dur:.0f}s)")
                return True, min(dur, tope)
        except Exception as e:
            logger.warning(f"Recorte de video falló ({cmd[-1]}): {e}")
        finally:
            if os.path.exists(tmp):
                try: os.remove(tmp)
                except OSError: pass
    logger.warning("No se pudo recortar %s; se conserva completo y el "
                   "reproductor limitará la reproducción a %ds.",
                   os.path.basename(ruta), tope)
    return False, dur


def procesar_video(ruta, tope=VIDEO_MAX_SEGUNDOS):
    """Comprime, recorta y limpia un video en una sola pasada de ffmpeg.

    Resultado: MP4 de hasta `tope` segundos, con el lado mayor en 1280 px como
    máximo (no se agranda lo que ya es menor), H.264 + AAC, sin metadatos y con
    el índice al principio para que empiece a reproducirse antes de bajar
    entero. Devuelve (ruta_final, info).

    Si ffmpeg falta, falla o tarda más de VIDEO_COMPRIMIR_TIMEOUT, se vuelve al
    procedimiento anterior (recorte por copia + limpieza de metadatos): la
    contribución no se pierde nunca por la compresión.
    """
    dur = duracion_de(ruta)
    base, ext = os.path.splitext(ruta)
    salida = base + ".mp4"
    tmp = base + ".comprimido.mp4"
    escala = (f"scale=w=trunc(min(iw\\,iw*{VIDEO_LADO_MAX}/max(iw\\,ih))/2)*2:h=-2")
    cmd = ["ffmpeg", "-y", "-i", ruta, "-t", str(tope),
           "-map", "0:v:0", "-map", "0:a:0?",
           "-vf", escala, "-c:v", "libx264", "-preset", "veryfast", "-crf", "28",
           "-maxrate", "1800k", "-bufsize", "3600k", "-pix_fmt", "yuv420p",
           "-c:a", "aac", "-b:a", "96k",
           "-map_metadata", "-1", "-map_chapters", "-1",
           "-movflags", "+faststart", tmp]
    try:
        antes = os.path.getsize(ruta)
        r = subprocess.run(cmd, capture_output=True, text=True,
                           timeout=VIDEO_COMPRIMIR_TIMEOUT)
        if r.returncode == 0 and os.path.exists(tmp) and os.path.getsize(tmp) > 0:
            os.replace(tmp, salida)
            if salida != ruta:
                try: os.remove(ruta)
                except OSError: pass
            despues = os.path.getsize(salida)
            logger.info("Video comprimido: %s %.1f MB → %.1f MB",
                        os.path.basename(salida), antes / 1e6, despues / 1e6)
            return salida, {"comprimido": True,
                            "recortado": bool(dur and dur > tope + 0.5),
                            "duracion": round(min(dur, tope), 1) if dur else None,
                            "tope_segundos": tope, "metadatos_limpios": True,
                            "mb_original": round(antes / 1e6, 1),
                            "mb_final": round(despues / 1e6, 1)}
        logger.warning("No se pudo comprimir %s: %s", os.path.basename(ruta),
                       (r.stderr or "")[-300:])
    except FileNotFoundError:
        logger.warning("ffmpeg no está instalado: %s se guarda sin comprimir.",
                       os.path.basename(ruta))
    except subprocess.TimeoutExpired:
        logger.warning("La compresión de %s superó %ss; se recorta sin recodificar.",
                       os.path.basename(ruta), VIDEO_COMPRIMIR_TIMEOUT)
    except Exception as e:
        logger.warning("Compresión de video falló para %s: %s", os.path.basename(ruta), e)
    finally:
        if os.path.exists(tmp):
            try: os.remove(tmp)
            except OSError: pass
    recortado, dur2 = recortar_video(ruta, tope)
    return ruta, {"comprimido": False, "recortado": recortado,
                  "duracion": round(dur2, 1) if dur2 else None,
                  "tope_segundos": tope,
                  "metadatos_limpios": limpiar_metadatos(ruta)}


# ── Subida de video por partes ──────────────────────────────────────
# Las partes se guardan fuera de static/, de modo que un archivo a medio subir
# nunca es accesible desde la web.
VIDEO_PARTES_DIR = os.path.join(BASE_DIR, "tmp_subidas")
os.makedirs(VIDEO_PARTES_DIR, exist_ok=True)

def _parte_rutas(uid):
    if not re.fullmatch(r"[0-9a-f]{32}", uid or ""):
        return None, None
    return (os.path.join(VIDEO_PARTES_DIR, uid + ".part"),
            os.path.join(VIDEO_PARTES_DIR, uid + ".json"))

def _limpiar_partes_viejas(horas=6):
    limite = time.time() - horas * 3600
    try:
        for nombre in os.listdir(VIDEO_PARTES_DIR):
            ruta = os.path.join(VIDEO_PARTES_DIR, nombre)
            if os.path.getmtime(ruta) < limite:
                os.remove(ruta)
    except OSError:
        pass

@app.route("/api/upload/video/start", methods=["POST"])
@rate_limit(10, 60)
@csrf_required
def api_video_start():
    d = request.get_json(silent=True) or {}
    nombre = str(d.get("name") or "")
    ext = os.path.splitext(nombre)[1].lower()
    try: total = int(d.get("size") or 0)
    except (TypeError, ValueError): total = 0
    if ext not in VIDEO_EXTS:
        return jsonify({"status": "error", "message": f"Tipo de video no permitido: {ext or 'desconocido'}"}), 415
    if total <= 0:
        return jsonify({"status": "error", "message": "Archivo vacío."}), 400
    if total > VIDEO_MAX_MB * 1024 * 1024:
        return jsonify({"status": "error", "message":
            f"El video pesa {total/1048576:.0f} MB y el máximo es {VIDEO_MAX_MB} MB. "
            "Grábalo en 1080p (no en 4K) o envíalo antes por WhatsApp para reducirlo."}), 413
    _limpiar_partes_viejas()
    uid = secrets.token_hex(16)
    parte, meta = _parte_rutas(uid)
    open(parte, "wb").close()
    with open(meta, "w", encoding="utf-8") as fh:
        json.dump({"ext": ext, "size": total, "t": time.time()}, fh)
    return jsonify({"status": "success", "id": uid,
                    "chunk_size": VIDEO_PARTE_MB * 1024 * 1024})

@app.route("/api/upload/video/chunk", methods=["POST"])
@rate_limit(120, 60)
@csrf_required
def api_video_chunk():
    uid = request.args.get("id", "")
    parte, meta = _parte_rutas(uid)
    if not parte or not os.path.exists(meta):
        return jsonify({"status": "error", "message": "Subida no encontrada o caducada."}), 404
    try: offset = int(request.args.get("offset", "-1"))
    except ValueError: offset = -1
    info = json.load(open(meta, encoding="utf-8"))
    actual = os.path.getsize(parte)
    datos = request.get_data(cache=False)
    if offset < actual:
        # Parte ya recibida (reintento tras un corte): se confirma sin escribir.
        if offset >= 0 and offset + len(datos) <= actual:
            return jsonify({"status": "success", "received": actual})
        return jsonify({"status": "error", "message": "Parte fuera de orden.", "received": actual}), 409
    if offset > actual:
        return jsonify({"status": "error", "message": "Parte fuera de orden.", "received": actual}), 409
    if not datos or len(datos) > VIDEO_PARTE_MB * 1024 * 1024 or actual + len(datos) > info["size"]:
        return jsonify({"status": "error", "message": "Parte no válida."}), 400
    with open(parte, "ab") as fh:
        fh.write(datos)
    os.utime(meta)
    return jsonify({"status": "success", "received": actual + len(datos)})

@app.route("/api/upload/video/finish", methods=["POST"])
@rate_limit(10, 60)
@csrf_required
def api_video_finish():
    d = request.get_json(silent=True) or {}
    parte, meta = _parte_rutas(str(d.get("id") or ""))
    if not parte or not os.path.exists(meta):
        return jsonify({"status": "error", "message": "Subida no encontrada o caducada."}), 404
    info = json.load(open(meta, encoding="utf-8"))
    if os.path.getsize(parte) != info["size"]:
        return jsonify({"status": "error", "message": "El video no llegó completo; vuelve a intentarlo."}), 400
    nm = datetime.now().strftime("%Y%m%d") + "_" + secrets.token_hex(8) + info["ext"]
    destino = os.path.join(UPLOAD_FOLDER, nm)
    os.replace(parte, destino)
    try: os.remove(meta)
    except OSError: pass
    if duracion_de(destino) is None and shutil.which("ffprobe"):
        # ffprobe está disponible y no reconoce el archivo: no es un video.
        try: os.remove(destino)
        except OSError: pass
        return jsonify({"status": "error", "message": "El archivo no es un video válido."}), 415
    final, extra = procesar_video(destino)
    url = f"/gallery/{os.path.basename(final)}"
    logger.info(f"Video subido por partes: {os.path.basename(final)} → {url}")
    salida = {"status": "success", "url": url, "media_type": "video"}
    salida.update(extra)
    return jsonify(salida)


@app.route("/api/upload", methods=["POST"])
@rate_limit(10, 60)
@csrf_required
def api_upload_recortado():
    if "file" not in request.files: return jsonify({"status":"error"}),400
    f  = request.files["file"]
    ok, mt, err = validate_upload(f)
    if not ok:
        logger.warning(f"Upload rechazado: {f.filename!r} — {err}")
        return jsonify({"status":"error","message":err}),415
    _ext = os.path.splitext(f.filename or "")[1].lower()
    # Nota de voz de la Red Comunitaria: el navegador graba en WebM/Opus
    # (Chrome, Android) o MP4/AAC (Safari, iPhone). Es audio aunque la
    # extensión sea de video, y nunca pasa por el recorte de videos.
    voz = request.args.get("kind") == "voz" and _ext in (".webm", ".ogg", ".m4a", ".mp4", ".aac")
    if voz:
        mt = "audio"
        if _ext == ".mp4":
            _ext = ".m4a"
        if request.content_length and request.content_length > 8 * 1024 * 1024:
            return jsonify({"status":"error","message":"La nota de voz es demasiado larga."}),413
    nm = datetime.now().strftime("%Y%m%d") + "_" + secrets.token_hex(8) + _ext
    dest = request.args.get("dest","gallery")
    if dest == "profile":
        profile_dir = os.path.join(STATIC_FOLDER,"gallery","profiles")
        os.makedirs(profile_dir, exist_ok=True)
        save_path = os.path.join(profile_dir, nm)
        f.save(save_path)
        url = f"/gallery/profiles/{nm}"
        if session.get("username"):
            try:
                db_ = get_db()
                db_.execute("INSERT OR IGNORE INTO user_photos (username,url,kind) VALUES (?,?,?)",
                            (session["username"], url, "portada" if request.args.get("kind") == "portada" else "perfil"))
                db_.commit()
            except Exception as e:
                logger.warning(f"user_photos: {e}")
    else:
        save_path = os.path.join(UPLOAD_FOLDER, nm)
        f.save(save_path)
        url = f"/gallery/{nm}"
        if mt == "video" and not voz:
            save_path, extra = procesar_video(save_path)
            nm = os.path.basename(save_path)
            url = f"/gallery/{nm}"
        if mt == "audio":
            extra = {"metadatos_limpios": limpiar_metadatos(save_path)}
        if mt == "foto":
            stem = os.path.splitext(nm)[0]
            canonical, widths = process_image_upload(save_path, stem)
            if canonical:
                url = f"/gallery/{canonical}"
                # El original conserva el EXIF, así que se elimina en cuanto
                # existe una derivada limpia. No es una copia de seguridad:
                # es exactamente el archivo que no queremos guardar.
                try: os.remove(save_path)
                except OSError: pass
    logger.info(f"Archivo subido: {nm} ({mt}) → {url}")
    salida = {"status":"success","url":url,"media_type":mt}
    salida.update(locals().get("extra") or {})
    return jsonify(salida)

