@app.route("/api/aliados/<int:aid>/estado", methods=["POST"])
@require_role("admin")
@csrf_required
def api_aliado_estado(aid):
    d = request.json or {}
    estado = d.get("estado", "")
    if estado not in ("aprobado", "rechazado", "pausado", "pendiente"):
        return jsonify({"status": "error", "message": "Estado no válido"}), 400
    desde = (d.get("desde") or "")[:10]; hasta = (d.get("hasta") or "")[:10]
    for f_ in (desde, hasta):
        if f_ and not re.match(r"^\d{4}-\d{2}-\d{2}$", f_):
            return jsonify({"status": "error", "message": "Fechas en formato AAAA-MM-DD"}), 400
    db = get_db()
    a = row(db.execute("SELECT * FROM aliados WHERE id=?", (aid,)))
    if not a:
        return jsonify({"status": "error"}), 404
    if a.get("permanente"):
        return jsonify({"status": "error", "message": "Es un aliado permanente: no tiene periodo ni se pausa desde aquí."}), 400
    nota = sanitise(d.get("nota", ""), 300)
    db.execute("UPDATE aliados SET estado=?, desde=?, hasta=?, nota=?, aprobado_por=?, aprobado_en=CURRENT_TIMESTAMP WHERE id=?",
               (estado, desde, hasta, nota, session.get("username", ""), aid))
    db.commit()
    if estado in ("aprobado", "rechazado") and a["contacto"]:
        _send_mail(a["contacto"], "OnLife Afro | tu solicitud de aliado",
                   (f"Tu organización «{a['nombre']}» fue aprobada como aliada de OnLife Afro"
                    + (f" desde el {desde}" if desde else "") + (f" hasta el {hasta}" if hasta else "") + ".") if estado == "aprobado" else
                   (f"Tu solicitud para «{a['nombre']}» no fue aprobada." + (f" Motivo: {nota}" if nota else "")),
                   tag="aliados")
    return jsonify({"status": "success"})

