@app.route("/verificar-correo")
def verificar_correo():
    token = request.args.get("token","")
    db = get_db()
    v = row(db.execute("SELECT * FROM email_verifications WHERE token_hash=? AND used=0",
                       (hashlib.sha256(token.encode()).hexdigest(),)))
    ok = bool(v) and v["expires_at"] >= datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if ok:
        u = row(db.execute("SELECT email FROM users WHERE id=?", (v["user_id"],)))
        ok = bool(u) and (u["email"] or "").lower() == v["email"].lower()
    if ok:
        db.execute("UPDATE users SET email_verified=1 WHERE id=?", (v["user_id"],))
        db.execute("UPDATE email_verifications SET used=1 WHERE id=?", (v["id"],))
        db.commit()
    return redirect("/?correo=" + ("verificado" if ok else "invalido"))

# ── COMMUNITY: PEOPLE TO FOLLOW / FOLLOWERS ──────────────────
@app.route("/api/users")
def api_users():
    """Registered users to discover and follow (excludes the current user)."""
    db = get_db()
    me = session.get("user_id")
    rows_ = rows(db.execute(
        "SELECT id, username, name, role, territory, profile_pic, bio FROM users "
        "ORDER BY (profile_pic!='') DESC, created_at DESC LIMIT 60"))
    # Map of who the current user already follows.
    following = set()
    if me:
        following = {r["following_id"] for r in rows(
            db.execute("SELECT following_id FROM followers WHERE follower_id=?", (me,)))}
    out = []
    for u in rows_:
        if me and u["id"] == me:
            continue
        fc = db.execute("SELECT COUNT(*) FROM followers WHERE following_id=?", (u["id"],)).fetchone()[0]
        u["followers"]    = fc
        u["is_following"] = u["id"] in following
        out.append(u)
    return jsonify({"status":"success", "users": out})


def _fotos_de_aportes(db, username, solo_publicadas=True):
    """Fotos de las historias de una persona (portada y galería), más recientes primero."""
    q = ("SELECT id, title, media_url, media_type, media_gallery, created_at FROM contributions "
         "WHERE author_uid=?" + (" AND approved=1" if solo_publicadas else "") + " ORDER BY created_at DESC LIMIT 80")
    out = []
    for c in rows(db.execute(q, (username,))):
        urls = []
        try:
            urls = [u for u in json.loads(c.get("media_gallery") or "[]") if isinstance(u, str)]
        except ValueError:
            pass
        mu = c.get("media_url") or ""
        if mu and (c.get("media_type") == "foto" or re.search(r"\.(jpe?g|png|webp|gif)$", mu, re.I)) and mu not in urls:
            urls.insert(0, mu)
        for u in urls:
            if re.search(r"\.(jpe?g|png|webp|gif)(\?|$)", u, re.I) or "/gallery/" in u:
                out.append({"url": u, "kind": "historia", "title": c.get("title") or "", "contribution_id": c["id"],
                            "created_at": c.get("created_at") or ""})
    return out

@app.route("/api/users/<int:uid>/photos")
def api_user_photos(uid):
    """Solo las fotos de esa persona. Quien mira su propio perfil ve también sus
    fotos de perfil anteriores y las de historias aún en moderación; los demás,
    solo lo publicado y las imágenes de perfil y portada vigentes."""
    db = get_db()
    u = row(db.execute("SELECT id, username, profile_pic, cover_pic FROM users WHERE id=?", (uid,)))
    if not u:
        return jsonify({"status": "error", "message": "No existe"}), 404
    es_yo = session.get("user_id") == uid
    fotos, vistos = [], set()
    def add(f):
        if f["url"] and f["url"] not in vistos:
            vistos.add(f["url"]); fotos.append(f)
    if u.get("profile_pic"):
        add({"url": u["profile_pic"], "kind": "perfil", "current": True})
    if u.get("cover_pic"):
        add({"url": u["cover_pic"], "kind": "portada", "current": True})
    if es_yo:
        for f in rows(db.execute("SELECT url, kind, created_at FROM user_photos WHERE username=? ORDER BY id DESC LIMIT 60",
                                 (u["username"],))):
            add(f)
    for f in _fotos_de_aportes(db, u["username"], solo_publicadas=not es_yo):
        add(f)
    return jsonify({"status": "success", "is_me": es_yo, "photos": fotos[:120]})

@app.route("/api/users/<int:uid>")
def api_user_profile(uid):
    """Public profile of a single user — shown when you click to follow them."""
    db = get_db()
    u = row(db.execute(
        "SELECT id, username, name, role, territory, profile_pic, cover_pic, bio, email, phone, show_contact, "
        "occupation, organization, experience, email_verified, created_at "
        "FROM users WHERE id=?", (uid,)))
    if not u:
        return jsonify({"status":"error","message":"Usuario no encontrado"}), 404
    # Antes el correo de cada persona se publicaba siempre. Ahora sólo si ella
    # lo decide en su perfil (la fecha de nacimiento nunca sale del servidor).
    if not u.pop("show_contact", 0) and session.get("user_id") != uid:
        u["email"] = ""; u["phone"] = ""
    u["email_verified"] = bool(u.get("email_verified"))
    u["followers"] = db.execute("SELECT COUNT(*) FROM followers WHERE following_id=?", (uid,)).fetchone()[0]
    u["following"] = db.execute("SELECT COUNT(*) FROM followers WHERE follower_id=?",  (uid,)).fetchone()[0]
    me = session.get("user_id")
    u["is_following"] = bool(me) and bool(db.execute(
        "SELECT 1 FROM followers WHERE follower_id=? AND following_id=?", (me, uid)).fetchone())
    u["is_me"] = (me == uid)
    u["online"] = uid in _en_linea(db)
    ok, motivo = _puede_llamar(db, me, uid) if me else (False, "Inicia sesión para llamar")
    u["can_call"], u["call_reason"] = ok, ("" if ok else motivo)
    okm, motm = _puede_escribir(db, me, uid) if me else (False, "Inicia sesión para escribir")
    u["can_message"], u["message_reason"] = okm, ("" if okm else motm)
    # How many published contributions this user has authored (by name/username).
    u["contributions"] = db.execute(
        "SELECT COUNT(*) FROM contributions WHERE status='published' AND (author=? OR author=?)",
        (u["name"], u["username"])).fetchone()[0]
    return jsonify({"status":"success","user":u})


@app.route("/api/follow", methods=["POST"])
@csrf_required
def api_follow():
    """Toggle following another user. Requires a logged-in account."""
    if "user_id" not in session:
        return jsonify({"status":"error","message":"Inicia sesión para seguir a otras personas"}), 401
    d = request.json or {}
    try:
        target = int(d.get("user_id"))
    except (TypeError, ValueError):
        return jsonify({"status":"error","message":"Usuario inválido"}), 400
    me = session["user_id"]
    if target == me:
        return jsonify({"status":"error","message":"No puedes seguirte a ti mismo"}), 400
    db = get_db()
    if not db.execute("SELECT 1 FROM users WHERE id=?", (target,)).fetchone():
        return jsonify({"status":"error","message":"Usuario no encontrado"}), 404
    existing = db.execute(
        "SELECT id FROM followers WHERE follower_id=? AND following_id=?", (me, target)).fetchone()
    if existing:
        db.execute("DELETE FROM followers WHERE id=?", (existing[0],))
        following = False
    else:
        db.execute("INSERT OR IGNORE INTO followers (follower_id, following_id) VALUES (?,?)", (me, target))
        following = True
        me_row = row(db.execute("SELECT username,name FROM users WHERE id=?", (me,)))
        target_row = row(db.execute("SELECT username FROM users WHERE id=?", (target,)))
        if me_row and target_row:
            notify(db, target_row["username"], "follow", me_row.get("name") or me_row["username"],
                   f"{me_row.get('name') or me_row['username']} empezó a seguirte", "dashboard")
    db.commit()
    count = db.execute("SELECT COUNT(*) FROM followers WHERE following_id=?", (target,)).fetchone()[0]
    return jsonify({"status":"success", "following": following, "followers": count})


@app.route("/api/social")
def api_social():
    """Social graph for the logged-in user, split into three buckets so the
    home page can render them separately:
      • following   — people I follow (shown as 'followed' profiles, no + button)
      • followers   — people who follow me, with their details + follow-back state
      • suggestions — everyone else I could follow (this is where the + lives)
    Each entry carries enough detail to render a rich profile preview.
    """
    db = get_db()
    me = session.get("user_id")
    online = _en_linea(db)

    def _decorate(u, following_set):
        """Attach follower count, contribution count and is_following flag,
        plus whether the person is online and whether I may call them."""
        u["online"] = u["id"] in online
        u["can_call"] = bool(me) and _puede_llamar(db, me, u["id"])[0]
        u["can_message"] = bool(me) and _puede_escribir(db, me, u["id"])[0]
        u["followers"] = db.execute(
            "SELECT COUNT(*) FROM followers WHERE following_id=?", (u["id"],)).fetchone()[0]
        u["contributions"] = db.execute(
            "SELECT COUNT(*) FROM contributions WHERE approved=1 AND (author=? OR author=?)",
            (u.get("name"), u.get("username"))).fetchone()[0]
        u["is_following"] = u["id"] in following_set
        return u

    cols = "id, username, name, role, territory, profile_pic, cover_pic, bio, occupation, organization, email_verified"

    # Not logged in: everyone is a suggestion, nothing followed.
    if not me:
        people = rows(db.execute(
            f"SELECT {cols} FROM users ORDER BY (profile_pic!='') DESC, created_at DESC LIMIT 60"))
        for u in people:
            _decorate(u, set())
        return jsonify({"status": "success", "logged_in": False,
                        "following": [], "followers": [], "suggestions": people})

    following_set = {r["following_id"] for r in rows(
        db.execute("SELECT following_id FROM followers WHERE follower_id=?", (me,)))}
    follower_set = {r["follower_id"] for r in rows(
        db.execute("SELECT follower_id FROM followers WHERE following_id=?", (me,)))}

    following, followers, suggestions = [], [], []
    for u in rows(db.execute(
            f"SELECT {cols} FROM users ORDER BY (profile_pic!='') DESC, created_at DESC LIMIT 200")):
        if u["id"] == me:
            continue
        _decorate(u, following_set)
        if u["id"] in following_set:
            following.append(u)
        if u["id"] in follower_set:
            # is_follower means THEY follow ME (used to show "te sigue" + follow-back)
            u_copy = dict(u)
            u_copy["is_follower"] = True
            followers.append(u_copy)
        if u["id"] not in following_set:
            suggestions.append(u)

    return jsonify({"status": "success", "logged_in": True,
                    "following": following, "followers": followers,
                    "suggestions": suggestions})

