# ── GLOBAL SEARCH ─────────────────────────────────────────────
import unicodedata as _ud

def _search_norm(s):
    """Lowercase + strip diacritics so 'Chocó'/'choco'/'CHOCO' all match.
    Used both for the query and (via a registered SQLite function) for the
    stored columns, making search accent- and case-insensitive."""
    if s is None:
        return ""
    s = str(s)
    nfkd = _ud.normalize("NFKD", s)
    return "".join(c for c in nfkd if not _ud.combining(c)).lower()

@app.route("/api/search")
def api_search():
    q = sanitise(request.args.get("q",""), 200).strip()
    if len(q) < 2:
        return jsonify({"results":[],"query":q})
    ter = request.args.get("territory","")
    db  = get_db()
    # Register the normaliser on this connection so SQL can normalise columns.
    db.create_function("noacc", 1, _search_norm)
    like = f"%{_search_norm(q)}%"          # query normalised the same way
    results = []
    # Contributions
    sql = ("SELECT id,title,body,territory,category,author,created_at,'contribution' as type "
           "FROM contributions WHERE approved=1 AND "
           "(noacc(title) LIKE ? OR noacc(body) LIKE ? OR noacc(author) LIKE ? OR noacc(territory) LIKE ?)")
    params = [like,like,like,like]
    if ter: sql+=" AND territory=?"; params.append(ter)
    for r in rows(db.execute(sql+" LIMIT 20", params)):
        r["excerpt"] = r["body"][:120]+"..." if len(r.get("body",""))>120 else r.get("body","")
        results.append(r)
    # Indicators
    sql3 = ("SELECT id,indicator,evidence_body,territory,layer,'indicator' as type "
            "FROM ci_publicados WHERE noacc(indicator) LIKE ? OR noacc(evidence_body) LIKE ?")
    for r in rows(db.execute(sql3+" LIMIT 10",[like,like])):
        r["title"] = r.get("indicator","")
        r["excerpt"] = r.get("evidence_body","")[:120]
        results.append(r)
    # Tracker
    sql4 = ("SELECT id,title,notes,territory,status,'tracker' as type "
            "FROM tracker WHERE noacc(title) LIKE ? OR noacc(notes) LIKE ?")
    for r in rows(db.execute(sql4+" LIMIT 10",[like,like])):
        r["excerpt"] = r.get("notes","")[:120]
        results.append(r)
    results.sort(key=lambda x: x.get("created_at","") or x.get("date",""), reverse=True)
    return jsonify({"results": results[:40], "query": q, "total": len(results)})

# ── CSV EXPORT ────────────────────────────────────────────────
def _csv_safe(v):
    """Neutralise spreadsheet formula injection.

    A CSV cell beginning with = + - @ (or a leading tab/CR) is executed as
    a formula by Excel and LibreOffice. This file is written by community
    members and opened by researchers and institutions, so a contribution
    titled `=HYPERLINK(...)` must arrive as text, not as a live formula.
    """
    if v is None:
        return ""
    t = str(v)
    if t[:1] in ("=", "+", "-", "@", "\t", "\r"):
        return "'" + t
    return t

def _valid_territory(slug):
    """Only accept a slug we actually know. Anything else is dropped."""
    if not slug:
        return None
    if slug in TERRITORIES:
        return slug
    if any(d["slug"] == slug for d in DEPARTMENTS):
        return slug
    return None

@app.route("/api/export/csv")
def api_export_csv():
    import io
    kind = request.args.get("type","contributions")
    ter  = _valid_territory(request.args.get("territory","").strip())
    db   = get_db()
    output = io.StringIO()
    import csv as csv_mod
    if kind == "contributions":
        # Parameterised — the filter value is bound, never concatenated.
        if ter:
            items = rows(db.execute("SELECT * FROM contributions WHERE approved=1 AND territory=? "
                                    "ORDER BY created_at DESC", (ter,)))
        else:
            items = rows(db.execute("SELECT * FROM contributions WHERE approved=1 "
                                    "ORDER BY created_at DESC"))
        if not items: return jsonify({"status":"error","message":"No data"}),404
        items = [{k: v for k, v in it.items() if k not in _CLAVES_PRIVADAS} for it in items]
        w = csv_mod.DictWriter(output, fieldnames=items[0].keys())
        w.writeheader()
        w.writerows({k: _csv_safe(v) for k, v in it.items()} for it in items)
        fname = f"onlife_contributions{'_'+ter if ter else ''}.csv"
    elif kind == "indicators":
        if ter:
            items = rows(db.execute("SELECT * FROM ci_publicados WHERE territory=? "
                                    "ORDER BY created_at DESC", (ter,)))
        else:
            items = rows(db.execute("SELECT * FROM ci_publicados "
                                    "ORDER BY created_at DESC"))
        if not items: return jsonify({"status":"error","message":"No data"}),404
        items = [{k: v for k, v in it.items() if k not in _CLAVES_PRIVADAS} for it in items]
        w = csv_mod.DictWriter(output, fieldnames=items[0].keys())
        w.writeheader()
        w.writerows({k: _csv_safe(v) for k, v in it.items()} for it in items)
        fname = f"onlife_indicators{'_'+ter if ter else ''}.csv"
    else:
        return jsonify({"status":"error","message":"type must be contributions|indicators"}),400
    return Response(output.getvalue(), mimetype="text/csv",
        headers={"Content-Disposition":f"attachment;filename={fname}"})

# ── TERRITORY REPORT (JSON for frontend PDF generation) ───────
@app.route("/api/department-summary/<slug>")
def api_department_summary(slug):
    """Lightweight KPI summary for ANY territory/department slug — unlike
    /api/territory/<slug>/report this isn't limited to the 7 core NARP
    territories, since contributions can be tagged with any of the 33
    Colombian departments too (see DEPARTMENTS)."""
    db = get_db()
    name = None
    icon = ""
    if slug in TERRITORIES:
        name = TERRITORIES[slug]["name"]; icon = TERRITORIES[slug].get("icon","")
    else:
        dep = next((d for d in DEPARTMENTS if d["slug"] == slug), None)
        if dep: name = dep["name"]
    if not name:
        return jsonify({"status":"error","message":"Departamento no reconocido"}), 404
    contributions = db.execute("SELECT COUNT(*) FROM contributions WHERE territory=? AND approved=1",(slug,)).fetchone()[0]
    with_geo      = db.execute("SELECT COUNT(*) FROM contributions WHERE territory=? AND approved=1 AND lat IS NOT NULL",(slug,)).fetchone()[0]
    indicators    = db.execute("SELECT COUNT(*) FROM ci_publicados WHERE territory=?",(slug,)).fetchone()[0]
    # "Voces" = testimonios grabados (audio o vídeo) de ese territorio.
    voices        = db.execute("SELECT COUNT(*) FROM contributions WHERE territory=? AND approved=1 "
                               "AND media_type IN ('audio','video')",(slug,)).fetchone()[0]
    undercounts   = db.execute("SELECT COUNT(*) FROM ci_publicados WHERE territory=? AND direction='undercount'",(slug,)).fetchone()[0]
    resolved      = db.execute("SELECT COUNT(*) FROM tracker WHERE territory=? AND status='resuelto'",(slug,)).fetchone()[0]
    pending       = db.execute("SELECT COUNT(*) FROM tracker WHERE territory=? AND status!='resuelto'",(slug,)).fetchone()[0]
    # Full DANE/GEIH ↔ comunidad pairs for this department, so the map's heat
    # panel can show real indicator gauges, not just activity counts.
    indicator_rows = rows(db.execute(
        "SELECT id,territory,indicator,layer,official_value,official_source,community_value,"
        "community_source,difference,direction,evidence_body,created_at "
        "FROM ci_publicados WHERE territory=? ORDER BY created_at DESC",(slug,)))
    return jsonify({
        "slug": slug, "name": name, "icon": icon,
        "contributions": contributions, "with_geo": with_geo, "voices": voices,
        "indicators": indicators, "undercounts": undercounts,
        "resolved": resolved, "pending": pending,
        "has_official_data": slug in TERRITORIES,
        "indicator_rows": indicator_rows,
    })

@app.route("/api/territory/<slug>/report")
def api_territory_report(slug):
    if slug not in TERRITORIES:
        return jsonify({"status":"error","message":"Territorio no válido"}),404
    db = get_db()
    ter = TERRITORIES[slug]
    contributions = rows(db.execute("SELECT * FROM contributions WHERE territory=? AND approved=1 ORDER BY created_at DESC",(slug,)))
    indicators    = rows(db.execute("SELECT * FROM ci_publicados WHERE territory=? ORDER BY created_at DESC",(slug,)))
    tracker_items = rows(db.execute("SELECT * FROM tracker WHERE territory=? ORDER BY updated_at DESC",(slug,)))
    return jsonify({
        "territory": ter,
        "slug": slug,
        "generated": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "contributions": contributions,
        "indicators": indicators,
        "tracker": tracker_items,
        "summary": {
            "total_contributions": len(contributions),
            "total_indicators": len(indicators),
            "undercounts": len([i for i in indicators if i.get("direction")=="undercount"]),
            "overcounts":  len([i for i in indicators if i.get("direction")=="overcount"]),
            "resolved_cases": len([t for t in tracker_items if t.get("status")=="resuelto"]),
        }
    })

