@app.route("/api/compare")
def api_compare():
    t1 = request.args.get("t1","")
    t2 = request.args.get("t2","")
    if not t1 or not t2 or t1 not in TERRITORIES or t2 not in TERRITORIES:
        return jsonify({"status":"error","message":"Provide valid t1 and t2 territory slugs"}),400
    db = get_db()
    def ter_data(slug):
        base = dict(TERRITORIES[slug])
        base["slug"] = slug
        base["contributions"] = db.execute("SELECT COUNT(*) FROM contributions WHERE territory=? AND approved=1",(slug,)).fetchone()[0]
        base["interviews"]    = db.execute("SELECT COUNT(*) FROM tracker WHERE territory=? AND status='en_proceso'",(slug,)).fetchone()[0]
        base["indicators"]    = db.execute("SELECT COUNT(*) FROM ci_publicados WHERE territory=?",(slug,)).fetchone()[0]
        base["undercounts"]   = db.execute("SELECT COUNT(*) FROM ci_publicados WHERE territory=? AND direction='undercount'",(slug,)).fetchone()[0]
        base["resolved"]      = db.execute("SELECT COUNT(*) FROM tracker WHERE territory=? AND status='resuelto'",(slug,)).fetchone()[0]
        base["indicator_list"]= rows(db.execute("SELECT indicator,official_value,community_value,difference,direction,layer FROM ci_publicados WHERE territory=?",(slug,)))
        return base
    return jsonify({"territory1": ter_data(t1), "territory2": ter_data(t2)})

# ── QR CODE (SVG — no external library needed) ───────────────
@app.route("/api/qr/<int:contribution_id>")
def api_qr(contribution_id):
    """Returns an SVG QR code linking to the contribution story."""
    db = get_db()
    c = row(db.execute("SELECT id,title,territory FROM contributions WHERE id=? AND approved=1",(contribution_id,)))
    if not c: return jsonify({"status":"error"}),404
    base_url = request.host_url.rstrip("/")
    url = f"{base_url}/?story={contribution_id}"
    # QR real y legible por cualquier teléfono. Los textos se escapan: el
    # título lo escribe la comunidad y el SVG se abre en el navegador.
    e = html_lib.escape
    qr = qr_svg(url, 160).replace("<svg ", '<svg x="20" y="30" ', 1)
    titulo = (c['title'] or '')[:30] + ('…' if len(c['title'] or '') > 30 else '')
    svg = f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 250" width="200" height="250">
  <rect width="200" height="250" fill="white"/>
  <text x="100" y="20" text-anchor="middle" font-size="10" font-family="sans-serif" fill="#1A1A1A">OnLife Afro</text>
  {qr}
  <text x="100" y="205" text-anchor="middle" font-size="8" font-family="sans-serif" fill="#1A1A1A">{e(titulo)}</text>
  <text x="100" y="220" text-anchor="middle" font-size="7" font-family="sans-serif" fill="#6B5B4E">{e(url[:60])}</text>
  <text x="100" y="235" text-anchor="middle" font-size="7" font-family="sans-serif" fill="#6B5B4E">{e(str((TERRITORIES.get(c['territory']) or {}).get('name') or c['territory']))} · #{contribution_id}</text>
</svg>"""
    return Response(svg, mimetype="image/svg+xml",
        headers={"Content-Disposition":f"attachment;filename=onlife_story_{contribution_id}_qr.svg"})

