# ── ANONYMOUS DENUNCIA ────────────────────────────────────────
@app.route("/api/denuncia-anonima", methods=["POST"])
@rate_limit(5, 300)
def api_anonymous_report():
    """Fully anonymous submission — no username, no IP stored."""
    d = request.json or {}
    ter   = sanitise(d.get("territory",""), 50)
    title = sanitise(d.get("title",""), 200)
    body  = sanitise(d.get("body",""), 5000)
    if not ter or not title or not body:
        return jsonify({"status":"error","message":"Faltan campos"}),400
    where = resolve_place(ter)
    if not where:
        return jsonify({"status":"error","message":"Lugar no válido"}),400
    ter, place_lat, place_lon, place_name = where
    # Zona vinculada (opcional): sólo el identificador del hexágono de ~1 km,
    # que señala dónde ocurre el problema, no dónde está quien denuncia.
    celda = str(d.get("zona_celda") or "")
    celda = celda if re.fullmatch(r"-?\d{1,7},-?\d{1,7}", celda) else ""
    ztipo = d.get("zona_tipo") if d.get("zona_tipo") in ZONA_TIPOS else ""
    db = get_db()
    cur = db.execute("""INSERT INTO contributions
        (territory,category,type,title,body,author,author_role,lat,lon,place,zona_celda,zona_tipo)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
        (ter, "Denuncia Comunitaria", "denuncia",
         title, body, "Anónimo", "Reporte anónimo",
         place_lat, place_lon, place_name, celda, ztipo if celda else ""))
    db.commit()
    logger.info(f"Denuncia anónima #{cur.lastrowid}: {ter} [IP not logged]")
    return jsonify({"status":"success","id":cur.lastrowid,
                    "message":"Denuncia recibida de forma anónima. Gracias por tu valentía."})

