@app.route("/api/anniversaries")
def api_anniversaries():
    """Returns contributions whose creation date matches today's month/day in past years."""
    db  = get_db()
    today = datetime.now().strftime("%m-%d")
    items = rows(db.execute("""
        SELECT *, (strftime('%Y','now') - strftime('%Y',created_at)) as years_ago
        FROM contributions
        WHERE approved=1
          AND strftime('%m-%d',created_at)=?
          AND strftime('%Y',created_at) != strftime('%Y','now')
        ORDER BY years_ago ASC LIMIT 10""", (today,)))
    return jsonify(items)

