    params = []
    if ter: q+=" AND territory=?"; params.append(ter)
    if cat: q+=" AND category=?"; params.append(cat)
    q+=f" ORDER BY created_at DESC LIMIT {per} OFFSET {(page-1)*per}"
    total = db.execute("SELECT COUNT(*) FROM contributions WHERE approved=1").fetchone()[0]
    return jsonify({"data": rows(db.execute(q,params)), "total":total, "page":page, "per_page":per,
                    "api_version":"1.0","platform":"OnLife Afro","license":"CC BY-SA 4.0"})

