# ── LIVING ARCHIVE (contribution history over time) ───────────
@app.route("/api/archive/timeline")
def api_archive_timeline():
    """Returns contribution counts grouped by month for timeline visualisation."""
    db = get_db()
    ter = request.args.get("territory","")
    q = """SELECT strftime('%Y-%m',created_at) as month,
           COUNT(*) as total,
           SUM(CASE WHEN approved=1 THEN 1 ELSE 0 END) as published,
           territory
           FROM contributions"""
    params = []
    if ter: q+=" WHERE territory=?"; params.append(ter)
    q+=" GROUP BY month,territory ORDER BY month ASC"
    return jsonify(rows(db.execute(q,params)))

@app.route("/api/archive/story/<int:cid>/history")
def api_story_history(cid):
    """Returns a story with its full moderation vote history."""
    db = get_db()
    c = row(db.execute("SELECT * FROM contributions WHERE id=?",(cid,)))
    if not c: return jsonify({"status":"error"}),404
    # Lo no publicado solo lo ven el personal y quien lo envió.
    if c.get("approved") != 1 and _rol_actual() not in ("admin", "institutional") and \
            not ((c.get("author_uid") or "") and c.get("author_uid") == _owner_uid({"voter": request.args.get("viewer", "")})):
        return jsonify({"status":"error","message":"Contenido no disponible"}),404
    votes   = rows(db.execute("SELECT vote,reason,voted_at FROM moderation_votes WHERE contribution_id=? ORDER BY voted_at",(cid,)))
    actions = rows(db.execute("""SELECT ia.* FROM institutional_actions ia
        JOIN tracker t ON ia.tracker_id=t.id WHERE t.contribution_id=?""",(cid,)))
    return jsonify({"contribution":c,"votes":votes,"institutional_actions":actions})

