@app.route("/api/admin/dane/<int:sid>/<accion>", methods=["POST"])
@csrf_required
@require_role("admin")
def api_admin_dane_revisar(sid, accion):
    if dane_auto is None:
        return jsonify({"status": "error", "message": "Falta dane_auto.py."}), 503
    con = dane_auto.conectar(DB_PATH)
    try:
        if accion == "aprobar":
            ok, msg = dane_auto.aprobar(con, sid, _usuario_actual())
        elif accion == "rechazar":
            ok, msg = dane_auto.rechazar(con, sid, _usuario_actual(), (request.get_json(silent=True) or {}).get("nota", ""))
        else:
            return jsonify({"status": "error", "message": "acción no válida"}), 400
    finally:
        con.close()
    pub = None
    if ok:
        load_official_indicators()      # este proceso recarga ya; los demás, por el sello
        if accion == "aprobar":
            pub = _publicacion([sid])
    return jsonify({"status": "ok" if ok else "error", "message": msg, "publicacion": pub}), (200 if ok else 400)

@app.route("/api/admin/dane/lote", methods=["POST"])
@csrf_required
@require_role("admin")
def api_admin_dane_lote():
    """Aprobar o rechazar una publicación completa (todas sus cifras pendientes)."""
    if dane_auto is None:
        return jsonify({"status": "error", "message": "Falta dane_auto.py."}), 503
    d = request.get_json(silent=True) or {}
    accion = d.get("accion")
    try:
        ids = [int(i) for i in (d.get("ids") or [])][:200]
    except (TypeError, ValueError):
        return jsonify({"status": "error", "message": "Lista de cifras no válida."}), 400
    if not ids or accion not in ("aprobar", "rechazar"):
        return jsonify({"status": "error", "message": "Indica las cifras y la acción."}), 400
    con = dane_auto.conectar(DB_PATH)
    try:
        if accion == "aprobar":
            hechos, errores = dane_auto.aprobar_lote(con, ids, _usuario_actual())
        else:
            hechos, errores = dane_auto.rechazar_lote(con, ids, _usuario_actual(), d.get("nota", ""))
    finally:
        con.close()
    pub = None
    if hechos:
        load_official_indicators()
        if accion == "aprobar":
            pub = _publicacion([h["id"] for h in hechos])
    ok = bool(hechos)
    msg = (f"{len(hechos)} cifra(s) {'aprobada(s) y publicada(s)' if accion == 'aprobar' else 'rechazada(s)'}."
           + (f" {len(errores)} no se pudieron procesar: {errores[0]['mensaje']}" if errores else ""))
    return jsonify({"status": "ok" if ok else "error", "message": msg, "hechos": hechos,
                    "errores": errores, "publicacion": pub}), (200 if ok else 400)


# ── OnLife Afro 2.0 · objeto de estado de un dato y pasaporte de fuente ──
_DONDE_SE_VE = {   # vistas públicas que leen la celda principal de cada indicador
    "tarjeta": "Tarjeta de «La cifra y la voz»",
    "barras": "Comparación entre territorios (barras)",
    "mapa": "Mapa de territorios",
    "comparar": "Comparar territorios",
    "fuente": "Fuente y trazabilidad",
}
_CAMPOS_MAPA = ("unemployment", "poverty", "connectivity")
_CAMPOS_COMPARAR = ("unemployment", "poverty", "connectivity", "education", "healthcare")

def estado_dato(ter, field, publico=True):
    """Objeto único de estado de un dato oficial (2.0 · D1/D4): valor, periodo,
    fuente, estado, ámbito, aprobación y procedencia. Lo usan la API pública,
    el pasaporte de fuente y la confirmación de publicación."""
    load_official_indicators()
    t = TERRITORIES.get(ter) or {}
    cat = next((c for c in INDICATOR_CATALOG if c["field"] == field), {})
    v = t.get(field)
    origen = t.get(field + "_origen") or ""
    estado = t.get(field + "_estado") or ("sin_dato" if v is None else "verificado")
    ficha = _OFFICIAL_FICHA.get((ter, field)) or {}
    periodo = str(t.get(field + "_periodo") or t.get(field + "_anio") or "")
    d = {"territory": ter, "territory_name": t.get("name", ter), "field": field,
         "indicator": cat.get("name", field), "unit": cat.get("unit", ""),
         "value": v, "status": estado, "origin": origen, "period": periodo, "period_label": periodo,
         "source": (t.get(field + "_fuente") or cat.get("source_label", "")) if v is not None else "",
         "source_url": (t.get(field + "_url") or ficha.get("url") or (cat.get("source_url", "") if origen == "archivo" else "")) if v is not None else "",
         "scope": (t.get(field + "_ambito") or t.get("ambito") or "") if v is not None else "",
         "approved_at": t.get(field + "_aprobado") or "", "reviewed_by": "", "sheet": "",
         "file_sha256": "", "file_period": "",
         "definition": cat.get("definition", ""), "universe": cat.get("universe", ""),
         "catalog_source_url": cat.get("source_url", "")}
    if origen in ("aprobado_mensual", "aprobado_anual") and dane_auto is not None and os.path.exists(DB_PATH):
        kind = "mensual" if origen == "aprobado_mensual" else "anual"
        try:
            con = dane_auto.conectar(DB_PATH)
            try:
                pp = dane_auto.pasaporte(con, ter, field, kind=kind, period=periodo or None)
            finally:
                con.close()
        except Exception as e:
            pp = None
            logger.warning(f"pasaporte {ter}/{field}: {e}")
        if pp:
            d.update({"sheet": pp.get("sheet") or "", "file_sha256": pp.get("file_sha256") or "",
                      "file_period": pp.get("period_label") or "", "approved_at": pp.get("approved_at") or d["approved_at"],
                      "source_url": pp.get("source_url") or d["source_url"],
                      "period_label": dane_auto.periodo_humano(kind, pp.get("period")),
                      "reviewed_by": "Equipo CAEDI" if publico else (pp.get("approved_by") or "")})
        d["note"] = "Encontrada automáticamente en la publicación oficial y aprobada por el equipo CAEDI antes de mostrarse."
    elif estado == "verificado":
        d["reviewed_by"] = "Equipo OnLife Afro (archivo oficial curado)"
        d["note"] = ("Cifra del archivo de indicadores oficiales que el equipo construye a partir de las "
                     "publicaciones y microdatos del DANE y el MEN.")
    elif estado == "referencia":
        d["reviewed_by"] = "Documentada en la tesis"
        d["note"] = (f"Cifra de referencia ({periodo or 'otro año'}) documentada en la tesis. No es la observación "
                     "actual: ocupa una celda que el archivo oficial deja vacía y se rotula como referencia.")
    else:
        d["note"] = ("No hay una observación oficial válida para este territorio e indicador. "
                     "La plataforma no la reemplaza con otra cifra ni con una estimación.")
    d["source_status"] = "ok" if d["source_url"] else ("sin_enlace" if v is not None else "sin_dato")
    return d

def _publicacion(staging_ids):
    """Qué vistas públicas cambiaron tras aprobar (2.0 · D7), comprobado contra
    la capa pública ya recargada, no supuesto."""
    if dane_auto is None or not staging_ids:
        return None
    con = dane_auto.conectar(DB_PATH)
    try:
        filas = [dict(r) for r in con.execute(
            f"SELECT * FROM dane_staging WHERE id IN ({','.join('?' * len(staging_ids))})", list(staging_ids))]
    finally:
        con.close()
    out = []
    for f in filas:
        if f["kind"] == "aviso":
            out.append({"id": f["id"], "titulo": f["period_label"] or f["source_label"], "confirmado": True,
                        "vistas": [], "nota": "Aviso marcado como atendido. No publica ninguna cifra."})
            continue
        e = estado_dato(f["territory"], f["field"], publico=False)
        en_celda = (e["value"] is not None and abs(float(e["value"]) - float(f["value"])) < 1e-9
                    and e["origin"] in ("aprobado_mensual", "aprobado_anual") and str(e["period"]) == str(f["period"]))
        vistas = []
        if f["kind"] == "mensual":
            vistas += ["Tendencia de 5 y 12 meses (La cifra y la voz)", "Histórico mensual"]
        if en_celda:
            vistas += [_DONDE_SE_VE["tarjeta"], _DONDE_SE_VE["barras"]]
            if f["field"] in _CAMPOS_MAPA:
                vistas.append(_DONDE_SE_VE["mapa"])
            if f["field"] in _CAMPOS_COMPARAR:
                vistas.append(_DONDE_SE_VE["comparar"])
            nota = "Es ahora la cifra principal del indicador."
        elif f["kind"] == "mensual":
            vistas.append("Otras cifras oficiales para este dato")
            nota = ("La celda principal conserva la cifra del archivo oficial (otro ámbito o periodo); "
                    "esta cifra mensual se muestra junto a ella, con su periodo.")
        else:
            nota = "Queda archivada como aprobada; la celda principal tiene una cifra de un año igual o más reciente."
        vistas.append(_DONDE_SE_VE["fuente"])
        out.append({"id": f["id"], "titulo": f"{dane_auto.NOMBRE_CAMPO.get(f['field'], f['field'])} · {f['ambito'] or f['territory']} · "
                                               f"{dane_auto.periodo_humano(f['kind'], f['period'])}",
                    "valor": f["value"], "confirmado": True, "en_celda": en_celda, "vistas": vistas, "nota": nota})
    return out

@app.route("/api/datos/estado")
def api_datos_estado():
    """Estado público de los datos oficiales de un territorio (o de un indicador)."""
    ter = (request.args.get("territory") or "").strip()
    field = (request.args.get("field") or "").strip()
    if ter not in TERRITORIES:
        return jsonify({"status": "error", "message": "territorio no válido"}), 400
    if field:
        if field not in _CAMPOS_OFICIALES:
            return jsonify({"status": "error", "message": "indicador no válido"}), 400
        return jsonify({"status": "ok", "dato": estado_dato(ter, field)})
    return jsonify({"status": "ok", "datos": [estado_dato(ter, f) for f in _CAMPOS_OFICIALES]})

_DANE_EN_CURSO = threading.Event()

@app.route("/api/admin/dane/ejecutar", methods=["POST"])
@csrf_required
@require_role("admin")
def api_admin_dane_ejecutar():
    """Revisión manual inmediata (la automática corre como tarea programada)."""
    if dane_auto is None:
        return jsonify({"status": "error", "message": "Falta dane_auto.py."}), 503
    if _DANE_EN_CURSO.is_set():
        return jsonify({"status": "ok", "message": "Ya hay una revisión en curso."})
    def correr():
        _DANE_EN_CURSO.set()
        try:
            dane_auto.ejecutar(None, DB_PATH)
        finally:
            _DANE_EN_CURSO.clear()
    threading.Thread(target=correr, daemon=True).start()
    return jsonify({"status": "ok", "message": "Revisión iniciada. Vuelve a cargar esta sección en uno o dos minutos."})

@app.route("/api/dane/ventana")
def api_dane_ventana():
    """Cinco meses más recientes aprobados de la desocupación de una ciudad."""
    ter = (request.args.get("territory") or "").strip()
    if ter not in TERRITORIES or dane_auto is None or not os.path.exists(DB_PATH):
        return jsonify({"status": "ok", "puntos": [], "archivo": 0})
    con = dane_auto.conectar(DB_PATH)
    try:
        archivo = dane_auto.meses_archivados(con)
        n_arg = (request.args.get("n") or "").strip()
        n = archivo if n_arg == "todo" else (int(n_arg) if n_arg.isdigit() else dane_auto.VENTANA_MESES)
        n = max(1, min(n or dane_auto.VENTANA_MESES, 120))
        desde = con.execute("SELECT COALESCE(MIN(period),'') FROM dane_aprobados WHERE field='unemployment' AND kind='mensual'").fetchone()[0]
        return jsonify({"status": "ok", "puntos": dane_auto.ventana(con, ter, n=n), "archivo": archivo, "desde": desde})
    finally:
        con.close()

@app.route("/api/metricas/serie")
def api_metricas_serie():
    ter = (request.args.get("territory") or "").strip()
    field = (request.args.get("field") or "").strip()
    if ter not in TERRITORIES or field not in _MX_TERMS:
        return jsonify({"status": "error", "message": "territorio o indicador no válido"}), 400
    db = get_db()
    terms = _MX_TERMS[field]
    donde = [ter] + _MX_AMBITO.get(ter, [])
    filas = rows(db.execute(
        "SELECT territory, indicator, year, value, source_label, is_estimate FROM official_timeseries "
        f"WHERE territory IN ({','.join('?'*len(donde))}) AND value IS NOT NULL ORDER BY year", donde))
    series = {}
    for f in filas:
        if any(t in (f["indicator"] or "").lower() for t in terms):
            series.setdefault((f["territory"], f["indicator"]), []).append(f)
    oficial = None
    if series:
        (t_, nombre), pts = max(series.items(), key=lambda kv: len({p["year"] for p in kv[1]}))
        vistos = {}
        for p_ in pts:
            vistos[p_["year"]] = p_
        oficial = {"indicator": nombre, "ambito": t_, "source": pts[-1]["source_label"],
                   "points": [{"year": y, "value": v["value"], "estimate": bool(v["is_estimate"])}
                              for y, v in sorted(vistos.items())]}
    comunidad = [c for c in rows(db.execute(
        "SELECT indicator, community_value AS value, community_source AS source, created_at "
        "FROM ci_publicados WHERE territory=? ORDER BY created_at", (ter,)))
        if any(t in (c["indicator"] or "").lower() for t in terms)]
    voces = rows(db.execute(
        "SELECT substr(created_at,1,7) AS month, COUNT(*) AS n FROM contributions "
        "WHERE approved=1 AND territory=? AND created_at >= date('now','-11 months','start of month') "
        "GROUP BY month ORDER BY month", (ter,)))
    # Punto oficial actual del territorio (el año que publica la capa oficial):
    # se dibuja aunque no haya serie, para que la línea de tiempo nunca quede vacía.
    t = TERRITORIES.get(ter, {})
    cat = next((c for c in INDICATOR_CATALOG if c["field"] == field), {})
    punto = None
    if t.get(field) is not None:
        anio = t.get(field + "_anio") or cat.get("period") or ""
        m = re.search(r"20\d{2}", str(anio))
        punto = {"year": int(m.group()) if m else None, "value": t.get(field),
                 "ambito": t.get("ambito", ""), "source": t.get(field + "_fuente") or cat.get("source_label", "")}
    # Series de referencia reales (Tabla 20 de la tesis, GEIH 2020-2024): sólo
    # existen para la escolaridad. Buenaventura se lee con su departamento.
    refs = []
    if field == "education":
        tabla = next((r for r in RESULTADOS_TESIS if r.get("id") == "serie_escolaridad"), None)
        if tabla:
            for i, nombre in enumerate(tabla["series"]):
                rol = "ref"
                if ter == "buenaventura" and nombre == "NARP — Valle del Cauca":
                    rol = "own"
                    # No es Buenaventura: es el departamento (incluye Cali). Se dice en el rótulo.
                    nombre = "NARP · Valle del Cauca (ámbito de Buenaventura)"
                elif ter != "buenaventura" and "Valle" in nombre:
                    continue          # el Valle no es contexto para los demás territorios
                refs.append({"name": nombre, "role": rol,
                             "points": [{"year": int(a), "value": v[i]} for a, v in tabla["datos"]]})
            if ter == "buenaventura":
                oficial = None        # la serie propia sale de la Tabla 20, no se duplica
    # El dato propio de Buenaventura (no del departamento): censo 2018, NARP de 25 años y más.
    censo = None
    if field == "education" and ter == "buenaventura":
        h = THESIS_EDUCATION.get("headline", {})
        if h.get("schooling_years") is not None:
            censo = {"year": 2018, "value": h["schooling_years"], "name": "Buenaventura · censo",
                     "source": "DANE — CNPV 2018, población NARP de 25 años y más"}
    return jsonify({"status": "success", "official": oficial, "community": comunidad, "voices": voces,
                    "point": punto, "references": refs, "censo": censo,
                    "ref_universe": "población de 25 años y más · GEIH 2020–2024 (Tabla 20)" if refs else ""})

# QR de cualquier vista pública de la plataforma (un indicador, un gráfico,
# un territorio). Sólo enlaces internos: nunca genera un QR hacia afuera.
@app.route("/api/qr-link")
def api_qr_link():
    u = request.args.get("u", "")
    if not re.fullmatch(r"/\?[A-Za-z0-9=&._%-]{1,160}", u):
        return jsonify({"status": "error"}), 400
    url = request.host_url.rstrip("/") + u
    e = html_lib.escape
    titulo = sanitise(request.args.get("t", "OnLife Afro"), 60)
    sub = sanitise(request.args.get("s", ""), 70)
    qr = qr_svg(url, 160).replace("<svg ", '<svg x="20" y="30" ', 1)
    svg = f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 250" width="200" height="250">
  <rect width="200" height="250" fill="white"/>
  <text x="100" y="20" text-anchor="middle" font-size="10" font-family="sans-serif" fill="#1A1A1A">OnLife Afro · La cifra y la voz</text>
  {qr}
  <text x="100" y="205" text-anchor="middle" font-size="8" font-family="sans-serif" fill="#1A1A1A">{e(titulo)}</text>
  <text x="100" y="220" text-anchor="middle" font-size="7" font-family="sans-serif" fill="#6B5B4E">{e(sub)}</text>
  <text x="100" y="235" text-anchor="middle" font-size="6.5" font-family="sans-serif" fill="#6B5B4E">{e(url[:64])}</text>
</svg>"""
    return Response(svg, mimetype="image/svg+xml")

@app.route("/api/indicators/<int:iid>/validate", methods=["POST"])
@require_role("admin","institutional")
@csrf_required
def api_validate_indicator(iid):
    """Community council formally validates or disputes a DANE correction."""
    d = request.json or {}
    council  = sanitise(d.get("council",""), 200)
    decision = d.get("decision","")   # 'validated' or 'disputed'
    evidence = sanitise(d.get("evidence","") or d.get("note",""), 2000)
    if decision not in ("validated","disputed") or not council:
        return jsonify({"status":"error","message":"Provide council name and decision (validated|disputed)"}),400
    db = get_db()
    ci = row(db.execute("SELECT id,territory,indicator,community_value,enviado_por FROM community_indicators WHERE id=?",(iid,)))
    if not ci:
        return jsonify({"status":"error"}),404
    # Queda registrado quién validó, en nombre de qué consejo y cuándo.
    # Validar publica la corrección; disputarla la retira de la vista pública.
    db.execute("UPDATE community_indicators SET validated=?, validated_by=?, "
               "validated_council=?, validated_at=CURRENT_TIMESTAMP, publicado=?, nota_validacion=? WHERE id=?",
               (1 if decision=="validated" else -1, session.get("username",""), council,
                1 if decision=="validated" else 0, evidence, iid))
    # Quien envió el dato se entera del resultado, con el motivo si no se validó.
    tname = (TERRITORIES.get(ci["territory"]) or {}).get("name") or ci["territory"]
    if decision == "validated":
        msg = f"validó y publicó tu dato «{ci['indicator']}» en {tname}. Ya aparece en Métricas."
    else:
        msg = f"no validó tu dato «{ci['indicator']}» en {tname}" + (f": {evidence}" if evidence else ".")
    notify(db, ci.get("enviado_por") or "", "dato", council, msg, panel="metricas")
    db.commit()
    logger.info(f"Council validation: indicator #{iid} → {decision} by {council}")
    return jsonify({"status":"success","decision":decision,"council":council})

