# ── 3. DATA SOVEREIGNTY / CONSENT LEDGER ─────────────────────
def _contributor_token():
    """Resolve the caller's contributor identity (session user or persistent id).

    El token anónimo es una capacidad sensible: quien lo tiene puede ver,
    exportar o retirar esos aportes. Por eso:
      · sólo se acepta el formato persistent_ con longitud suficiente (nunca
        «user:…», que antes permitía hacerse pasar por una cuenta);
      · viaja en una cabecera o en el cuerpo, no en la URL, para que no quede
        en historiales ni en los registros de acceso del servidor;
      · queda atado al navegador que lo generó (localStorage) y no se muestra
        en ninguna respuesta pública.
    """
    if "username" in session:
        return "user:" + session["username"]
    t = (request.headers.get("X-Contributor-Token") or
         (request.get_json(silent=True) or {}).get("token") or "").strip()
    if t.startswith("persistent_") and 20 <= len(t) <= 120 and re.fullmatch(r"[A-Za-z0-9_]+", t):
        return t
    return None


@app.route("/api/sovereignty/consent", methods=["GET", "POST"])
@csrf_required
def api_sovereignty_consent():
    """Record or read a contributor's consent preferences (their data, their rules)."""
    db = get_db()
    token = _contributor_token()
    if not token:
        return jsonify({"status": "error", "message": "Falta identidad del contribuyente"}), 400
    if request.method == "POST":
        d = request.json or {}
        db.execute("""INSERT INTO consent_ledger
            (contributor_token, consent_public, consent_research, consent_institutional, note)
            VALUES (?,?,?,?,?)
            ON CONFLICT(contributor_token) DO UPDATE SET
              consent_public=excluded.consent_public,
              consent_research=excluded.consent_research,
              consent_institutional=excluded.consent_institutional,
              note=excluded.note, revoked=0, updated_at=CURRENT_TIMESTAMP""",
            (token,
             1 if d.get("public", True) else 0,
             1 if d.get("research", True) else 0,
             1 if d.get("institutional", True) else 0,
             sanitise(d.get("note", ""), 500)))
        db.commit()
        logger.info(f"Consent updated: {token}")
        return jsonify({"status": "success"})
    c = row(db.execute("SELECT * FROM consent_ledger WHERE contributor_token=?", (token,)))
    return jsonify({"status": "success", "consent": c, "token": token})


@app.route("/api/sovereignty/my-data")
def api_sovereignty_my_data():
    """Right to access: everything the platform holds tied to this contributor."""
    token = _contributor_token()
    if not token:
        return jsonify({"status": "error", "message": "Falta identidad del contribuyente"}), 400
    db = get_db()
    owner = token.split("user:")[-1] if token.startswith("user:") else token
    contribs = rows(db.execute(
        "SELECT id,title,territory,category,status,approved,created_at FROM contributions "
        "WHERE author_uid<>'' AND author_uid=?", (owner,)))
    consent = row(db.execute("SELECT * FROM consent_ledger WHERE contributor_token=?", (token,)))
    # Log the access (transparency — the contributor can see who looked).
    db.execute("INSERT INTO data_access_log (contributor_token, action, actor) VALUES (?,?,?)",
               (token, "access", session.get("username", "self")))
    db.commit()
    return jsonify({"status": "success", "token": token,
                    "contributions": contribs, "consent": consent,
                    "count": len(contribs)})


@app.route("/api/sovereignty/export")
def api_sovereignty_export():
    """Right to portability: full machine-readable export of the contributor's data."""
    token = _contributor_token()
    if not token:
        return jsonify({"status": "error", "message": "Falta identidad del contribuyente"}), 400
    db = get_db()
    owner = token.split("user:")[-1] if token.startswith("user:") else token
    payload = {
        "platform": "OnLife Afro",
        "exported_at": datetime.now().isoformat(),
        "contributor_token": token,
        "contributions": [{k: v for k, v in r.items() if k != "author_uid"} for r in rows(db.execute(
            "SELECT * FROM contributions WHERE author_uid<>'' AND author_uid=?", (owner,)))],
        "consent": row(db.execute("SELECT * FROM consent_ledger WHERE contributor_token=?", (token,))),
        "access_log": rows(db.execute(
            "SELECT action,actor,ts FROM data_access_log WHERE contributor_token=? ORDER BY ts DESC", (token,))),
        "rights": "Ley 1581/2012 · OCAP data sovereignty · CC BY-SA 4.0",
    }
    db.execute("INSERT INTO data_access_log (contributor_token, action, actor) VALUES (?,?,?)",
               (token, "export", session.get("username", "self")))
    db.commit()
    return Response(json.dumps(payload, ensure_ascii=False, indent=2, default=str),
                    mimetype="application/json",
                    headers={"Content-Disposition": "attachment;filename=onlife_mis_datos.json"})


@app.route("/api/sovereignty/revoke", methods=["POST"])
@csrf_required
def api_sovereignty_revoke():
    """Right to withdraw: unpublish the contributor's data and mark consent revoked."""
    token = _contributor_token()
    if not token:
        return jsonify({"status": "error", "message": "Falta identidad del contribuyente"}), 400
    db = get_db()
    owner = token.split("user:")[-1] if token.startswith("user:") else token
    cur = db.execute(
        "UPDATE contributions SET approved=0, status='withdrawn' "
        "WHERE author_uid<>'' AND author_uid=? AND status!='withdrawn'", (owner,))
    db.execute("""INSERT INTO consent_ledger (contributor_token, revoked) VALUES (?,1)
        ON CONFLICT(contributor_token) DO UPDATE SET revoked=1, updated_at=CURRENT_TIMESTAMP""",
        (token,))
    db.execute("INSERT INTO data_access_log (contributor_token, action, actor) VALUES (?,?,?)",
               (token, "revoke", session.get("username", "self")))
    db.commit()
    logger.info(f"Consent REVOKED: {token} ({cur.rowcount} contributions withdrawn)")
    return jsonify({"status": "success", "withdrawn": cur.rowcount,
                    "message": "Tus datos fueron retirados de la vista pública."})


@app.route("/api/sovereignty/access-log")
def api_sovereignty_access_log():
    """Transparency: who accessed this contributor's data, and when."""
    token = _contributor_token()
    if not token:
        return jsonify({"status": "error", "message": "Falta identidad del contribuyente"}), 400
    db = get_db()
    log = rows(db.execute(
        "SELECT action,actor,ts FROM data_access_log WHERE contributor_token=? ORDER BY ts DESC LIMIT 100",
        (token,)))
    return jsonify({"status": "success", "log": log})


@app.route("/api/sovereignty/erase", methods=["POST"])
@rate_limit(3, 600)
@csrf_required
def api_sovereignty_erase():
    """Right to erasure ('to be forgotten'): permanently delete the
    contributor's content and de-identify anything that must remain.
    Requires authentication and only ever erases the caller's own data."""
    if "user_id" not in session:
        return jsonify({"status": "error", "message": "Debes iniciar sesión para borrar tus datos."}), 401
    db = get_db()
    user = row(db.execute("SELECT id,username,name FROM users WHERE id=?", (session["user_id"],)))
    if not user:
        return jsonify({"status": "error", "message": "Usuario no encontrado."}), 404
    uname = user["username"]
    token = "user:" + uname
    # Sólo lo que esta cuenta publicó, identificado por su usuario, nunca por
    # el nombre escrito (que cualquiera puede repetir).
    ids = [r[0] for r in db.execute(
        "SELECT id FROM contributions WHERE author_uid<>'' AND author_uid=?", (uname,)).fetchall()]
    for cid in ids:
        for tbl in ("moderation_votes", "likes", "reactions", "comments", "narrative_data_links"):
            db.execute(f"DELETE FROM {tbl} WHERE contribution_id=?", (cid,))
    deleted = db.execute("DELETE FROM contributions WHERE author_uid<>'' AND author_uid=?",
                         (uname,)).rowcount
    db.execute("UPDATE messages SET sender='Anónimo', sender_pic='', sender_role='', sender_uid='' "
               "WHERE sender_uid<>'' AND sender_uid=?", (uname,))
    db.execute("DELETE FROM notifications WHERE recipient=?", (uname,))
    db.execute("DELETE FROM followers WHERE follower_id=? OR following_id=?", (user["id"], user["id"]))
    db.execute("DELETE FROM consent_ledger WHERE contributor_token=?", (token,))
    db.execute("DELETE FROM users WHERE id=?", (user["id"],))
    # Keep a non-PII tombstone for audit integrity, then drop the rest.
    db.execute("DELETE FROM data_access_log WHERE contributor_token=?", (token,))
    db.execute("INSERT INTO data_access_log (contributor_token, action, actor) VALUES (?,?,?)",
               ("erased:" + secrets.token_hex(8), "erase", "self"))
    db.commit()
    session.clear()
    logger.info(f"Data ERASED for a contributor ({deleted} contributions removed)")
    return jsonify({"status": "success", "deleted_contributions": deleted,
                    "message": "Tus datos fueron eliminados permanentemente."})


@app.route("/api/admin/role-requests")
@require_role("admin")
def api_role_requests():
    db = get_db()
    return jsonify(rows(db.execute(
        "SELECT id,username,name,email,territory,created_at FROM users "
        "WHERE requested_role='institutional' ORDER BY created_at")))


@app.route("/api/admin/role-requests/<int:uid>", methods=["POST"])
@require_role("admin")
@csrf_required
def api_role_request_decide(uid):
    d = request.json or {}
    decision = d.get("decision")
    if decision not in ("approve", "deny"):
        return jsonify({"status": "error", "message": "Decisión no válida"}), 400
    db = get_db()
    if not db.execute("SELECT id FROM users WHERE id=? AND requested_role='institutional'",
                      (uid,)).fetchone():
        return jsonify({"status": "error", "message": "Solicitud no encontrada"}), 404
    if decision == "approve":
        db.execute("UPDATE users SET role='institutional', requested_role='' WHERE id=?", (uid,))
    else:
        db.execute("UPDATE users SET requested_role='' WHERE id=?", (uid,))
    db.commit()
    logger.info("Solicitud institucional de user#%s: %s por %s", uid, decision, session.get("username"))
    return jsonify({"status": "success"})


@app.route("/healthz")
def healthz():
    """Liveness/readiness probe for deployment platforms and uptime checks."""
    try:
        db = get_db()
        n = db.execute("SELECT COUNT(*) FROM contributions").fetchone()[0]
        return jsonify({"status": "ok", "database": "ready", "contributions": n,
                        "production": IS_PRODUCTION}), 200
    except Exception as e:
        logger.error(f"Health check failed: {e}")
        return jsonify({"status": "error", "database": "unavailable"}), 503


