# ── Recursos estáticos con caché larga ───────────────────────
# La portada traía 300 KB de CSS y 620 KB de JavaScript dentro del HTML, de
# modo que cada visita volvía a descargarlos. Aquí se separan al arrancar en
# /assets/app.<huella>.css y .js: el navegador los guarda un año y solo los
# vuelve a pedir cuando cambian (cambia la huella). Los datos que la plantilla
# inyectaba dentro del código pasan a un objeto pequeño, window.__OA.
_ASSETS = {}

def _separar_recursos(html):
    import hashlib as _h
    estilos = list(re.finditer(r"<style>(.*?)</style>", html, flags=re.S))
    guiones = list(re.finditer(r"<script>(.*?)</script>", html, flags=re.S))
    css_m = max(estilos, key=lambda m: len(m.group(1)))
    js_m = max(guiones, key=lambda m: len(m.group(1)))
    js = js_m.group(1)
    nombres = sorted(set(re.findall(r"\{\{\s*(\w+)\s*\|\s*tojson\s*\}\}", js)))
    for n in nombres:
        js = re.sub(r"\{\{\s*" + n + r"\s*\|\s*tojson\s*\}\}", "window.__OA." + n, js)
    if "{{" in js or "{%" in js:
        raise ValueError("el JavaScript conserva expresiones de plantilla")
    css = css_m.group(1)
    out = {}
    for tipo, cuerpo, mime in (("css", css, "text/css"), ("js", js, "application/javascript")):
        datos = cuerpo.encode("utf-8")
        huella = _h.sha256(datos).hexdigest()[:12]
        out[tipo] = {"ruta": f"/assets/app.{huella}.{tipo}", "datos": datos,
                     "gz": gzip.compress(datos, 9), "mime": mime, "etag": huella}
    datos_js = "window.__OA={" + ",".join(f"{n}:{{{{ {n} | tojson }}}}" for n in nombres) + "};"
    pagina = (html[:css_m.start()] + f'<link rel="stylesheet" href="{out["css"]["ruta"]}">' +
              html[css_m.end():js_m.start()] + f"<script>{datos_js}</script>"
              f'<script src="{out["js"]["ruta"]}"></script>' + html[js_m.end():])
    return pagina, out

try:
    HTML_PAGINA, _ASSETS = _separar_recursos(HTML)
except Exception as _e:          # nunca dejar la portada sin servir
    logger.warning(f"Recursos sin separar (se sirven en línea): {_e}")
    HTML_PAGINA, _ASSETS = HTML, {}

@app.route("/assets/app.<huella>.<tipo>")
def srv_asset(huella, tipo):
    a = _ASSETS.get(tipo)
    if not a or a["etag"] != huella:
        abort(404)
    gz = "gzip" in request.headers.get("Accept-Encoding", "")
    resp = Response(a["gz"] if gz else a["datos"], mimetype=a["mime"])
    if gz:
        resp.headers["Content-Encoding"] = "gzip"
    resp.headers["Vary"] = "Accept-Encoding"
    resp.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    resp.headers["ETag"] = f'"{a["etag"]}"'
    return resp

