# INIT + RUN
# ─────────────────────────────────────────────────────────────

init_db()


def ensure_admin_account():
    """Make sure exactly one private 'Admin Comboni' account can exist, known
    ONLY to the operator (you). Regular users can never self-promote — the role
    selector hides admin and the server enforces session role on every
    privileged endpoint.

    Credentials come from environment variables:
        ADMIN_USERNAME  (default 'comboni_admin')
        ADMIN_PASSWORD  (if unset, a strong random one is generated and written
                         to the log ONCE so only whoever runs the server sees it)
    Idempotent: if an admin already exists, nothing happens.
    """
    try:
        with app.app_context():
            db = get_db()
            if db.execute("SELECT id FROM users WHERE role='admin' LIMIT 1").fetchone():
                return  # an admin already exists
            username = os.environ.get("ADMIN_USERNAME", "comboni_admin").strip() or "comboni_admin"
            password = os.environ.get("ADMIN_PASSWORD")
            generated = False
            if not password:
                password = secrets.token_urlsafe(12)
                generated = True
            db.execute("INSERT INTO users (username,password,name,role) VALUES (?,?,?,?)",
                       (username, hash_password(password), "Admin CAEDI", "admin"))
            db.commit()
            if generated:
                logger.warning(
                    "Admin Comboni account created — username=%s  password=%s  "
                    "(set ADMIN_USERNAME/ADMIN_PASSWORD env vars to choose your own; "
                    "this password is shown only once, here in the log).",
                    username, password)
            else:
                logger.info("Admin Comboni account created for username=%s (password from env).", username)
    except Exception as e:
        logger.error("Could not ensure admin account: %s", e)


ensure_admin_account()

# Auto-wire the Buenaventura + educación supplement (pipeline + seeding).
# Runs at import time so it also works under WSGI on PythonAnywhere, where the
# __main__ block below never executes. Idempotent and failure-safe.
run_supplement_startup()


def startup_check():
    """Verify DB is accessible and tables exist before serving requests."""
    with app.app_context():
        try:
            db = get_db()
            counts = {
                'contributions': db.execute("SELECT COUNT(*) FROM contributions").fetchone()[0],
                'indicators':    db.execute("SELECT COUNT(*) FROM community_indicators").fetchone()[0],
                'tracker':       db.execute("SELECT COUNT(*) FROM tracker").fetchone()[0],
                'messages':      db.execute("SELECT COUNT(*) FROM messages").fetchone()[0],
            }
            print("  ✅ DB Health Check:")
            for table, count in counts.items():
                print(f"     {table}: {count} rows")
        except Exception as e:
            print(f"  ❌ DB Error: {e}")
            print("  → Reinitialising database...")
            try:
                init_db()
                db = get_db()
                print("  ✅ Database rebuilt:")
                for table in ('contributions','community_indicators','tracker','messages'):
                    n = db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                    print(f"     {table}: {n} rows")
            except Exception as e2:
                print(f"  ❌ Rebuild failed: {e2}")

# ── PythonAnywhere WSGI entry point ──────────────────────────
# In PythonAnywhere WSGI config, point to: application = app
# This init block runs on import, so the DB is always ready.

if __name__ == "__main__":
    try_run_pipeline()   # I2: run GEIH pipeline if available
    startup_check()      # Verify DB before serving
